window.JASTROW_CHUNKS[47]={"18800":{"h":"נִיסָנֵי","r":"N00712","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיסְחָנָא\">נִיסְחָנָא</a></div>","alt":[]},"18801":{"h":"נִיסְקָא","r":"N00713","html":"<div class=\"sense\"> m. (transpos. of <span dir=\"rtl\">ניקסא</span>), v. <a href=\"#\" data-headword=\"נִקְצָא\">נִקְצָא</a></div>","alt":[]},"18802":{"h":"נִיסְרָא","r":"N00714","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִסְרָא\">נִסְרָא</a></div>","alt":[]},"18803":{"h":"ניסרדי","r":"N00715","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*מוּטַרְדֵּי\">מוּטַרְדֵּי</a></div>","alt":[]},"18804":{"h":"ניסרוי","r":"N00716","html":"<div class=\"sense\">, Targ. II Esth. III, 8 <span dir=\"rtl\">בנ׳</span> ed. Lag. a. oth., read: <span dir=\"rtl\">בְּגוֹ סִדְרוֹי</span>, v. <a href=\"#\" data-headword=\"סִדְרָא\">סִדְרָא</a></div>","alt":[]},"18805":{"h":"ניסרפו","r":"N00717","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"לקת\">לקת</a></div>","alt":[]},"18806":{"h":"נִיסְתָא","r":"N00718","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִסֵּיתָא\">נִסֵּיתָא</a></div>","alt":[]},"18807":{"h":"נִיעַ","r":"N00719","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נוּעַ\">נוּעַ</a>) <i>the effort made to remove phlegm, hawking; the phlegm discharged by hawking</i>, contrad. to <a href=\"#\" data-headword=\"כִּיחַ\">כִּיחַ</a>. <span class=\"citation\">Nidd. VII, 1</span> <span dir=\"rtl\">הנ׳ והרוק</span> the phlegm (of an unclean person) and the spittle. <span class=\"citation\">Ib. 55ᵇ</span> <span dir=\"rtl\">ונִיעוֹ</span>; <span class=\"citation\">B. Kam. 3ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּיחַ\">כִּיחַ</a>; a. e.</div>","alt":[]},"18808":{"h":"נְיָעָא","r":"N00720","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נוּעַ\">נוע</a>) [<i>something hanging</i>, cmp. Syr. <span dir=\"rtl\">נעא</span> <i>lobe of the liver</i>, P. Sm. 2403,] </div><div class=\"sense\"><b>1)</b> <i>fat-tail, rump</i>. <span class=\"citation\">Targ. Y. II, Lev. III, 9</span> (h. text <a href=\"#\" data-headword=\"אַלְיָה\">אליה</a>).</div><div class=\"sense\"><b>—2)</b> <i>breast of an animal</i>. Ib. VII, 30 (h. text <a href=\"#\" data-headword=\"חזי\">חזה</a>); [Ar. <a href=\"#\" data-headword=\"נָעָא\">נָעָא</a>, v. Koh. Ar. Compl. s. v.].—Midr. Sam. ch. XIV <span dir=\"rtl\">שוקה ונִיעָה</span> the shoulder and the breast.</div>","alt":["נִיעָא"]},"18809":{"h":"נִיעָה","r":"N00721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְיָעָא\">preced.</a></div>","alt":[]},"18810":{"h":"נִיעוּר","r":"N00722","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָעַר I\">נָעַר</a>) <i>shaking</i> of a garment. <span class=\"citation\">B. Mets. 29ᵇ</span></div>","alt":[]},"18811":{"h":"נֵיעוֹר","r":"N00723","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"עוּר\">עוּר</a></div>","alt":[]},"18812":{"h":"נֵיעוֹת","r":"N00724","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*עוּת\">עוּת</a></div>","alt":[]},"18813":{"h":"נִיעֲנוּעַ","r":"N00725","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נַעֲמיתָא\">נִעֲ׳</a>.</div>","alt":["נִיעֲנֵעַ"]},"18814":{"h":"נִיף","r":"N00726","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Arakh. V, 14</span>, v. <a href=\"#\" data-headword=\"נוֹף II\"><span dir=\"rtl\">נוֹף</span> II</a></div>","alt":[]},"18815":{"h":"נִיפּוּחַ","r":"N00727","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַח\">נָפַח</a>) <i>blowing into</i>. <span class=\"citation\">B. Bath. 79ᵃ</span> (play on <span dir=\"rtl\">נפח</span>, <span class=\"citation\">Num. XXI, 30</span>) <span dir=\"rtl\">אש שאינה צריכה נ׳</span> a fire which needs no fanning (hell); <span class=\"citation\">Yalk. Num. 765</span>.</div>","alt":[]},"18816":{"h":"נִיפּוּל","r":"N00728","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָפַל\">נָפַל</a>) </div><div class=\"sense\"><b>1)</b> <i>falling off</i>, esp. (with ref. to <span class=\"citation\">Lev. XI, 32</span>) <i>of a limb detached from the body</i>. <span class=\"citation\">Ḥull. 74ᵃ</span> <span dir=\"rtl\">מיתה עושה נ׳ וכ׳</span> the natural death of an animal causes the hanging limb (<a href=\"#\" data-headword=\"דִּלְדּוּל\">דִּלְדּוּל</a>) to be considered as if detached (in life-time, so that it does not come under the law of <a href=\"#\" data-headword=\"נְבֵלָה\">נְבֵלָה</a>), but slaughtering does not &amp;c. (and the dangling limb is considered as a part of the slaughtered animal. <span class=\"citation\">Ib. 129ᵃ</span> <span dir=\"rtl\">אי מיתה עושה נ׳ ליטמא וכ׳</span> if death causes the limb to be considered as detached, let it be susceptible of uncleanness as a limb cut off from a live animal, and if not &amp;c.; a. fr.—Pl. <a href=\"#\" data-headword=\"נִיפּוֹלִין\">נִיפּוּלִין</a>. <span dir=\"rtl\">פת נ׳</span> <i>bread which falls apart, spoiled bread</i>. <span class=\"citation\">Tosef. B. Kam. X, 9</span>; <span class=\"citation\">B. Kam. 99ᵇ</span>; <span class=\"citation\">B. Bath. 93ᵇ</span>. Sifra B’ḥuck., Par. 2, ch. VI <span dir=\"rtl\">פת ניפולה</span> (corr. acc.; <span class=\"citation\">Yalk. Lev. 675</span> <span dir=\"rtl\">נוֹפֶלֶת</span>).—[V. <a href=\"#\" data-headword=\"נִיפּוֹלִין\">נִיפּוֹלִין</a>.]—2) <i>falling down</i> for prayer. <span class=\"citation\">Deut. R. s. 2</span>, beg. (as one of the expressions for prayer, with ref. to <span class=\"citation\">Deut. IX, 25</span>); Yalk. ib. 811; Sifré ib. 26.</div>","alt":["נִפּ׳"]},"18817":{"h":"נִיפּוֹל","r":"N00729","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִיפּוּל\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>young birds found near their nests</i>. <span class=\"citation\">B. Bath. II, 6</span> (<span class=\"citation\">23ᵇ</span>) <span dir=\"rtl\">ני׳ הנמצא וכ׳</span> (Ms. O. <a href=\"#\" data-headword=\"נָפִיל\">נָפֵיל</a>; Ms. H. <a href=\"#\" data-headword=\"נֵפֶל\">נֶפֶל</a></div><div class=\"sense\"><b>—2)</b>  a species of <i>locusts, nippol</i>. <span class=\"citation\">Ḥull. 65ᵇ</span> <span dir=\"rtl\">סלעם זה ני׳</span> (Ar. <span dir=\"rtl\">החרגל</span>) <i>Salʿam</i> (<span class=\"citation\">Lev. XI, 22</span>) is <i>nippol;</i> Sifra Sh’mini, Par. 3, ch. V <span dir=\"rtl\">חרגל זה נפול</span>.</div>","alt":["נִפּ׳"]},"18818":{"h":"נִיפּוֹלָא","r":"N00730","html":"<div class=\"sense\"> ch. as <a href=\"#\" data-headword=\"נִיפּוֹל\">preced.</a> 2. <span class=\"citation\">Targ. Y. Lev. XI, 22</span> (Ar. <a href=\"#\" data-headword=\"נעלא\">נעלא</a>, corr. acc.; h. text <span dir=\"rtl\">חרגל</span>).</div>","alt":["נִיפוֹלָא"]},"18819":{"h":"ניפולה","r":"N00731","html":"<div class=\"sense\">, Sifra B’ḥuck., Par. 2, ch. VI, v. <a href=\"#\" data-headword=\"נִיפּוּל\">נִיפּוּל</a></div>","alt":[]},"18820":{"h":"ניפוליה","r":"N00732","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיפּוֹלִין\">next w.</a></div>","alt":[]},"18821":{"h":"נִיפּוֹלִין","r":"N00733","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Neapolis</i> on the site of the ancient Shechem. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> <a href=\"#\" data-headword=\"ניפוליה\">ניפוליה</a> (corr. acc., or <span dir=\"rtl\">ניפוליס</span>); <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">נ׳ של כותיים</span>. <span class=\"citation\">Num. R. s. 23</span> (expl. <a href=\"#\" data-headword=\"שְׁכֶם I\">שכם</a>, <span class=\"citation\">Josh. XX, 7</span>) <a href=\"#\" data-headword=\"נִיפּוּל\">נִפּ׳</a>.</div>","alt":[]},"18822":{"h":"נִיפְחָא","r":"N00734","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִפְחָא\">נִפְחָא</a></div>","alt":[]},"18823":{"h":"נִיפְיוֹרָא","r":"N00735","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נִיפְרָא\">נִיפְרָא</a></div>","alt":[]},"18824":{"h":"נֵיפֶל","r":"N00736","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְפִילָה\">נְפִילָה</a></div>","alt":[]},"18825":{"h":"נִיפְלָא","r":"N00737","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"נָפִיל\">נָפִיל</a>) [<i>giant</i>,] the constellation of <i>Orion</i> (h. <a href=\"#\" data-headword=\"כְּסִיל\">כְּסִיל</a>). <span class=\"citation\">Targ. Job IX, 9</span>. <span class=\"citation\">Ib. XXXVIII, 31</span>.—Pl. <a href=\"#\" data-headword=\"נָפִיל\">נְפִילִין</a>, constr. <span dir=\"rtl\">נְפִילֵי</span>, <a href=\"#\" data-headword=\"נִפְלֵי\">נִפְלֵי</a> <span class=\"citation\">Targ. Is. XIII, 10</span> (h. text <span dir=\"rtl\">וכסיליהם</span>).—<span class=\"citation\">Snh. 96ᵇ</span> בר נפלי <i>son of giants</i> (?), surname of the Messiah (with allus. to <span dir=\"rtl\">הנפלת</span>, <span class=\"citation\">Am. IX, 11</span>); Yalk. Am. 549 (some ed. <span dir=\"rtl\">נְפִילֵי</span>).</div>","alt":["נִפְ׳ I"]},"18826":{"h":"נִיפְלָא II","r":"N00738","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>untimely birth</i>, v. <a href=\"#\" data-headword=\"נְפִיל\"><span dir=\"rtl\">נְפִילָא</span> II</a>.</div>","alt":[]},"18827":{"h":"נִיפְקָא","r":"N00739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִפִקָא\">נִפְקָא</a></div>","alt":[]},"18828":{"h":"נִיפָר","r":"N00740","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Assyr. Nipur, modern Niffer, v. Schr. KAT.<sup>2</sup>, p. 57</div><div class=\"sense\"><b>2)</b> <i>Nifar</i>. <span class=\"citation\">Yoma 10ᵃ</span> (identified with <span dir=\"rtl\">כלנה</span>) <span dir=\"rtl\">ני׳</span> Ms. M. 2 (Ms. M. 1 <span dir=\"rtl\">נפגר</span> for <span dir=\"rtl\">נפור</span>, v. Rabb. D. S. a. l. note; ed. <span dir=\"rtl\">נופר נינפי</span>, strike out the second w., as a corrupt gloss, induced by phonetic resemblance of <span dir=\"rtl\">כַּלְנֵה</span> a. <a href=\"#\" data-headword=\"כַּלָּה\">כַּלָּה</a>, v. <a href=\"#\" data-headword=\"נִינְפֵי\">נִינְפֵי</a>).</div>","alt":[]},"18829":{"h":"*נִיפְרָא","r":"N00741","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a mutilation of λυχνοφόρος, cmp. <a href=\"#\" data-headword=\"לוּפָר\">לוּפָר</a>) <i>torch-bearer</i>. <span class=\"citation\">Ab. Zar. 11ᵃ</span> ני׳ Ar. (ed. <a href=\"#\" data-headword=\"נִיפְיוֹרָא\">נִיפְיוֹרָא</a>; Ag. Hatt. <span dir=\"rtl\">נוּפְרָא</span>; <span class=\"citation\">Yalk. Ex. 229</span> ed. Salon. <span dir=\"rtl\">אנפירא</span>, v. Rabb. D. S. a. l. note 200); v. <a href=\"#\" data-headword=\"פִּיפְיוֹרָא\">פִּיפְיוֹרָא</a>.</div>","alt":[]},"18830":{"h":"נִיפַשׁ","r":"N00742","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְפַשׁ\">נְפַשׁ</a>) = h. <a href=\"#\" data-headword=\"רָוַח\">רֶוַח</a>, <i>vacant space</i>. <span class=\"citation\">Targ. Y. Gen. XXXII, 17</span>.</div>","alt":[]},"18831":{"h":"נִיץ","r":"N00743","html":"<div class=\"sense\"><b>1)</b> <i>to sprout, blossom</i>. <span class=\"citation\">Targ. Ps. XC, 6</span> <span dir=\"rtl\">יְנִיץ</span>. <span class=\"citation\">Ib. CXXIX, 6</span> יֵינִיץ Ms. (ed. <span dir=\"rtl\">יציץ</span>).—<span class=\"citation\">Snh. 18ᵇ</span> <span dir=\"rtl\">יֵינַץ</span>; <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">מֵינַץ</span>, v. <a href=\"#\" data-headword=\"בַּכִּיר\">בַּכִּיר</a>; Y. Snh. I, 18ᶜ bot. <a href=\"#\" data-headword=\"טינץ\">טינץ</a> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>to shine</i> (cmp. <a href=\"#\" data-headword=\"נָבַט\">נָבַט</a>). <span class=\"citation\">Targ. Ps. CXXXII, 18</span> (h. text <span dir=\"rtl\">יציץ</span>).</div><div class=\"sense\"><b>Af. אָנֵיץ  אֲנֵיץ</b> <div class=\"sense\"><i>to bring forth blossoms</i>. <span class=\"citation\">Targ. Num. XVII, 23</span> (ed. Berl. <a href=\"#\" data-headword=\"אָנֵיץ\">אַנֵּיץ</a>).</div></div>","alt":["נוּץ","(יְנַץ)"]},"18832":{"h":"נֵיץ","r":"N00744","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֵץ\">נֵץ</a></div>","alt":["נֵיצָא"]},"18833":{"h":"נִיצְבָא","r":"N00745","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִיצּוּחַ\">נִצְ׳</a>.</div>","alt":["נִיצְבְּתָא"]},"18834":{"h":"נִיצּוּחַ","r":"N00746","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָצַח\">נָצַח</a>) <i>glory; use of the stem</i> נָצַח <i>for song</i>. <span class=\"citation\">Midr. Till. to Ps. IV</span> (expl. <span dir=\"rtl\">למנצח</span>) <span dir=\"rtl\">למי שנִצּוּחוֹ נצח נצחים</span> to him whose glory is everlasting. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בני׳ וכ׳</span> with glorification (use of <span dir=\"rtl\">נצח</span>) &amp;c.; <span class=\"citation\">Pes. 117ᵃ</span>, a. e. <a href=\"#\" data-headword=\"נִיגּוּן\">נִיגּוּן</a>.</div>","alt":["נִצּ׳"]},"18835":{"h":"נִיצּוֹחָא","r":"N00747","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָצוֹחָא\">נָצוֹחָא</a></div>","alt":[]},"18836":{"h":"נִיצּוּיֵי","r":"N00748","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"נְצֵי\">נְצֵי</a>) <i>strife, rivalry</i>. <span class=\"citation\">Meg. 24ᵇ</span> top, v. <a href=\"#\" data-headword=\"נְצֵי\">נְצֵי</a>.</div>","alt":["נִצּ׳"]},"18837":{"h":"ניצולית","r":"N00749","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיצּוֹלֶת\">next w.</a></div>","alt":[]},"18838":{"h":"נִיצּוֹלֶת","r":"N00750","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נֵצֶל\">נֵצֶל</a>) <i>remnants, refuse</i>. <span class=\"citation\">Gen. R. s. 67</span> (ref. to <span dir=\"rtl\">אצלת</span>, <span class=\"citation\">Gen. XXVII, 36</span>) <span dir=\"rtl\">מן הנ׳</span> ed. (Ar. <span dir=\"rtl\">הנִצּוֹלוֹת</span>) of the leavings (of the poorest kind). <span class=\"citation\">Gen. R. s. 74</span> (ref. to <span dir=\"rtl\">ויצל</span>, <span class=\"citation\">Gen. XXXI, 9</span>) <span dir=\"rtl\">כזה שהוא מציל מן הנ׳</span> (Ar. <span dir=\"rtl\">הנצולות</span>) like one that saves things from among the refuse.—Pl. <a href=\"#\" data-headword=\"נִיצּוֹלֶת\">נִיצּוֹלוֹת</a>, <a href=\"#\" data-headword=\"נִיצּוּחַ\">נִצּ׳</a>. <span class=\"citation\">Tosef. Ter. X, 3</span> <span dir=\"rtl\">הניצולית וכ׳</span> (corr. acc.; ed. Zuck. <span dir=\"rtl\">המצולות</span>) the leavings and the rotten fruits &amp;c.—V. <a href=\"#\" data-headword=\"נָצַל\">נָצַל</a> a. <a href=\"#\" data-headword=\"נְצוּלָה\">נְצוּלָה</a>.</div>","alt":["נִצּ׳"]},"18839":{"h":"נִיצוֹץ","r":"N00751","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"נָצַץ\">נָצַץ</a>) </div><div class=\"sense\"><b>1)</b>  (b. h.) <i>spark, sparkling light</i>. Tanḥ. Vayesheb 1 <span dir=\"rtl\">נ׳ אחד וכ׳</span> one spark from thy smithy.—Pl. <span dir=\"rtl\">נִיצוֹצוֹת</span>, <span dir=\"rtl\">נִיצוֹצִים</span>, <span dir=\"rtl\">נִיצוֹצִין</span>. <span class=\"citation\">Tosef. Yoma II, 3</span> <span dir=\"rtl\">היו נ׳ יוצאות ממנה</span> sparkling rays proceeded from it (the golden tablet); <span class=\"citation\">Yoma 37ᵇ</span> <span dir=\"rtl\">נ׳ יוצאין</span>; Y. ib. III, 41ᵃ top <span dir=\"rtl\">הנ׳ מנתזין</span>; Y. Sot. II, 18ᵃ top <span dir=\"rtl\">הניצוצים וכ׳</span>. <span class=\"citation\">Num. R. s. 5</span>, beg. <span dir=\"rtl\">שני נ׳ של אש וכ׳</span> two sparks of fire &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שני נצ׳ מקדמין וכ׳</span> two sparks preceded them. <span class=\"citation\">Y. Ab. Zar. V, end, 45ᵇ</span> (v. <a href=\"#\" data-headword=\"לִיבּוּן\">לִיבּוּן</a>) <span dir=\"rtl\">צריך שיהא נ׳ וכ׳</span> it must be so heated that sparks burst forth from it. <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 2</span> <span dir=\"rtl\">נפלו הימנו נ׳ ואמר וכ׳</span> if snuff falls off the candle, and he says, we shall have guests &amp;c. (v. <a href=\"#\" data-headword=\"אֱמוֹרִי\">אֱמוֹרִי</a>). <span class=\"citation\">Sabb. III, 6</span> <span dir=\"rtl\">לקבל נ׳</span> to receive the snuff; a. fr.—</div><div class=\"sense\"><b>*2)</b> <i>shivers scattering from the broken sledge-hammer</i>. <span class=\"citation\">Sabb. 88ᵇ</span>; <span class=\"citation\">Snh. 34ᵃ</span> (ref. to <span class=\"citation\">Jer. XXIII, 29</span>) <span dir=\"rtl\">מה פטיש זה מתחלק לכמה נ׳</span> as the sledge-hammer (when shattered by the harder rock) is divided into many shivers (differ. in commentaries).</div><div class=\"sense\"><b>—3)</b> <i>squirtings</i> (of boiling water &amp;c.). <span class=\"citation\">Ab. Zar. 76ᵇ</span> <span dir=\"rtl\">מה בולעו נ׳ וכ׳</span> as the rim of a caldron absorbs forbidden substances through squirtings, so does it emit them again through the squirtings (of the boiling cleansing water, v. <a href=\"#\" data-headword=\"גִּיעוּל I\">גִּיעוּל</a>). <span class=\"citation\">Nidd. 13ᵃ</span> <span dir=\"rtl\">נ׳ נתזין וכ׳</span> drippings (of urine) squirt upon his feet. <span class=\"citation\">Yoma 29ᵇ</span>, sq.; a. e.</div><div class=\"sense\"><b>—4)</b>  (cmp. Arab. <i>nuḍâḍah</i>) <i>residue</i>. <span class=\"citation\">Sabb. 139ᵇ</span> <span dir=\"rtl\">האיכא נ׳</span> but there is the residue (the last drops percolating through the dregs in emptying liquid from vessel to vessel); <span dir=\"rtl\">נ׳ לבי ר׳ וכ׳</span></div>","alt":[]},"18840":{"h":"נִיצוֹצָא","r":"N00752","html":"<div class=\"sense\">, <span dir=\"rtl\">נִיצוֹץ נורא</span> <i>spark</i>. <span class=\"citation\">Targ. Is. I, 31</span>.</div>","alt":[]},"18841":{"h":"נִיצוֹצְיָא","r":"N00753","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נוֹצִיצְיָא\">נוֹצִיצְיָא</a></div>","alt":[]},"18842":{"h":"נִיצּוֹק","r":"N00754","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִצּוֹק\">נִצּוֹק</a></div>","alt":[]},"18843":{"h":"נִיצוֹר","r":"N00755","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"נֵצֶר IV\"><span dir=\"rtl\">נֵצֶר</span> IV</a></div>","alt":["בַּר נִ׳"]},"18844":{"h":"נִיצָּחוֹן","r":"N00756","html":"<div class=\"sense\">, v. sub. <span dir=\"rtl\">נצח׳</span>.</div>","alt":["נִיצְחָנָא","נִיצְחָנוּתָא"]},"18845":{"h":"נִיצְיָיא","r":"N00757","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*נִצְיָיא\">נִצְיָיא</a></div>","alt":["נִיצְיָינָא"]},"18846":{"h":"נֵיצֶל","r":"N00758","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נֵצֶל\">נֵצֶל</a></div>","alt":[]},"18847":{"h":"נִיצָּנָא","r":"N00759","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נצץ</span>) = b. h. <a href=\"#\" data-headword=\"צָנַן\">נִצָּן</a>, <i>blossom</i>.—Pl. <span dir=\"rtl\">נִיצָּנַיָּא</span>, <a href=\"#\" data-headword=\"נִיצָּנָא\">נִצָּ׳</a>. <span class=\"citation\">Targ. I Kings VI, 1</span>; <span class=\"citation\">37</span>.</div>","alt":["נִצָּ׳"]},"18848":{"h":"נִיצְצָא","r":"N00760","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְצָצָא\">נְצָצָא</a></div>","alt":[]},"18849":{"h":"נִיצְרָא","r":"N00761","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִצְרָא\">נִצְרָא</a></div>","alt":[]},"18850":{"h":"נִיקְבָּא","r":"N00762","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִקְבָּא\">נִקְבָּא</a></div>","alt":[]},"18851":{"h":"נִיקּוּד","r":"N00763","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַד I) </div><div class=\"sense\"><b>1)</b> <i>dot, point</i>.—Pl. <span dir=\"rtl\">נִיקּוּדִים</span>, <span dir=\"rtl\">נִיקּוּדִין</span>, <a href=\"#\" data-headword=\"נִיקּוּד\">נִקּ׳</a>. <span class=\"citation\">Tosef. Sabb. XI</span> (<span class=\"citation\">XII), 13</span> <span dir=\"rtl\">הכותב שני נ׳ וכ׳</span> if one writes (on the Sabbath) two dots, and another person finishes them up &amp;c., v. <a href=\"#\" data-headword=\"נְקוּדָּה\">נְקוּדָּה</a>.</div><div class=\"sense\"><b>—2)</b> <i>pl.</i> (as ab.) <i>minute loaves, cakes</i> (of half the size of an egg). <span class=\"citation\">Ter. V, 1</span> (oth. opin. <i>crumbled pieces</i>; v. <span class=\"citation\">Josh. IX, 12</span>); <span class=\"citation\">Bekh. 22ᵇ</span>. <span class=\"citation\">Y. Ter. V, 43ᶜ</span> top <span dir=\"rtl\">והדין נ׳ כהדא חציי וכ׳</span> those <i>niḳḳadim</i> are half the size of eggs.—[Midr. Sam. ch. XXII <span dir=\"rtl\">ניקודים</span> some ed., read: <span dir=\"rtl\">נִיקּוּרִים</span>.]</div>","alt":["נִקּ׳"]},"18852":{"h":"נִיקּוּי","r":"N00764","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נקי\">נָקָה</a>) <i>cleansing, clearing</i> from sin. <span class=\"citation\">Gen. R. s. 82</span>, beg. <span dir=\"rtl\">עולמים אין לו נ׳</span> will never be cleared (forgiven).</div>","alt":["נִקּ׳"]},"18853":{"h":"נִיקוֹלוֹגוֹס","r":"N00765","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (νεικολόγος, not found in Greek Dict.) <i>pleader in a law-suit</i>. Pesik. Baḥod., p. 153ᵇ <span dir=\"rtl\">מנה לך ניקלגיס וכ׳</span> (corr. acc.) retain for thyself such and such a man as pleader, and thou shalt be acquitted; <span class=\"citation\">Yalk. Num. 782</span>; <span class=\"citation\">Yalk. Lev. 645</span> <span dir=\"rtl\">ניקולונ׳</span> (corr. acc.); <span class=\"citation\">Lev. R. s. 29</span> <span dir=\"rtl\">נקול׳</span>; v. <a href=\"#\" data-headword=\"דִּיקוֹלוֹגוֹס\">דִּיקוֹלוֹגוֹס</a>.</div>","alt":[]},"18854":{"h":"נִיקוֹמָכִי","r":"N00766","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Νικομάχης) <i>Nicomaches</i>, an Amora. <span class=\"citation\">Y. M. Kat. I, 80ᵈ</span> top; Y. Snh. II, 23ᵈ bot. (not <span dir=\"rtl\">ניקימ׳</span>).</div>","alt":[]},"18855":{"h":"*נִיקוֹן","r":"N00767","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Νίκων, v. Joseph. Bell. <span class=\"citation\">Jud. V, 7</span>, 2) <i>an engine of war, iron ram.</i> <span class=\"citation\">Kel. XI, 8</span> (comment. <i>iron point of a javelin</i>, ref. to <span dir=\"rtl\">קינו</span> <span class=\"citation\">II Sam. XXI, 16</span>; R. Hai G. reads <a href=\"#\" data-headword=\"נִקָּיוֹן\">נקיון</a>); [<span class=\"citation\">Tosef. Kel. B. Mets. III, 1</span> <a href=\"#\" data-headword=\"גִּינִּין\">גינין</a>].</div>","alt":[]},"18856":{"h":"נִיקּוּף","r":"N00768","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַף I) <i>knock, bruise</i>. <span class=\"citation\">Ḥull. 7ᵇ</span> <span dir=\"rtl\">דם נ׳ וכ׳</span> the blood of a bruise atones &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נ׳ שני</span> a second bruise (before the first one is healed).</div>","alt":["נִקּ׳ I"]},"18857":{"h":"נִיקּוּף ²","r":"N00769","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַף II) <i>crown, rim</i>.—<span dir=\"rtl\">זיתי נ׳</span> (cmp. <a href=\"#\" data-headword=\"פֵּאָה\">פֵּאָה</a>; v. <span class=\"citation\">Is. XVII, 6</span>) <i>the olives left on the tree for the poor, the poor man’s share, gleaning</i>, opp. to <span dir=\"rtl\">זיתי מָסִיק</span>. <span class=\"citation\">Ḥall. III, 9</span>. <span class=\"citation\">Peah VIII, 3</span>. Yib. 20ᵈ bot. <span dir=\"rtl\">מקום שנהגו … ז׳ נ׳ וכ׳</span> where the custom prevails to take down the gleanings (instead of leaving them on the trees), the poor man may say, this oil is from gleanings; a. e.—[Comment. <span dir=\"rtl\">זיתי נ׳</span> olives which are <i>knocked down</i>, v. preced.]</div>","alt":["נִקּ׳ II"]},"18858":{"h":"נִיקּוּר","r":"N00770","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (נָקַר I) </div><div class=\"sense\"><b>1)</b> <i>picking, biting; chiselling</i>.—נ׳ עינים <i>putting out the eyes</i>. Pesik. Aḥăré, p. 168ᵇ; <span class=\"citation\">Lev. R. s. 20</span>; Tanḥ. Vaëthḥ. 1; <span class=\"citation\">Koh. R. to VIII, 17</span>.—נ׳ אבנים <i>chiselling of stones</i>. <span class=\"citation\">Sot. 46ᵇ</span>.—Esp. <i>the picking</i> or <i>biting</i> done by birds, snakes &amp;c., <i>traces of biting</i>. <span class=\"citation\">Ab. Zar. 35ᵃ</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"נְחַשׁ I\">נחש</a>) <span dir=\"rtl\">משום נ׳</span></span> because a serpent may have touched it. <span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> top <span dir=\"rtl\">דג נ׳</span> a fish showing traces of bites; a. fr.—Pl. <span dir=\"rtl\">נִיקּוּרִים</span>, <span dir=\"rtl\">נִיקּוּרִין</span>, <a href=\"#\" data-headword=\"נִיקּוּד\">נִקּ׳</a>. <span class=\"citation\">Ter. VIII, 6</span> <span dir=\"rtl\">נִיקּוּרֵי תאנים וכ׳</span> figs &amp;c. which appear to have been bitten at (possibly by snakes); <span class=\"citation\">Tosef. ib. VII, 16</span> <span dir=\"rtl\">נ׳ תבשיל וכ׳</span> a dish &amp;c. showing traces of bites. <span class=\"citation\">Kidd. 80ᵃ</span>, sq. <span dir=\"rtl\">נמצאו נ׳ נ׳ וכ׳</span> the dough shows that it has been pecked at (by chickens); a. fr.—Esp. <i>niḳḳurin, laws concerning food suspected of having been touched by snakes</i>. Y. Ter. l. c.; v. <a href=\"#\" data-headword=\"אֲפַךְ\">אֲפַּךְ</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>pl. worm-eaten cloth, shreds</i>. Midr. Sam. ch. XXII (some ed. <span dir=\"rtl\">ניקוד׳</span>, corr. acc.); Yalk. ib. 129, v. <a href=\"#\" data-headword=\"*בְּרוּקְלֵי\">בְּרוּקְלֵי</a>.</div>","alt":["נִקּ׳"]},"18859":{"h":"נִיקּוּרָא","r":"N00771","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">נִיקּוּרִין</span>, <span dir=\"rtl\">נִיקּוּרֵי</span>. <span class=\"citation\">Ḥull. 59ᵃ</span> <span dir=\"rtl\">לא חייש מר לנ׳</span> do you not apprehend that it may have been bitten by snakes?—<span class=\"citation\">Ab. Zar. 30ᵇ</span> אי אית ביה נ׳ Ar. (ed. <span dir=\"rtl\">נְקִירֵי</span>) if there are bites in it.—<span class=\"citation\">Ḥull. 57ᵃ</span> צנא דנקורי Ar., v. <a href=\"#\" data-headword=\"אִינְקוֹרָא\">אִינְקוֹרָא</a>.</div>","alt":[]},"18860":{"h":"נִיקּוּשָׁא","r":"N00772","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְקַשׁ\">נְקַשׁ</a>) <i>knocking, rattling</i>. <span class=\"citation\">Targ. Jer. XLVI, 22</span>. <span class=\"citation\">Targ. Nah. II, 11</span>. <span class=\"citation\">Ib. III, 2</span>; a. e.—V. <a href=\"#\" data-headword=\"נְקָשָׁא\">נְקָשָׁא</a>.</div>","alt":["נִקּ׳"]},"18861":{"h":"נִיקַטְמוֹן","r":"N00773","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*אָנְקִטְמִין\">אָנְקִיטְמִין</a>) <i>a musical instrument resembling a wooden leg.</i> <span class=\"citation\">Kel. XV, 6</span>.</div>","alt":["נְקַ׳"]},"18862":{"h":"נִיקָּיוֹן","r":"N00774","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִקָּיוֹן\">נִקָּיוֹן</a>.—[<span class=\"citation\">Kel. XV, 8</span>, R. H. G., v. <a href=\"#\" data-headword=\"*נִיקוֹן\">נִיקוֹן</a>.]</div>","alt":[]},"18863":{"h":"ניקלבים","r":"N00775","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקְלְוָוס\">נִיקְלְוָוס</a></div>","alt":["ניקלבוס","ניקלבס"]},"18864":{"h":"ניקלגיס","r":"N00776","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיקוֹלוֹגוֹס\">נִיקוֹלוֹגוֹס</a></div>","alt":["ניקלוגוס"]},"18865":{"h":"נִיקְלְוָוס","r":"N00777","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Νικόλαος, S.) <i>a variety of the date</i>. <span class=\"citation\">Ab. Zar. I, 5</span> (<span class=\"citation\">13ᵇ</span>) <span dir=\"rtl\">נקליבם</span> (Bab. ed. <span dir=\"rtl\">נקלב</span>; Mish. Nap. <span dir=\"rtl\">ודנקלבס</span>, v. Rabb. D. S. a. l. note 400; Y. ed. <a href=\"#\" data-headword=\"ניקלבים\">ניקלבים</a>). Ib. 14ᵇ <span dir=\"rtl\">נקלס</span> (Ms. M. <a href=\"#\" data-headword=\"נִקְלְוָוס\">נקלווס</a>); Y. ib. I, 39ᵈ bot. <span dir=\"rtl\">נקלבי׳</span>. <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> <span dir=\"rtl\">דניקלבס</span> stones of <i>nicolaos</i> dates; <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">דנִקְלְבִיסִין</span> (<i>pl.</i>)—<i>Pl.</i> <span dir=\"rtl\">נִיקְלַוְוסִין</span>, <span dir=\"rtl\">נִיקְלַוְוסַיָּא</span> &amp;c. <span class=\"citation\">Y. Ber. VI, 10ᶜ</span> bot.—<span class=\"citation\">Num. R. s. 3</span>, beg., v. <a href=\"#\" data-headword=\"נוֹבֶלֶת\">נוֹבֶלֶת</a>; <span class=\"citation\">Midr. Till. to Ps. XCII</span> <span dir=\"rtl\">מקולסין</span> (corr. acc.).</div>","alt":["נִיקְלְבָס"]},"18866":{"h":"נִיקְלַי","r":"N00778","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּנְקְלַי II\"><span dir=\"rtl\">אוּנְקְלַי</span> II</a></div>","alt":[]},"18867":{"h":"נִיקְלִיטִין","r":"N00779","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַקְלִיטִין\">נַקְלִיטִין</a></div>","alt":[]},"18868":{"h":"נִיקָנוֹר","r":"N00780","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Νικάνωρ) <i>Nicanor</i>, </div><div class=\"sense\"><b>1)</b>  a general under Antioch Epiphanes and Demetrius I, defeated and slain by Judah Maccabi (<span class=\"citation\">I Macc. VII, 39</span>; <span class=\"citation\">II Macc. XV, 30</span>). <span class=\"citation\">Y. Taan. II, 66ᵃ</span> top (Meg. Taan. XII) <span dir=\"rtl\">יום נ׳</span> Nicanor-Day (a half-festival); <span class=\"citation\">Y. Meg. I, 70ᶜ</span> bot.</div><div class=\"sense\"><b>—2)</b>  N., who imported Corinthian bronze doors for a Temple gate. <span class=\"citation\">Yoma III, 10</span>; <span class=\"citation\">Tosef. ib. II, 4</span>; Y. ib. III, 41ᵃ; Bab. <span class=\"citation\">ib. 38ᵃ</span>. <span class=\"citation\">Midd. II, 3</span>, a. fr. <span dir=\"rtl\"><span dir=\"rtl\">שער נ׳</span> (שערי</span>), v. <a href=\"#\" data-headword=\"נְחוּשְׁתָּן\">נְחוּשְׁתָּן</a></div>","alt":["נִקָ׳"]},"18869":{"h":"נִיקְצָא","r":"N00781","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִיקּוּף\">נִקְ׳</a>.</div>","alt":["נִיקְרָא"]},"18870":{"h":"נִיר I","r":"N00782","html":"<div class=\"sense\"> v. Del. Proleg., p. 98, sq.) [<i>to conquer</i>,] <i>to break ground, clear</i>. <span class=\"citation\">Tosef. Men. IX, 3</span> <span dir=\"rtl\">נָרָהּ שנה ראשונה ושנייה חורשה וכ׳</span> he breaks the field the first year, the second year he ploughs it &amp;c.; <span class=\"citation\">Men. 85ᵃ</span>. <span class=\"citation\">Arakh. IX, 1</span> (<span class=\"citation\">29ᵇ</span>) <span dir=\"rtl\">נָרָהּ</span> if he broke it (without planting). <span class=\"citation\">Tosef. B. Mets. IX, 7</span> <span dir=\"rtl\">לא יהא נָר … אלא נָאר וכ׳</span> (Var. <a href=\"#\" data-headword=\"נֵר\">נָר</a>) he must not plough it over entirely one year and plant the next, but plough one half &amp;c. <span class=\"citation\">Ib. 8</span> <span dir=\"rtl\">והיה נָרָהּ וכ׳</span> and he ploughed all of it one year &amp;c. <span class=\"citation\">Ib. 26</span> <a href=\"#\" data-headword=\"נָאר\">נאר</a> (Var. <a href=\"#\" data-headword=\"נְיָיר\">נָיֵיר</a>, <a href=\"#\" data-headword=\"נֵר\">נָר</a>); a. fr.—Part. pass. <a href=\"#\" data-headword=\"נִיר\">נִיר</a>; f. <span dir=\"rtl\">נִירָה</span>. <span class=\"citation\">Ib. 29</span> <span dir=\"rtl\">מניחה לפניו נ׳</span> when he surrenders the field to him cleared, opp. <a href=\"#\" data-headword=\"שֶׁלֶף\">שֶׁלֶף</a>.—[<span class=\"citation\">Men. 85ᵇ</span> <span dir=\"rtl\">ניר חציה</span>, Ms. M. <a href=\"#\" data-headword=\"נֵר\">נָר</a>.]</div><div class=\"sense\"><b>Pilp. נִרְנֵר</b> <div class=\"sense\"><i>to plough over repeatedly</i>. Part. pass. <span dir=\"rtl\">מְנוֹנָר</span> (= <span dir=\"rtl\">מְנוּרְנָר</span>; cmp. <a href=\"#\" data-headword=\"מְטוֹטֶלֶת\">מְטוֹטֶלֶת</a> a. <a href=\"#\" data-headword=\"מְטוֹלְטֶלֶת\">מְטוּלְטֶלֶת</a>); f. <span dir=\"rtl\">מְנוֹנֶרֶת</span>, pl. <span dir=\"rtl\">מְנוֹנָרוֹת</span>. <span class=\"citation\">Men. 85ᵃ</span> <span dir=\"rtl\">שדות … והמ׳ לכך</span> (Ms. M. <span dir=\"rtl\">הנונרות לבד</span>, corr. acc. or <span dir=\"rtl\">הנִינָּרוֹת</span> <i>Nif.</i>) fields … repeatedly ploughed over for that purpose; <span class=\"citation\">Tosef. ib. IX, 3</span> <span dir=\"rtl\">הגינירות</span>, Var. <span dir=\"rtl\">הניטרות</span>, read <span dir=\"rtl\">הנִינָּרוֹת</span> or <span dir=\"rtl\">הנִינּוֹרוֹת</span>).</div></div><div class=\"sense\"><b>Nif. נִינָּר  נִינּוֹר</b> <div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"דִּין I\">נִידּוֹן</a> fr. <a href=\"#\" data-headword=\"דִּין\">דִּין</a>) <i>to be broken</i>, v. supra.</div></div>","alt":["נוּר"]},"18871":{"h":"נִיר","r":"N00783","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. VIII, 12</span> <a href=\"#\" data-headword=\"לְמֵינָה\">לְמֵינָר</a> (ed. Wil. <span dir=\"rtl\">למִינַר</span>).</div>","alt":[]},"18872":{"h":"נִיר II","r":"N00784","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נִיר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>clearing, ploughing over</i>. <span class=\"citation\">Tosef. B. Mets. IX, 24</span> <span dir=\"rtl\">בשעת הנ׳</span> (read: <span dir=\"rtl\">בשנת</span>) in the year during which he cleared the land.</div><div class=\"sense\"><b>—2)</b> <i>newly broken land.</i> <span class=\"citation\">Peah II, 1</span> <span dir=\"rtl\">הבור והנ׳</span> fallow land or newly broken land. <span class=\"citation\">Y. Naz. VII, 56ᵇ</span> top; a. e.—Pl. <span dir=\"rtl\">נִירִין</span>. <span class=\"citation\">Shebi. IV, 3</span>.</div>","alt":[]},"18873":{"h":"נִיר ²","r":"N00785","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. VIII, 12</span>.</div>","alt":["נִירָא I"]},"18874":{"h":"נִיר III","r":"N00786","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(<a href=\"#\" data-headword=\"נִיר ²\">preced.</a> wds.; Assyr. <i>nîru</i>) <i>yoke; servitude</i>. <span class=\"citation\">Targ. Deut. XXI, 3</span>. <span class=\"citation\">Targ. Num. XIX, 2</span>.—<span class=\"citation\">Targ. Jer. XXVII, 8</span>; a. fr.—<span class=\"citation\">Y. Sabb. V, end, 7ᶜ</span>; Bab. <span class=\"citation\">Sabb. 54ᵇ</span>, v. <a href=\"#\" data-headword=\"גִּימוֹן\">גִּימוֹן</a>.—Pl. <span dir=\"rtl\">נִירִין</span>. <span class=\"citation\">Targ. Jer. XXVII, 2</span>. <span class=\"citation\">Ib. XXVIII, 13</span>.</div>","alt":["נִירָא II"]},"18875":{"h":"נִיר IV","r":"N00787","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נִיר III\">preced.</a>; cmp. jugum a. ζυγόν, v. Sm. Ant. s. v. Tela) <i>cross-beam of the loom</i>, also <i>the cross-rod</i> under the cross-beam (liciatorium) to which the ends of the leashes are fastened; trnsf (mostly pl.) <span dir=\"rtl\">נִירִים</span>, <span dir=\"rtl\">נִירִין</span> <i>the leashes</i> or <i>thrums</i> to which the threads of the warp are fastened; also <i>the warp</i>. <span class=\"citation\">Gen. R. s. 94</span>, v. <a href=\"#\" data-headword=\"פָּתַל\">פָּתַל</a>. <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">אין לוקחין … ולא נ׳</span> you must not buy from the weaver remnants of woof or of warp threads. <span class=\"citation\">Kel. XXI, 1</span> <span dir=\"rtl\">הנוגע בנ׳ …</span> he who touches the upper beam … or the rods, contrad. to <a href=\"#\" data-headword=\"קֵירוֹס I\">קֵירוֹס</a>.—<span dir=\"rtl\">בית נ׳</span> that portion of the web produced by passing the spool with the woof across the warp, <i>mesh, slip</i>. <span class=\"citation\">Sabb. XIII, 2</span> (<span class=\"citation\">105ᵃ</span>) <span dir=\"rtl\">העושה שני בתי נ׳ בנִירַיִּים וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">בנירין</span>) he who starts a web by making two meshes, attaching them either to the cross-pieces or to the slips <a href=\"#\" data-headword=\"קֵירוֹס I\">(קֵירוֹס</a>). Ib. 105ᵃ <span dir=\"rtl\">ברוחב ג׳ בתי נ׳</span> within a distance of three meshes; (Tosef. ib. XII (XIII), 1 <span dir=\"rtl\">על ג׳ בתים</span>). Y. ib. VII, 10ᶜ <span dir=\"rtl\">שני נ׳ בחף … בניר אחד</span> two sets of warp threads fastened to one old border web (licium) or two borders fastened to one set of warp threads. <span class=\"citation\">Shek. VIII, 5</span> על ע&quot;ב נ׳ וכ׳ Ms. M. a. Ar. (ed. <span dir=\"rtl\">נימין</span>; v. Rabb. D. S. a. l., p. <span dir=\"rtl\">לד</span>, note) the curtain was woven on seventy-two leashes, and each twist of the warp (<a href=\"#\" data-headword=\"נִימָה\">נִימָה</a>) contained twenty four threads; <span class=\"citation\">Ḥull. 90ᵇ</span>; <span class=\"citation\">Tam. 29ᵇ</span> <span dir=\"rtl\">נימין</span>; <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">נימין</span>; Tanḥ. Vayaḳh. 7 <span dir=\"rtl\">נימין</span>; ed. Bub. 10 <span dir=\"rtl\">נירים</span>.</div>","alt":[]},"18876":{"h":"נִירָא III","r":"N00788","html":"<div class=\"sense\">; <span dir=\"rtl\">בת נ׳</span> the <i>cross-rod</i> (liciatorium). <span class=\"citation\">Sabb. 105ᵃ</span> (expl. <span dir=\"rtl\">שני בתי נירין בנירין</span>, v. <a href=\"#\" data-headword=\"נִיר IV\">preced.</a>) <span dir=\"rtl\">תרתי בבת נ׳ וחדא בנ׳</span> Ms. M. a. Rashi (ed. <span dir=\"rtl\">בבתי</span>, early ed. <span dir=\"rtl\">בבי</span>; v. Rabb. D. S. a. l. note) he passes a thread twice around the cross-rod and once around the cross-beam (jugum). <span class=\"citation\">Ib. 67ᵃ</span> <span dir=\"rtl\">נ׳ ברקא</span> a white twisted cord.—Pl. <span dir=\"rtl\">נִירַיָּא</span>. Y. ib. XIII, beg. 14ᵃ (expl. <span dir=\"rtl\">בנירין</span>, v. supra) <a href=\"#\" data-headword=\"נ׳\">נ׳</a> the two cross-rods (the liciatorium and the jugum).</div>","alt":[]},"18877":{"h":"נִירְדָּא","r":"N00789","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִרְדָּא\">נִרְדָּא</a></div>","alt":[]},"18878":{"h":"נִירוֹן","r":"N00790","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Nero</i>, the Roman emperor. <span class=\"citation\">Gitt. 56ᵃ</span> <span dir=\"rtl\">נ׳ קיסר</span>. <span class=\"citation\">Lam. R. to I, 5</span> <span dir=\"rtl\">מית נ׳</span> (<span class=\"citation\">Gitt. 56ᵇ</span> <a href=\"#\" data-headword=\"קֵיסַר\">קיסר</a>).</div>","alt":[]},"18879":{"h":"נִירוֹנִית","r":"N00791","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נִירוֹן\">preced.</a>) <i>aNeronian coin</i>. <span class=\"citation\">B. Mets. 25ᵇ</span>; <span class=\"citation\">Tosef. ib. II, 10</span>. <span class=\"citation\">Kel. XVII, 12</span> <span dir=\"rtl\">כסלע הניר׳</span> ed. Dehr. (ed. <span dir=\"rtl\">הנר׳</span>, corr. acc.) the size of the Neronian Sela; Bekḥ. 37ᵇ. Ib. 38ᵃ</div>","alt":[]},"18880":{"h":"נֵירוֹק","r":"N00792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָקַק\">רָקַק</a></div>","alt":[]},"18881":{"h":"נִישְׁבָּא","r":"N00793","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">נִשְׁבּ׳</span>.</div>","alt":["נִישְׁבִּים","נִישְׁבִּין"]},"18882":{"h":"נִישְׁדּוּר","r":"N00794","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. našâdur. v. Perl. Et. St. p. 48) <i>gum-ammoniac</i>. <span class=\"citation\">Gitt. 69ᵃ</span> bot.</div>","alt":["נִשְׁ׳"]},"18883":{"h":"נִישּׂוּאִין","r":"N00795","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשָׂא\">נָשָׂא</a>) <i>taking in marriage</i> (v. <a href=\"#\" data-headword=\"אֵרוּסִין\">אֵרוּסִין</a>); <i>married state</i>. <span class=\"citation\">Keth. I, 4</span> <span dir=\"rtl\">אלמנה … מן הנ׳</span> a widow, a divorced woman … after having been actually married, opp. to <span dir=\"rtl\">מן הארוסין</span>. <span class=\"citation\">Ib. V, 1</span>. <span class=\"citation\">Yeb. 23ᵃ</span> (ref. to <span class=\"citation\">Deut. XXI, 15</span>) <span dir=\"rtl\">אהובה בנִישּׂוּאֶיהָ וכ׳</span> beloved for her (blameless) marriage, hated for her (illicit) marriage. Ib. 64ᵇ <span dir=\"rtl\">נ׳ ומלקיות</span> as to marrying (a third time), and as to the treatment of one twice lashed; a. fr.</div>","alt":["נִשּׂ׳"]},"18884":{"h":"נִישּׂוּאִין ²","r":"N00796","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Chr. VIII, 9</span> <span dir=\"rtl\">דאתחדתא בני שואה</span>, read: <span dir=\"rtl\">דאתחדתא הלכה בנִישּׂוּאֶהָ</span> for a novel interpretation of the law was established through her marriage; v. <span class=\"citation\">Y. Yeb. VIII, 9ᶜ</span> top.</div>","alt":[]},"18885":{"h":"נישיותה","r":"N00797","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְשִׂיאוּתָא\">נְשִׂיאוּתָא</a></div>","alt":[]},"18886":{"h":"נישובים","r":"N00798","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִשְׁבִּים\">נִשְׁבִּים</a></div>","alt":[]},"18887":{"h":"נִישּׁוֹבֶת","r":"N00799","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָשַׁב\">נָשַׁב</a>) <i>chaff</i>. <span class=\"citation\">B. Bath. 94ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"נִישּׁוֹבֶת\">נִישּׁוֹבוֹת</a> pl.; Ms. R. <a href=\"#\" data-headword=\"נִשּׁוֹפוֹת\">נִשּׁוֹפוֹת</a>).</div>","alt":[]},"18888":{"h":"נִישְׁמָא","r":"N00800","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִישְׁדּוּר\">נִשְׁ׳</a>.</div>","alt":["נִישְׁפָּא","נִישְׁרָא"]},"18889":{"h":"נִישְׂתְּרוּפֵי","r":"N00801","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"שָׂרָף\">שָׂרָף</a>) <i>drippings</i>; <span dir=\"rtl\">קירא דנ</span> <i>wax that runs through the beehive</i>. <span class=\"citation\">Sabb. 110ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"נָשׁ\">נִשְׂ</a>).</div>","alt":[]},"18890":{"h":"נִיתְבָּרָא","r":"N00802","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִדְבָּכָה\">נִדְבָּכָה</a></div>","alt":[]},"18891":{"h":"נִיתּוּחַ","r":"N00803","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָתַח\">נָתַח</a>) <i>dissection</i>. <span class=\"citation\">Zeb. V, 4</span>, v. <a href=\"#\" data-headword=\"הֶפְשֵׁט\">הֶפְשֵׁט</a>. <span class=\"citation\">Gen. R. s. 34</span>; a. fr.</div>","alt":["נִתּ׳"]},"18892":{"h":"נִיתְקָא","r":"N00804","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"נִיתּוּחַ\">נִתְ׳</a>.</div>","alt":["נִיתְרָא"]},"18893":{"h":"נְכָא","r":"N00805","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְכֵי\">נְכֵי</a></div>","alt":[]},"18894":{"h":"נַכַּאי","r":"N00806","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַכַּי\">נַכַּי</a></div>","alt":[]},"18895":{"h":"נְכָאלָא","r":"N00807","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכֵיל\">נְכֵיל</a>) <i>deceiver, hypocrite</i>. <span class=\"citation\">Targ. Prov. XI, 9</span> Ms. (ed. <a href=\"#\" data-headword=\"נְכַל\">נִכְלָא</a>).</div>","alt":[]},"18896":{"h":"נֶכֶד","r":"N00808","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>offspring, grandson</i>. Mekh. B’shall., Amalek, s. 2, v. <a href=\"#\" data-headword=\"נִין\">נִין</a>.</div>","alt":[]},"18897":{"h":"נָכָה","r":"N00809","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נכי\">נכי</a></div>","alt":[]},"18898":{"h":"נֵכֶה","r":"N00810","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>crippled</i>, <span dir=\"rtl\">נְכֵה רגלים</span> <i>paralyzed, lame</i>. <span class=\"citation\">Yalk. Deut. 933</span>. <span dir=\"rtl\">משל לנ׳ ר׳ וכ׳</span> like a lame person that disturbed the peace of &amp;c., opp. <a href=\"#\" data-headword=\"שָׁלֵם\">שָׁלֵם</a>.—Pl. <span dir=\"rtl\">נֵכִים</span>. <span class=\"citation\">Pesik. R. s. 13</span>, v. <a href=\"#\" data-headword=\"צָלַע\">צָלַע</a>.</div>","alt":[]},"18899":{"h":"נְכֹה","r":"N00811","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Pharaoh Necho</i> (II), King of Egypt. <span class=\"citation\">Sot. 9ᵃ</span>; a. e.</div>","alt":["פַּרְעֹה נ׳"]},"18900":{"h":"נָכוֹן","r":"N00812","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>firm, ready</i>. <span class=\"citation\">Ber. 60ᵃ</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  pr. n. <span dir=\"rtl\">גֹּורֶן נ׳</span>, v. <a href=\"#\" data-headword=\"כִּידוֹן II\"><span dir=\"rtl\">כִּידוֹן</span> II</a></div>","alt":[]},"18901":{"h":"נָכוֹסָא","r":"N00813","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכַס\">נְכַס</a>) <i>butcher</i>. <span class=\"citation\">Y. Yoma III, 40ᶜ</span> top (expl. <a href=\"#\" data-headword=\"קְרַץ I\">קרץ</a>, <span class=\"citation\">Jer. XLVI, 20</span>) <span dir=\"rtl\">חד אמר נ׳</span> one says, it means the butcher (with ref. to <span class=\"citation\">Yoma III, 4</span> <span dir=\"rtl\">קרצו</span>).</div>","alt":["נָכוֹסָה"]},"18902":{"h":"נִכּוּשׁ","r":"N00814","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נִיכּוּשׁ</a></div>","alt":[]},"18903":{"h":"נָכוֹשׁ","r":"N00815","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָכַשׁ\">נָכַשׁ</a>) <i>he who lops trees</i>, v. <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נִיכּוּשׁ</a>.</div>","alt":[]},"18904":{"h":"נַכְזְרָיָא","r":"N00816","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַכְזָר\">אַכְזָר</a>) <i>cruel</i>. <span class=\"citation\">Targ. Prov. XI, 17</span> (ed. Lag. <a href=\"#\" data-headword=\"נוּכְרָא\">נוכריא</a>). <span class=\"citation\">Ib. XVII, 11</span> (ed. Wil. <span dir=\"rtl\">נוּכְזְ׳</span>).</div>","alt":[]},"18905":{"h":"נִכְזְרָיוּתָא","r":"N00817","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַכְזְרָיָא\">preced.</a>) <i>cruelty</i>. <span class=\"citation\">Targ. Prov. XII, 10</span> (ed. Wil. <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נַכְ׳</a>). <span class=\"citation\">Ib. XXVII, 4</span> (v. <a href=\"#\" data-headword=\"נוּכְרָא\">נוּכְרָא</a>).</div>","alt":[]},"18906":{"h":"נכי","r":"N00818","html":"<div class=\"sense\"> (b. h.) <i>to be lessened</i>.—[<span class=\"citation\">Lev. R. s. 33</span> <span dir=\"rtl\">אלא נכה</span>, some ed., v. <a href=\"#\" data-headword=\"אָנָךְ\">אָנָךְ</a>.]</div><div class=\"sense\"><b>Pi. נִכָּה  נִיכָּה</b> <div class=\"sense\"><i>to deduct</i>. <span class=\"citation\">Ḥull. X, 3</span> <span dir=\"rtl\">ואינו מְנַכֶּה לו וכ׳</span> and the seller is not bound to allow him a reduction for the priest’s share. <span class=\"citation\">B. Bath. VII, 2</span>, sq. <span dir=\"rtl\">יְנַכֶּה</span> he must make an allowance for what there is less than specified in the contract. <span class=\"citation\">Num. R. s. 20</span> (ref. to <span dir=\"rtl\">נכה</span>, <span class=\"citation\">ib. XXII, 6</span>) <span dir=\"rtl\">כמי שמְנַכֶּה אחד מכ&quot;ד לסאה</span> as one (purchasing grain) is prepared for a deficiency of one twenty-fourth for each S’ah (allowance for chaff, v. <a href=\"#\" data-headword=\"טִינּוֹפֶת\">טִינֹּופֶת</a>); Tanḥ. Balak 4 (not <span dir=\"rtl\">למאה</span>); ed. Bub. 6; a. fr.—[<span class=\"citation\">Cant. R. to III, 4</span> <span dir=\"rtl\">שנכה מסנחריב</span> some ed., read <span dir=\"rtl\">שנָכַת</span>, v. <a href=\"#\" data-headword=\"נְכִיתָה\">נְכִיתָה</a>.]</div></div><div class=\"sense\"><b>Hif. הִכָּה  הִיכָּה</b> <div class=\"sense\"><b>1)</b> <i>to injure, knock, strike</i>. <span class=\"citation\">B. Kam. VIII, 1</span> <span dir=\"rtl\">הִכָּהוּ חייב וכ׳</span> if he hit him (created a sore), he must pay for curing him. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">המַכֶּה את וכ׳</span> if a person strikes his father &amp;c. <span class=\"citation\">Snh. IX, 2</span> <span dir=\"rtl\">נתכוין להַכֹּותוֹ וכ׳</span> if he intended to hit him on his loins. Y. Peah I, 16ᵃ bot. (ref. to <span class=\"citation\">Ps. CXX, 3</span>, sq.) <span dir=\"rtl\">כל כלי זיין מַכִּין וכ׳</span> all weapons strike in their place, but this (calumny) strikes at a distance; a. v. fr.—Part. pass. <span dir=\"rtl\">מוּכֶּה</span>; f. <span dir=\"rtl\">מוּכָּה</span>; pl. <span dir=\"rtl\">מוּכִּים</span>, <span dir=\"rtl\">מוּכִּין</span>; <span dir=\"rtl\">מוּכֹּות</span>. <span class=\"citation\">Keth. VII, 10</span>, a. fr. <span dir=\"rtl\">מוּכֵּה שהין</span> afflicted with leprosy. <span class=\"citation\">Ib. I, 3</span>, a. fr. <span dir=\"rtl\">מוּכַּת עץ</span> one who lost her hymen through an accidentallesion. <span class=\"citation\">Par. VIII, 9</span>; <span class=\"citation\">Mikv. I, 8</span>, v. <a href=\"#\" data-headword=\"מַיִם\">מַיִם</a>.</div><div class=\"sense\"><b>—2)</b>  (trnsf.) <i>to strike, produce sound, play.</i> <span class=\"citation\">Yoma I, 7</span> <span dir=\"rtl\">מַכִּין לפניו באצבע וכ׳</span> snap their middle-fingers. <span class=\"citation\">Arakh. II, 3</span>, v. <a href=\"#\" data-headword=\"חָלִיל\">חָלִיל</a>; a. fr.</div></div>","alt":["נָכָה"]},"18907":{"h":"נְכֵי","r":"N00819","html":"<div class=\"sense\"><b>Pa. נַכֵּי</b> <div class=\"sense\"><i>to deduct</i>. <span class=\"citation\">Targ. Y. Lev. XXVII, 18</span>.—Y. Sot. V, 20ᶜ bot.; Y. Ber. IX, 14ᵇ bot. <span dir=\"rtl\">אנא מְנַכֵּי</span>, v. <a href=\"#\" data-headword=\"הַנְכָּיָה\">הַנְכָּיָה</a>. <span class=\"citation\">Sabb. 140ᵃ</span> <span dir=\"rtl\">מְנַכּוּ</span>, v. <a href=\"#\" data-headword=\"זְכוּתָא\">זְכוּתָא</a>. <span class=\"citation\">B. Kam. 97ᵇ</span>, sq. <span dir=\"rtl\">אי מחמת … מְנַכִּינָן ליה וכ׳</span> if provisions have become cheaper in consequence of the increased weight of the coin, we impose upon the creditor a corresponding reduction of the debt &amp;c.; a. fr.</div></div><div class=\"sense\"><b>Ithpe. אִינְּכֵי  אִנְּכֵי</b> <div class=\"sense\"><i>to be injured, suffer</i>. Y. Ab. Zar. II, 41ᵈ top <span dir=\"rtl\">אשתון … ואִנְּכוּן</span> the first drank and did not die, but were sick; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ולא מייתין אינכון</span> read <span dir=\"rtl\">ואִי׳</span>; (Y. Ter. VIII, 45ᵈ bot. only <span dir=\"rtl\">מייתין</span>). Y. Dem. I, 22ᵃ top <span dir=\"rtl\">ולא אנכון</span> and they suffered no more (from mice). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יעבור ולא מִנְּכָה</span> let him cross, he shall not be injured. Y. Keth. XII, 35ᵇ top <span dir=\"rtl\">כל הן דהוא מהו מִנְּכֵי</span> wherever he be buried, what does he lose (what difference does it make to him)?; Y. Kil. IX, 32ᶜ top <a href=\"#\" data-headword=\"טנכי\">טנכי</a> (corr. acc.).</div></div><div class=\"sense\"><b>Af. אַכֵּי</b> <div class=\"sense\"><i>to harm</i>. Y. Sabb. III, 6ᵃ bot. (in Hebr. dict.) <span dir=\"rtl\">ומַכֵּי הוא לה כלום</span> can he harm her in any manner?; Y. Bets. II, 61ᶜ</div></div>","alt":["נְכָא"]},"18908":{"h":"נַכַּי","r":"N00820","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכֵי\">preced.</a> wds.) <i>deduction</i>. <span class=\"citation\">B. Kam. 59ᵃ</span> <span dir=\"rtl\">נכי חיה</span> payment is made with a deduction of the expense for the midwife (which the husband now saves); <span dir=\"rtl\">נ׳ מזונות</span> a deduction for nursing expenses (incident to a regular confinement). Y. ib. VIII, beg. 6ᵇ <span dir=\"rtl\">נותנין נכאי מזון</span> the injured person must be fully indemnified, deducting what his ordinary alimentation would have cost; Tosef. ib. IX, 3 נכי מזון Var. (ed. Zuck. <span dir=\"rtl\">דמי ניזק</span>, oth. var. <a href=\"#\" data-headword=\"זכי\">זכי</a>, <span dir=\"rtl\">זבי</span>, corr. acc.).</div>","alt":["נַכַּאי"]},"18909":{"h":"נַכֵּי","r":"N00821","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַכַּי\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>deduction; less</i>. <span class=\"citation\">Gitt. 15ᵇ</span>; <span class=\"citation\">B. Bath. 57ᵃ</span> <span dir=\"rtl\">נ׳ ריבעא</span> (the whole) less a quarter, i.e. <i>three fourths</i> (cmp. <a href=\"#\" data-headword=\"דַּל I\"><span dir=\"rtl\">דַּל</span> I</a>).</div><div class=\"sense\"><b>—2)</b> <i>loss, harm</i>. <span class=\"citation\">Y. Kidd. IV, 66ᵇ</span> bot. <span dir=\"rtl\">משם מה נַכְּיֵיה</span> because of ‘what is his loss?’, i.e. because it makes no difference in the law.</div>","alt":[]},"18910":{"h":"נַכְיָיתָא","r":"N00822","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נַכֵּי\">preced.</a> wds.) <i>reduction of a debt against a landed security</i> (<a href=\"#\" data-headword=\"מַשְׁכַּנְתָּא\">מַשְׁכַּנְתָּא</a>) <i>by deducting a stipulated amount every year for usufruct</i>. <span class=\"citation\">B. Mets. 67ᵇ</span> top <span dir=\"rtl\">האי משכנתא … לא ניכול אלא בנ׳</span> where the usage prevails that a land pledge can be redeemed at any time, the creditor must not have the usufruct except for the consideration of a rent deductible from the debt, v. <a href=\"#\" data-headword=\"מַשְׁכַּנְתָּא\">מַשְׁכַּנְתָּא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בלא נ׳</span> without paying any rent by deduction. <span class=\"citation\">Ib. 62ᵃ</span> <span dir=\"rtl\">משכנתא בלא נכיתא</span> (Rashi <span dir=\"rtl\">נכיי׳</span>) in the case of usufruct from pledged land without consideration; a. fr.—<span class=\"citation\">Y. Ber. IX, 14ᵇ</span> bot. <span dir=\"rtl\">מה נ׳</span> ed. Lehm., v. <a href=\"#\" data-headword=\"הַנְכָּיָה\">הַנְכָּיָיה</a>.</div>","alt":["נַכְיָתָא"]},"18911":{"h":"נְכֵיל","r":"N00823","html":"<div class=\"sense\"><i>to be crafty; to contrive</i>. <span class=\"citation\">Targ. Ps. LXXXIII, 4</span>.</div><div class=\"sense\"><b>Pa. נַכֵּיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נַכְיָיתָא\">same</a>; (with accus.) <i>to deceive</i>. <span class=\"citation\">Targ. O. Num. XXV, 18</span> ed. Berl. (oth. ed. <i>Pe</i>.). <span class=\"citation\">Targ. Ps. XII, 3</span> (ed. Wil. <span dir=\"rtl\">מנבל׳</span>). <span class=\"citation\">Targ. I Chr. XII, 17</span>.</div></div>","alt":["נְכֵל"]},"18912":{"h":"נְכִיל","r":"N00824","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכֵיל\">preced.</a>) <i>craftiness, fraud</i>. <span class=\"citation\">Targ. Mal. I, 14</span> (ed. Lag. <span dir=\"rtl\">נכל</span>).</div>","alt":[]},"18913":{"h":"נָכִיל","r":"N00825","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכִיל\">preced.</a>) <i>crafty, deceitful</i>. <span class=\"citation\">Targ. Ps. XLIII, 1</span>. <span class=\"citation\">Targ. Jer. IX, 2</span>. <span class=\"citation\">Targ. Ps. CXX, 2</span>; a. e.—<span class=\"citation\">Targ. Hos. VII, 16</span> (ed. Lag. <a href=\"#\" data-headword=\"נִיכְלָא\">נִיכְלָא</a>).</div>","alt":["נְכִילָא","נְכִילָא","נְכִילְתָּא"]},"18914":{"h":"נְכִילוּ","r":"N00826","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"נְכִיל\">נְכִיל</a>. <span class=\"citation\">Targ. Ex. XXI, 14</span>; a. e.—<span class=\"citation\">Targ. Ps. X, 2</span> נכילו׳ Ms. (ed. <a href=\"#\" data-headword=\"נִכְלוּתָא\">נִכְלוּתָא</a>; Regia <a href=\"#\" data-headword=\"נְכִילְתָּא\">נְכִילְתָּא</a>). <span class=\"citation\">Targ. Job V, 16</span> <a href=\"#\" data-headword=\"נִכְלוּתָא\">נְכֶלְתָּא</a> ed. Wil. (ed. Lag. <a href=\"#\" data-headword=\"נְבֵילָא\">נבילתא</a>, h. text <span dir=\"rtl\">עלתה</span>).</div>","alt":["נְכִילוּתָא"]},"18915":{"h":"נְכִילְתָּא","r":"N00827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָכִיל\">נָכִיל</a>, a. <a href=\"#\" data-headword=\"נְכִילוּ\">preced.</a></div>","alt":[]},"18916":{"h":"נְכֵיס","r":"N00828","html":"<div class=\"sense\"><i>to slaughter</i>, v. <a href=\"#\" data-headword=\"נְכַס\">נְכַס</a>.</div>","alt":[]},"18917":{"h":"נְכִיס","r":"N00829","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכֵיס\">preced.</a>) <i>slaughtered</i>. <span class=\"citation\">Targ. Lev. XIV, 6</span> (O. ed. Amst. <a href=\"#\" data-headword=\"נִכְלוּתָא\">נְכֶסְתָּא</a>). <span class=\"citation\">Ib. 51</span> (O. ed. Vien. <a href=\"#\" data-headword=\"נְכִיס\">נְכֵיסְתָּא</a>); a. e.</div>","alt":["נְכִיסָא","נְכִיסְתָּא"]},"18918":{"h":"נָכִישׁ","r":"N00830","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נִוכּוּשׁ</a> q. v.</div>","alt":[]},"18919":{"h":"נְכֵית","r":"N00831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְכַת\">נְכַת</a></div>","alt":[]},"18920":{"h":"נְכִיתָה","r":"N00832","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָכַת\">נָכַת</a>) <i>bite</i>; trnsf. <i>booty</i>. <span class=\"citation\">Cant. R. to III, 4</span> (play on <a href=\"#\" data-headword=\"נְכָתָה\">נכתה</a>, <span class=\"citation\">II Kings XX, 13</span>) <span dir=\"rtl\">נ׳ שנָכַת וכ׳</span> (some ed. <a href=\"#\" data-headword=\"נְכָתָה\">נְכָתָה</a></div>","alt":[]},"18921":{"h":"נְכֵל","r":"N00833","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְכֵיל\">נְכֵיל</a></div>","alt":[]},"18922":{"h":"נְכַל","r":"N00834","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכֵיל\">נְכֵיל</a>) </div><div class=\"sense\"><b>1)</b>  = b. h. <span dir=\"rtl\">נֵכֶל</span> <i>deceit</i>. <span class=\"citation\">Targ. Ps. XXIV, 4</span>; a. fr.—Pl. <span dir=\"rtl\">נִכְלִין</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. Is. LIII, 9</span> (not <span dir=\"rtl\">ניב׳</span>). <span class=\"citation\">Targ. Mic. VI, 12</span>. <span class=\"citation\">Targ. O. Num. XXV, 18</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>deceitful; hypocrite</i>, v. <a href=\"#\" data-headword=\"נְכָאלָא\">נְכָאלָא</a>, a. <a href=\"#\" data-headword=\"נָכִיל\">נָכִיל</a>.—Pl. <span dir=\"rtl\">נִכְלֵי</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Gen. R. s. 49</span>; <span class=\"citation\">Yalk. ib. 83</span>, v. <a href=\"#\" data-headword=\"נִפְלָא II\"><span dir=\"rtl\">נִבְלָא</span> II</a>.</div>","alt":["נִכְלָא","נִי׳"]},"18923":{"h":"נִכְלוּתָא","r":"N00835","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְכִילוּ\">נְכִילוּ</a></div>","alt":["נְכֶלְתָּא"]},"18924":{"h":"נָכַס","r":"N00836","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כָּסַס\">כָּסַס</a>) </div><div class=\"sense\"><b>1)</b> <i>to cut; to slaughter</i>. Imper. <a href=\"#\" data-headword=\"כּוֹס I\">כּוֹס</a>. <span class=\"citation\">Pes. 61ᵃ</span> (expl. <span dir=\"rtl\">תכסו</span>, <span class=\"citation\">Ex. XII, 4</span>) <span dir=\"rtl\">טלה זה לשון סורסי הוא … כוס לו</span> it is an abbreviated form (v. <a href=\"#\" data-headword=\"סוּרְסִי\">סוּרְסִי</a>), as one says to his neighbor, <i>kos</i> (for <span dir=\"rtl\">נְכוֹס</span>) &amp;c., cut this lamb for me; Y. ib. V, 32ᵃ bot.; Mekh. Bo. s. 3.—<span class=\"citation\">Snh. 82ᵇ</span> (play on <span dir=\"rtl\">כזבי</span>, <span class=\"citation\">Num. XXV, 15</span>) <span dir=\"rtl\">שאמרה לאביה כוס בי עם זה</span> she said to her father, cut (ruin) this people through me. <span class=\"citation\">Ḥull. 37ᵇ</span> <span dir=\"rtl\">בְּשַׂר כוס כוס</span> meat of an animal about which one says, ‘cut, cut’, i.e. meat of an animal hurriedly cut, because it threatens to die; Treat. Kuthim (ed. Kirchh., p. 33, sq.) we must not sell to Samaritans <a href=\"#\" data-headword=\"כּוּסְכּוּס\">כּוֹסְכּוֹס</a> (sub. <span dir=\"rtl\">בשר</span>) meat of an animal on the point of death.</div><div class=\"sense\"><b>—2)</b> <i>to mark, count</i>, v. <a href=\"#\" data-headword=\"נְכָסִים\">נְכָסִים</a>.</div>","alt":[]},"18925":{"h":"נְכַס","r":"N00837","html":"<div class=\"sense\"> ch. <a href=\"#\" data-headword=\"נָכַס\">same</a>; impf. <span dir=\"rtl\">יִכּוֹס</span>. <span class=\"citation\">Targ. Gen. XXXI, 54</span>. Ib. O. XXII, 10 <span dir=\"rtl\">למִיכַּס</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">למֵיכַס</span>); a. fr.—<span class=\"citation\">Snh. 25ᵇ</span> bot. <span dir=\"rtl\">והאידנא נ׳ אבא וכ׳</span> and presently he will slaughter the father for the son and the son for the father (he will exercise extortions). <span class=\"citation\">Y. Shebi. V, end, 36ᵃ</span> <span dir=\"rtl\">מִיכּוֹס תורא וכ׳</span> to slaughter an ox available for the plough; a. fr.</div><div class=\"sense\"><b>Ithpe. אִתְנְכֵס  אִתְנְכֵיס</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"נְכֵי\">אִינְּכֵיס</a> <i>to be slaughtered</i>. <span class=\"citation\">Targ. Lev. XIX, 6</span>; a. fr.—<span class=\"citation\">Gen. R. s. 33</span> <span dir=\"rtl\">אזל למִתְנַכְסָה וכ׳</span> was going to be slaughtered, and it lowed, as if to say, save me; Y. Keth. XII, 35ᵃ <span dir=\"rtl\">מִינְּכֵיס</span>; Y. Kil. IX, 32ᵇ <span dir=\"rtl\">מִנְּכִס</span> taken to be slaughtered.</div></div>","alt":["נְכֵיס"]},"18926":{"h":"נִכְסָא","r":"N00838","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכַס\">preced.</a>) <i>slaughter; slaughtering</i> (according to the ritual, <a href=\"#\" data-headword=\"שְׁחִיטָה\">שְׁחִיטָה</a>); <i>sacrifice, feast</i> (= h. <a href=\"#\" data-headword=\"זֶבַח\">זֶבַח</a>). <span class=\"citation\">Targ. Is. XXXIV, 6</span> (h. text <span dir=\"rtl\">טבח</span>).—<span class=\"citation\">Targ. Y. Deut. XIV, 21</span>. <span class=\"citation\">Targ. Y. Lev. XVII, 13</span> (ed. Vien. <span dir=\"rtl\">נִיכְסַתֵּיה</span>). <span class=\"citation\">Targ. Gen. XXXI, 45</span>; a. fr.—<span class=\"citation\">Targ. Y. Gen. XLIII, 16</span> <span dir=\"rtl\">בות נ׳</span> the place for ritual cutting <span dir=\"rtl\">(בות השחיטה</span>), <i>ritually cut throat</i>.—<span class=\"citation\">B. Bath. 92ᵃ</span> <span dir=\"rtl\">אי גברא דזבין לנ׳ לנ׳</span> if it is a man that sells cattle for food, the purchase was made for slaughtering (and not for work); <span class=\"citation\">B. Kam. 46ᵃ</span> (not <span dir=\"rtl\">לנכסותא</span>; v. Rabb. D. S. a. l.); a. fr.—Pl. <span dir=\"rtl\">נִכְסָן</span>, <a href=\"#\" data-headword=\"נִכְסָא\">נִכְסָתָא</a>; constr. <span dir=\"rtl\">נִכְסַת</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>; (also <a href=\"#\" data-headword=\"נִכְסִין\">נִכְסִין</a>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>). <span class=\"citation\">Targ. O. Ex. XXXII, 6</span> <span dir=\"rtl\">ניכסן</span> ed. Berl. (oth. ed. a. Y. <span dir=\"rtl\">ניכסין</span>). Ib. XVIII, 12; a. fr.—<span class=\"citation\">Targ. Ps. CVI, 28</span> <a href=\"#\" data-headword=\"נִכְסִין\">נִכְסֵי</a> (Ms. <span dir=\"rtl\">נכסת</span>).</div>","alt":["נִכְסְתָא","נִי׳"]},"18927":{"h":"נכסותא","r":"N00839","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִכְסָא\">preced.</a></div>","alt":[]},"18928":{"h":"נִכְסַיָּא","r":"N00840","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִכְסִין\">נִכְסִין</a></div>","alt":[]},"18929":{"h":"נְכָסִים","r":"N00841","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> [<i>counted things</i>,] <i>account; property, business</i>. <span class=\"citation\">Ber. 46ᵃ</span> <span dir=\"rtl\">ויצלח מאד בכל נְכָסָיו ויהיו נכסיו ונְכָסֵינוּ וכ׳</span> may he have great success in all his accounts (enterprises), and may his business and ours be successful and near a city. <span class=\"citation\">Ab. Zar. 19ᵇ</span>, v. <a href=\"#\" data-headword=\"צָלַח\">צָלַח</a>. <span class=\"citation\">B. Bath. IX, 7</span>, a. fr. <span dir=\"rtl\">נ׳ שיש להן אחריות</span>, v. <a href=\"#\" data-headword=\"אַחֲרָיוּת\">אַחֲרָיוּת</a>. Ib. <span dir=\"rtl\">המחלק נכסיו וכ׳</span> if a person disposes of his belongings by word of mouth. <span class=\"citation\">Yeb. IV, 3</span> <span dir=\"rtl\">נ׳ הנכנסים וכ׳</span> property which the wife brings in and takes out again (v. <a href=\"#\" data-headword=\"מְלוֹג\">מְלוֹג</a>). <span class=\"citation\">B. Kam. I, 2</span> נ׳ של בני ברית Jewish property; <span dir=\"rtl\">נ׳ המיוחדין</span> individual property; a. v. fr.</div>","alt":[]},"18930":{"h":"נִכְסִין","r":"N00842","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Num. XXXII, 1</span> (h. text <a href=\"#\" data-headword=\"מִקְנֶה\">מקנה</a>) <i>herds</i>. <span class=\"citation\">Targ. Josh. XXII, 8</span> (h. text <a href=\"#\" data-headword=\"נְכָסִים\">נכסים</a>). <span class=\"citation\">Targ. Deut. VIII, 17</span> (h. text <span dir=\"rtl\">הַיִל</span>); a. fr.—<span class=\"citation\">B. Kam. 93ᵃ</span> (prov.) <span dir=\"rtl\">בתר מרא נ׳ וכ׳</span> behind a man of wealth chips are dragged along, i.e. in the company of a wealthy man you have an opportunity of making money. <span class=\"citation\">Bekh. 48ᵃ</span> הא אשתעבד נ׳ Rashi (read: <span dir=\"rtl\">אשתעבוד</span>; ed. <span dir=\"rtl\">אשתעבדן להו לנ׳</span>) has not the estate been made responsible for the debt (before the father’s death)? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכדי נ׳ דבר וכ׳</span> does not a person’s property merely take the place of a guarantor? <span class=\"citation\">B. Bath. 58ᵃ</span> <span dir=\"rtl\">כל נִכְסַי לחד ברא</span> all my property shall go to one son (of mine). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כולהו נִכְסֵי דהאי</span> all the property (of the father) goes to this (son).</div>","alt":["נִכְסַיָּא","נִכְסֵי","נִי׳"]},"18931":{"h":"נכְסְתָא","r":"N00843","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִכְסָא\">נִכְסָא</a></div>","alt":[]},"18932":{"h":"נִכְפֶּה","r":"N00844","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כפי\">כָּפָה</a></div>","alt":[]},"18933":{"h":"נָכַר","r":"N00845","html":"<div class=\"sense\"> (b. h.) <i>to be unknown, strange</i>.</div><div class=\"sense\"><b>Hif. הִכִּיר</b> <div class=\"sense\"><b>1)</b> <i>to recognize, know; to favor</i>. <span class=\"citation\">Ruth R. to II, 10</span> (ref. to <span dir=\"rtl\">להכירני</span>, ib.) <span dir=\"rtl\">נתנבאה … להַכִּירָהּ כדרך וכ׳</span> she prophesied that he would know her in the way of all people (as his wife, cmp. <a href=\"#\" data-headword=\"יָדַע\">יָדַע</a>). <span class=\"citation\">Ber. 10ᵇ</span> <span dir=\"rtl\">האשה מַכֶּרֶת באורחין וכ׳</span> woman recognizes the character of guests better than man. <span class=\"citation\">R. Hash. II, 1</span> <span dir=\"rtl\">אם אינן מַכִּירִין אותו</span> if the court does not know him personally. Y. Yeb. IV, 6ᵇ <span dir=\"rtl\">כנסה ולא הִכִּירָהּ</span> he married her but did not touch her (v. supra). <span class=\"citation\">Snh. 7ᵇ</span> (ref. to <span class=\"citation\">Deut. I, 17</span>) <span dir=\"rtl\">לא תַכִּירֵהוּ</span> thou shalt not favor him (if he is thy friend); a. fr.—<span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">במקום שמכיר</span> where he knows (the people), where he is acquainted; <span class=\"citation\">Sifré Num. 14</span> <span dir=\"rtl\">במקום שמכירין אותו</span>.</div><div class=\"sense\"><b>—2)</b> <i>to make known, identify; to acknowledge, own</i>. R. Hash. l. c. <span dir=\"rtl\">מן המכירים</span> on the declaration of those who identify (the witnesses; v. Rabb. D. S. a. l. note 2). <span class=\"citation\">Gen. R. s. 43</span> <span dir=\"rtl\">לא היה שמי ניכר … והִכַּרְתָּ אותי וכ׳</span> my name was unknown … and thou hast made me known among my creatures. <span class=\"citation\">Sifré Deut. 217</span>; <span class=\"citation\">Kidd. 78ᵇ</span>, a. e. (ref. to <span dir=\"rtl\">יכיר</span>, <span class=\"citation\">Deut. XXI, 17</span>) <span dir=\"rtl\">יַכִּירֶנּוּ לאחרים</span> he may identify him before others (as his first born son). <span class=\"citation\">Sifré Deut. 312</span> <span dir=\"rtl\">שאהיה מַכִּירוֹ</span> that I may make it known as mine. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מהיכן המקום מַכִּיר את חלקו</span> beginning with whom does the Lord acknowledge his share (claim as his)? With Jacob; a. fr.</div></div><div class=\"sense\"><b>Hof. הוּכָּר</b> <div class=\"sense\"><i>to be recognized; to be discernible</i>. <span class=\"citation\">Kidd. III, 5</span> <span dir=\"rtl\">ה׳ עוברה</span> her pregnancy was certain, v. <a href=\"#\" data-headword=\"הַכָּרָה\">הַכָּרָה</a>; <span class=\"citation\">ib. 62ᵇ</span>. <span class=\"citation\">B. Mets. 93ᵇ</span> <span dir=\"rtl\">ה׳ הגנב</span> the thief was found out; a. e.</div></div><div class=\"sense\"><b>Nif. נִיכַּר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"נִכְפֶּה\">same</a>. Part. <a href=\"#\" data-headword=\"נָכַר\">נִיכָּר</a>. <span class=\"citation\">Ber. 28ᵃ</span> <span dir=\"rtl\">מכותלי … אתה נ׳ וכ׳</span> by the walls of thy house, one sees that thou art a smith. <span class=\"citation\">Kidd. 31ᵃ</span> <span dir=\"rtl\">מסוף דברך נ׳ וכ׳</span> from thy last words (the fifth and following commandments of the decalogue) it is seen that thy first one is true. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מבין ריסי עיניך נ׳</span>, v. <a href=\"#\" data-headword=\"רִיס I\">רִיס</a>. <span class=\"citation\">Gitt. 53ᵃ</span> <span dir=\"rtl\">שאינו נ׳</span>, v. <a href=\"#\" data-headword=\"הֶיזֵּק\">הֶיזֵּק</a>. <span class=\"citation\">Sabb. 91ᵇ</span> <span dir=\"rtl\">מקומו נ׳</span> its location is discernible. <span class=\"citation\">Sot. 9ᵇ</span> <span dir=\"rtl\">נִיכָּרִין דברי אמת</span> words of truth are easily recognized. <span class=\"citation\">Gen. R. s. 43</span>, v. supra; a. fr.</div></div><div class=\"sense\"><b>Pi. נִכֵּר</b> <div class=\"sense\"><i>to treat as a stranger, ignore; to discriminate against</i>. Snh. l. c. (ref. to <span class=\"citation\">Deut. I, 17</span>) <span dir=\"rtl\">לא תְנַכְּרֵהוּ</span> (if he is thy enemy) do not discriminate against him (v. supra). <span class=\"citation\">Sifré Deut. 322</span> <span dir=\"rtl\">בשעת … מְנַכְּרִים וכ׳</span> when Israel is in trouble, the nations ignore them and act as though they did not know them; a. e.</div></div>","alt":[]},"18934":{"h":"נְכַר","r":"N00846","html":"<div class=\"sense\">; <i>Af</i>. <span dir=\"rtl\">אַכֵּר</span> <i>to recognize, know</i>. <span class=\"citation\">Targ. Y. I Gen. XXXVIII, 25</span>, sq.</div><div class=\"sense\"><b>Ithpa. אִינַּכַּר</b> <div class=\"sense\"><i>to be distinguishable</i>. <span class=\"citation\">B. Kam. 5ᵃ</span> <span dir=\"rtl\">דמִינַּכְּרָא</span>, v. <span dir=\"rtl\">הֶיוֵּקָא</span>. <span class=\"citation\">Ib. 97ᵃ</span> <span dir=\"rtl\">מִינַּכַּר היזיקה</span> its reduction in value is distinguishable.</div></div><div class=\"sense\"><b>Pa. נַכֵּר</b> <div class=\"sense\"><i>to make strange, remove</i>. <span class=\"citation\">Sabb. 82ᵇ</span> (ref. to <span dir=\"rtl\">תזרם</span>, <span class=\"citation\">Is. XXX, 22</span>) <span dir=\"rtl\">נַכְּרִינְהוּ מינך כַּוָּר</span> (v. Rabb. D. S. a. l. note) remove them from thee like a strange (disgusting) thing.</div></div>","alt":[]},"18935":{"h":"נָכְרִי","r":"N00847","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"נְכַר\">preced.</a> wds.) <i>stranger, gentile</i>. [In editions published under the censor’s supervision, our w. is frequently changed into <span dir=\"rtl\">עכו&quot;ם</span>, <a href=\"#\" data-headword=\"גּוֹי\">גּוֹי</a>, <a href=\"#\" data-headword=\"כּוּשִׁי\">כּוּשִׁי</a>, <a href=\"#\" data-headword=\"כּוּתִי I\">כּוּתִי</a> &amp;c.] <span class=\"citation\">Ab. Zar. IV, 4</span> (<span class=\"citation\">51ᵇ</span>; <span class=\"citation\">52ᵇ</span>; Mish. ed. <span dir=\"rtl\">עכו&quot;ם</span>). <span class=\"citation\">Sabb. 31ᵃ</span>; a. v. fr.—Pl. <a href=\"#\" data-headword=\"נָכְרִי\">נָכְרִים</a>. <span class=\"citation\">Ḥull. 13ᵇ</span> <span dir=\"rtl\">נ׳ שבחוצה לארץ לאו עובדי ע&quot;ז וכ׳</span> gentiles outside of Palestine are not to be considered as idolaters, they only continue their fathers’ customs. <span class=\"citation\">Gitt. 61ᵃ</span> <span dir=\"rtl\">מפרנסין עניי נ׳ וכ׳</span> we must support the poor of the gentiles &amp;c.; (Tosef. ib. V (III), 4 <span dir=\"rtl\">גוים</span>). <span class=\"citation\">Gitt. V, 9</span> (<span class=\"citation\">61ᵃ</span>) <span dir=\"rtl\">מספידין מתי נ׳ וכ׳</span> (Mish. ed. <span dir=\"rtl\">עכו&quot;ם</span>) we must lament for the dead of the gentiles &amp;c.; a. v. fr.—Fem. <a href=\"#\" data-headword=\"נָכְרִי\">נָכְרִית</a>. <span class=\"citation\">Yeb. 17ᵃ</span>. <span class=\"citation\">Ib. III, 7</span> <span dir=\"rtl\">שלשה אחים … ואחד נשוי נ׳</span> in the case of three brothers, two of whom married two sisters, and one a stranger; a. fr.</div>","alt":[]},"18936":{"h":"נָכַשׁ","r":"N00848","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">כשכש</span>, <a href=\"#\" data-headword=\"קַשְׁקֵשׁ\">קשקש</a>) <i>to come in near contact</i>.</div><div class=\"sense\"><b>Pi. נִיכֵּשׁ</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מַכּוֹשׁ I\"><span dir=\"rtl\">מַכּוֹשׁ</span> I</a>) <i>to weed; to lop.</i> <span class=\"citation\">Kil. II, 5</span> <span dir=\"rtl\">אין מחייבין אותו לנַכֵּשׁ</span> the law does not bind him to pluck out (the plants which grow among the fenugrec). Ib. <span dir=\"rtl\">ואם נִכֵּשׁ</span> (Y. ed. <span dir=\"rtl\">ני׳</span>) but if he did &amp;c. Tosef. ib. I, 15 <span dir=\"rtl\">והמְנַכֵּשׁ</span> and he who does the weeding (in a field of mixed seeds); <span class=\"citation\">M. Kat. 2ᵇ</span>; a. fr. [<span class=\"citation\">B. Bath. 54ᵃ</span> Ms. R., v. <a href=\"#\" data-headword=\"מַכּוֹשׁ I\"><span dir=\"rtl\">מַכּוֹשׁ</span> I</a>.]</div></div><div class=\"sense\"><b>Hif. הִכִּישׁ</b> <div class=\"sense\"><b>1)</b> <i>to strike, wound, sting</i>. <span class=\"citation\">B. Mets. 30ᵇ</span>; <span class=\"citation\">B. Bath. 88ᵃ</span> <span dir=\"rtl\">הִבִּישָׁהּ</span> if he struck the lost beast which he took in charge. <span class=\"citation\">Gen. R. s. 30</span>, beg. <span dir=\"rtl\">הִכִּישׁוֹ ארי וכ׳</span> a lion struck and crippled him. <span class=\"citation\">B. Mets. 78ᵃ</span> <span dir=\"rtl\">הִכִּישָׁהּ נחש</span> a serpent bit her.</div><div class=\"sense\"><b>—2)</b> <i>to cause injury by contact</i>. <span class=\"citation\">B. Kam. 23ᵇ</span> <span dir=\"rtl\">מַכִּישׁ</span> (Ms. H. <a href=\"#\" data-headword=\"מְשִׁיךְ\">משיך</a>) he who caused a neighbor’s death by bringing the serpent’s tooth in contact with his neighbor’s body; <span class=\"citation\">Snh. 78ᵃ</span>. <span class=\"citation\">Yalk. Deut. 944</span> <span dir=\"rtl\">שמַכִּישִׁין</span>, v. <a href=\"#\" data-headword=\"קוּנְטְרִינִים\">קונטרינים</a>; <span class=\"citation\">Sifré Deut. 317</span> <span dir=\"rtl\">שמכינים</span> (corr. acc.).</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"מַכּוֹשׁ I\"><span dir=\"rtl\">מַכּוֹשׁ</span> I</a>) <i>to insert the hoe</i> or <i>spade</i>. <span class=\"citation\">B. Bath. 54ᵃ</span>, v. <a href=\"#\" data-headword=\"מַכּוֹשׁ I\"><span dir=\"rtl\">מַכּוֹשׁ</span> I</a>.</div></div><div class=\"sense\"><b>Hithpa. הִתְנַכֵּשׁ</b> </div><div class=\"sense\"><b>Nif. נִכּוֹשׁ</b> <div class=\"sense\"><i>to be hoed for</i>. <span class=\"citation\">Gen. R. s. 45</span> <span dir=\"rtl\">הקוצים … לא מִתְנַכְּשִׁין ולא נזרעין וכ׳</span> for thorns there is neither hoeing (digging over) nor sowing, but they grow of themselves, while wheat &amp;c.; <span class=\"citation\">Yalk. ib. 79</span> <span dir=\"rtl\">לא נִכּוֹשִׁין ולא נחרשים וכ׳</span></div></div>","alt":[]},"18937":{"h":"נְכַשׁ","r":"N00849","html":"<div class=\"sense\">; <i>Pa</i>. <a href=\"#\" data-headword=\"נָכִישׁ\">נַכֵּישׁ</a> <i>to bite</i>. <span class=\"citation\">Gen. R. s. 91</span> <span dir=\"rtl\">כן … מְנַכְּשָׁא … ואכלה וכ׳</span> so may this woman (I) take a bite of the flesh of this and eat; (<span class=\"citation\">Yalk. Gen. 148</span> only <a href=\"#\" data-headword=\"אָכְלָה I\">אכלה</a>); v. <a href=\"#\" data-headword=\"נְכַת\">נְכַת</a>.</div><div class=\"sense\"><b>Af. אַנְכֵּישׁ</b> <div class=\"sense\"><i>to weed</i>. <span class=\"citation\">B. Mets. 105ᵃ</span> מַנְכִּישְׁנָא וכ׳ I shall weed as much as is required for thy share.</div></div>","alt":[]},"18938":{"h":"נַּכָּשׁ","r":"N00850","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְכַשׁ\">preced.</a>) <i>he who lops trees</i>; v. <a href=\"#\" data-headword=\"נִיכּוּשׁ\">נִיכּוּשׁ</a>.</div>","alt":[]},"18939":{"h":"נָכַת","r":"N00851","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"נְכַת\">next w.</a>) <i>to bite</i>. <span class=\"citation\">Cant. R. to III, 4</span>; v. <a href=\"#\" data-headword=\"נְכִיתָה\">נְכִיתָה</a>.</div>","alt":[]},"18940":{"h":"נְכַת","r":"N00852","html":"<div class=\"sense\"> (cmp. <span dir=\"rtl\">כתת</span>; v. <span dir=\"rtl\">נכש</span>) <i>to wound, bite, injure</i>. <span class=\"citation\">Targ. Num. XXI, 9</span>. <span class=\"citation\">Ib. 6</span> (ed. Berl. <span dir=\"rtl\">נַכִּיתוּ</span> <i>Pa</i>.); a. fr.—<span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">חיויא דבעי למִיכַּת וכ׳</span> the serpent that is to bite my son. <span class=\"citation\">Y. Peah I, 16ᵃ</span> bot. [read:] <span dir=\"rtl\">אילולי דאתאמר … נְכוֹת לא הוינא נָכֵית</span> had I not been told from on high, ‘bite’, I should not bite. <span class=\"citation\">Koh. R. to VII, 1</span> <span dir=\"rtl\">מאן דנַכְתֵיה וכ׳</span>, v. <a href=\"#\" data-headword=\"דּחֵיל\">דְּחֵיל</a>. <span class=\"citation\">Gitt. 67ᵇ</span> (expl. <a href=\"#\" data-headword=\"קוּרְדְּיָיקוֹס\">קורדייקוס</a>) <span dir=\"rtl\">דנכתיה חמרא וכ׳</span> young wine from the press has bitten him (made him delirious). <span class=\"citation\">B. Mets. 60ᵇ</span> <span dir=\"rtl\">נשך איכא דקא נכית ליה וכ׳</span> it is <i>neshekh</i> (usury, v. <a href=\"#\" data-headword=\"נֶשֶׁךְ\">נֶשֶׁךְ</a>), for he bites (injures) him, by taking from him something which he (the creditor) had not given him; a. fr.</div><div class=\"sense\"><b>Pa. נַכֵּית</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"נָכַת\">same</a>. <span class=\"citation\">Targ. O. Num. XXI, 6</span>, v. supra.—<span class=\"citation\">Ab. Zar. 35ᵇ</span> <span dir=\"rtl\">היה מְנַכֵּית ואכיל וכ׳</span></div><div class=\"sense\"><b>—2)</b> <i>to cause to bite</i>. <span class=\"citation\">Yeb. 76ᵃ</span> <span dir=\"rtl\">מייתינן … ומְנַכְּתִינָן ליה וכ׳</span> we get a big ant and let it bite (insert its head into the opening) and cut its head off.</div></div><div class=\"sense\"><b>Ithpe. אִינְכֵית  אִינְּכֵית</b> <div class=\"sense\"><i>to be bitten, stung</i>. <span class=\"citation\">Targ. O. Num. XXI, 8</span>. <span class=\"citation\">Targ. Y. II ib. 9</span>.</div></div>","alt":["נְכֵית"]},"18941":{"h":"נְכָתָה","r":"N00853","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְכִיתָה\">נְכִיתָה</a></div>","alt":[]},"18942":{"h":"נִכְתְּמָא","r":"N00854","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כתם</span>) (<i>wooden</i>) <i>lid</i> of a water pitcher. <span class=\"citation\">Bets. 30ᵃ</span>. <span class=\"citation\">B. Bath. 26ᵃ</span> top <span dir=\"rtl\">כדנייד נ׳ וכ׳</span> as much as a lid on a pitcher shakes. <span class=\"citation\">Sabb. 105ᵇ</span>. <span class=\"citation\">Pes. 112ᵃ</span></div>","alt":[]},"18943":{"h":"נָם","r":"N00855","html":"<div class=\"sense\"> perf. of <a href=\"#\" data-headword=\"נוּם\">נוּם</a>.</div>","alt":[]},"18944":{"h":"נָמָא","r":"N00856","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"נִימָּא\">נִימָּא</a>, <a href=\"#\" data-headword=\"נִימָה\">נִימָּה</a>, v. <a href=\"#\" data-headword=\"נוּם I\"><span dir=\"rtl\">נוּם</span> I</a>.</div>","alt":["נָמָה"]},"18945":{"h":"נְמוֹיָיה","r":"N00857","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְמָיָה\">נְמָיָה</a></div>","alt":[]},"18946":{"h":"נָמוֹךְ","r":"N00858","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>low, lowly</i>, v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>.—Pl. <span dir=\"rtl\">נְמוּכִים</span>; <span dir=\"rtl\">נְמוּכוֹת</span>. <span class=\"citation\">Num. R. s. 19</span> <span dir=\"rtl\">בגבוה שבגבוהים ובנמוך שבנ׳</span> with the highest of the high (the cedar) and the lowest of the low (the hyssop). <span class=\"citation\">Sot. 5ᵇ</span> <span dir=\"rtl\">נְמוּכֵי הרוח</span> the humble. <span class=\"citation\">Koh. R. to IX, 10</span> <span dir=\"rtl\">פניהם נ׳</span> with downcast countenances, opp. <span dir=\"rtl\">זקופות</span>; a. fr.</div>","alt":["נְמוּכָה"]},"18947":{"h":"נִמוֹס","r":"N00859","html":"<div class=\"sense\"><i>law</i>, v. <a href=\"#\" data-headword=\"אַבְנִימוֹס\">נִימוֹס</a>.</div>","alt":[]},"18948":{"h":"נִמּוֹס","r":"N00860","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>.—[<span class=\"citation\">Tosef. Bekh. IV, 16</span>, read: <a href=\"#\" data-headword=\"גָּלוּם\">גָּמוּם</a>, v. <a href=\"#\" data-headword=\"גָּמַם\">גָּמַם</a>.]</div>","alt":[]},"18949":{"h":"נִמּוֹק","r":"N00861","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מָקַק\">מָקַק</a></div>","alt":[]},"18950":{"h":"נִמּוּק","r":"N00862","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִימּוּק\">נִימּוּק</a></div>","alt":[]},"18951":{"h":"נְמוֹר","r":"N00863","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְמַר\">נְמַר</a>) <i>speckled</i>. <span class=\"citation\">Targ. Gen. XXX, 32</span>, sq.—Pl. <a href=\"#\" data-headword=\"נְמוֹרִין\">נְמוֹרִין</a>; f. <span dir=\"rtl\">נְמוֹרָתָא</span>. <span class=\"citation\">Targ. O. ib. 39</span>. <span class=\"citation\">Ib. 35</span> <span dir=\"rtl\">נְמוֹרְתָא</span>; Y. ib. <a href=\"#\" data-headword=\"נְעוֹרְתָּא\">נְמוֹרְתָּא</a> (corr. acc.).</div>","alt":[]},"18952":{"h":"נְמוֹרֵי","r":"N00864","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"נְמִירֵי\">נְמִירֵי</a></div>","alt":[]},"18953":{"h":"נְמוֹרִין","r":"N00865","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"נִמְרֵי\">נִמְרִין</a></div>","alt":[]},"18954":{"h":"נמורקין","r":"N00866","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גמורקין\">גמורקין</a></div>","alt":[]},"18955":{"h":"נַמְטָא","r":"N00867","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מוּט\">מוּט</a> or <a href=\"#\" data-headword=\"מְטֵי\">מְטֵי</a>) <i>felt-mattress, felt-cloth</i>. <span class=\"citation\">Yoma 69ᵃ</span>; <span class=\"citation\">Bets. 15ᵃ</span>, v. <a href=\"#\" data-headword=\"גְּמַד\">גְּמַד</a>.—Pl. <span dir=\"rtl\">נַמְטֵי</span>. <span class=\"citation\">B. Mets. 84ᵇ</span>, v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a> ch. <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">מאי בגדים נ׳</span> what kind of garments is meant? Felt-spreadings; <span class=\"citation\">ib. 93ᵇ</span></div>","alt":[]},"18956":{"h":"נֹמִי","r":"N00868","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוֹמִי\">נוֹמִי</a></div>","alt":[]},"18957":{"h":"נַמִּי","r":"N00869","html":"<div class=\"sense\"> adv. (= <span dir=\"rtl\">נְהֵי מִי</span>; cmp. <span dir=\"rtl\">ויהי מה</span> <span class=\"citation\">II Sam. XVIII, 23</span>) <i>at all events, really, even, likewise</i>. <span class=\"citation\">Pes. 102ᵃ</span> נימא ניהוי תיובתיה נ׳ מהא Ms. M. (ed. <span dir=\"rtl\">נימא מהא נ׳ תיהוי תיובתא</span>) I mean to say, at all events (even if the previous objection could be met) he will stand refuted from this citation; <span class=\"citation\">Erub. 30ᵃ</span>. <span class=\"citation\">Pes. 114ᵃ</span>, a. fr. <span dir=\"rtl\">הכא נ׳</span> (abbrev. <span dir=\"rtl\">ה&quot;נ</span>), v. <a href=\"#\" data-headword=\"הָכָא\">הָכָא</a>. <span class=\"citation\">Yoma 64ᵃ</span> <span dir=\"rtl\">נהי נ׳</span>, v. <a href=\"#\" data-headword=\"נְהֵי I\"><span dir=\"rtl\">נְהֵי</span> II</a>.—<span dir=\"rtl\">הכי נ׳</span> (abbrev. <span dir=\"rtl\">ה&quot;נ</span>) <i>it is really so; is it really so?</i> <span class=\"citation\">Ḥag. 11ᵇ</span> <span dir=\"rtl\">ה&quot;נ</span> will you say, it is really so (that this subject must be taught only in the presence of three students)? <span class=\"citation\">Ḥull. 11ᵇ</span> sq. <span dir=\"rtl\">ה&quot;נ דלא וכ׳</span> (will you say) it is really so that he ate no meat?; <span dir=\"rtl\">וכי תימא ה&quot;נ וכ׳</span> and if you will say, ‘yes, it is so’, what about sacred meat? Ib. 12ᵃ <span dir=\"rtl\">אפי׳ תרומה נ׳</span> then you must say ‘yes’ even with regard to T’rumah; <span dir=\"rtl\">אפי׳ שחיטה נ׳ לא</span> then you must say ‘no’ even with regard to slaughtering. Ib. <span dir=\"rtl\">אי נ׳ שמע אינש אחרינא</span> Rashi (ed. incorr.) even if another person did overhear it. Ib. 51ᵃ <span dir=\"rtl\">והאי נ׳ וכ׳</span> and this animal has really measured its strength. <span class=\"citation\">B. Mets. 98ᵃ</span>, a. fr. <span dir=\"rtl\">אי נ׳</span> or indeed (which would be better).—<span class=\"citation\">R. Hash. 22ᵇ</span>, a. fr. <span dir=\"rtl\">הכי נ׳ מסתברא</span> so, indeed, it stands to reason. Ib., a. fr. <span dir=\"rtl\">תניא נ׳ הכי</span> so, indeed, it has been taught. <span class=\"citation\">Ber. 4ᵇ</span> <span dir=\"rtl\">מה קימה … אף שכיבה נ׳ וכ׳</span> as on getting up you must recite …, so on lying down likewise &amp;c.; a. v. fr.</div>","alt":[]},"18958":{"h":"נְמָיָא","r":"N00870","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְמָיָה\">נְמָיָה</a></div>","alt":[]},"18959":{"h":"נְמִיגָה","r":"N00871","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <span dir=\"rtl\">נָמוֹג</span>, Nif. of <a href=\"#\" data-headword=\"מוּג\">מוּג</a>) <i>melting, loss of courage</i>. Mekh. B’shall., Shir., s. 9 (ref. to <span dir=\"rtl\">נמגו</span>, <span class=\"citation\">Ex. XV, 15</span>) <span dir=\"rtl\">אין נ׳ אלא נמיסה</span> the root <span dir=\"rtl\">מוג</span> is synonymous with <span dir=\"rtl\">מסס</span>; <span class=\"citation\">Yalk. Ex. 251</span> <span dir=\"rtl\">אין נ׳ אלא מסייה</span>.</div>","alt":[]},"18960":{"h":"נְמִיָּה","r":"N00872","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (supposed to be) <i>marten</i>. <span class=\"citation\">Ḥull. 52ᵇ</span>. <span class=\"citation\">B. Bath. II, 5</span>. Y’lamd. to Gen. XVI, 5, v. <a href=\"#\" data-headword=\"חָמַס\">חָמַס</a>; a. fr.</div>","alt":["נְמִיָּיה"]},"18961":{"h":"נְמָיָה","r":"N00873","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נמי</span>, dialect. corresp. to <a href=\"#\" data-headword=\"נבי I\">נבי</a>; cmp. Arab. <i>namay</i>) <i>sproutings</i>, v. <a href=\"#\" data-headword=\"נְבָיָיה\">נְבָיָיה</a>. </div>","alt":["נְמָיָיה"]},"18962":{"h":"נמיטרין","r":"N00874","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 868</span>, v. <a href=\"#\" data-headword=\"מִיטְרִין\">מִיטְרִין</a></div>","alt":[]},"18963":{"h":"נְמָיָיה","r":"N00875","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְמָיָה\">נְמָיָה</a></div>","alt":[]},"18964":{"h":"נְמִיָּיה","r":"N00876","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נְמִיָּה\">נְמִיָּה</a></div>","alt":[]},"18965":{"h":"נָמֵיל","r":"N00877","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָמֵל\">נָמֵל</a></div>","alt":[]},"18966":{"h":"נְמִיסָה","r":"N00878","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מָסַס\">נָמַס</a>, Nif. of <a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>) <i>melting, loss of courage</i>. Mekh. B’shall., Shir., s. 9, v. <a href=\"#\" data-headword=\"נְמִיגָה\">נְמִיגָה</a>.</div>","alt":[]},"18967":{"h":"נְמִירֵי","r":"N00879","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>N’miré</i>, a twin-town of (Hash-)Shulami, separated from it by the Jordan. <span class=\"citation\">Tosef. Bekh. VII, 3</span> <span dir=\"rtl\">כגון השולמי וכ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">מנרי</span>, corrupt.) like Hash-Sh. and N., being two autonomous places (v. <a href=\"#\" data-headword=\"*אַבְטוֹנִיּוֹת\">אַבְטוֹנִיּוֹת</a>); <span class=\"citation\">Bekh. 55ᵃ</span> <span dir=\"rtl\">של נמר ונמורי</span> (corr. acc.); <span class=\"citation\">Y. B. Bath. III, 14ᵃ</span> top <span dir=\"rtl\">שלומי ונבירו</span>.</div>","alt":[]},"18968":{"h":"נָמַךְ","r":"N00880","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"מוּךְ\">מוּךְ</a>, a. <a href=\"#\" data-headword=\"נָמוֹךְ\">נָמוֹךְ</a>), <i>Hif.</i> הִנְמִיךְ <i>to lower</i>. <span class=\"citation\">Sifré Num. 83</span> <span dir=\"rtl\">הגבוה מַנְמִיכוֹ וכ׳</span> every hilly place he lowered, and every depression he raised; <span class=\"citation\">Yalk. Ex. 228</span>.—<span class=\"citation\">Ber. 45ᵃ</span> יַנְמִיךְ הקורא קולו Ms. F. (v. Rabb. D. S. a. l. note 6; ed. <span dir=\"rtl\">ימעך</span>) the reader must temper his voice.</div>","alt":[]},"18969":{"h":"נָמֵל","r":"N00881","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a popular corrupt. of <a href=\"#\" data-headword=\"לְמֵין\">לְמֵין</a>, q. v.) <i>haven, bay</i>. <span class=\"citation\">Erub. IV, 2</span>, v. <a href=\"#\" data-headword=\"לְמֵין\">לְמֵין</a>. <span class=\"citation\">Tosef. Yoma II, 4</span> <span dir=\"rtl\">נְמֵלָהּ של יפו</span> (Var. <span dir=\"rtl\">נְמֵי׳</span>) the harbor of Japho; <span class=\"citation\">Yoma 38ᵃ</span> <span dir=\"rtl\">נ׳ של עכו</span>; a. e.</div>","alt":[]},"18970":{"h":"נְמָלָה","r":"N00882","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>ant</i>. <span class=\"citation\">Ḥull. 63ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">כי הוה חזי נ׳ וכ׳</span> when he saw ants (at work), he used to say, ‘thy righteousness &amp;c. (<span class=\"citation\">Ps. XXXVI, 7</span>). <span class=\"citation\">Deut. R. s. 5</span>; <span class=\"citation\">Yalk. Prov. 938</span> <span dir=\"rtl\">הנ׳ שלשה וכ׳</span> in the house of the ant there are three stories. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מעשה בנ׳ אחת וכ׳</span> once an ant dropped a grain of wheat &amp;c.; a. e.—Pl. <span dir=\"rtl\">נְמָלִים</span>, <span dir=\"rtl\">נְמָלִין</span>. <span class=\"citation\">Peah IV, 11</span>. <span class=\"citation\">Tosef. ib. I, 8</span>; <span class=\"citation\">Men. 71ᵇ</span>; a. fr.—<span class=\"citation\">Y. Yeb. VIII, 9ᵇ</span> <span dir=\"rtl\">מביא נימולין</span>, v. <a href=\"#\" data-headword=\"נָשַךְ\">נָשַׁךְ</a>.—[Chald. <a href=\"#\" data-headword=\"שׁוּמְשְׁמָנָא\">שׁוּמְשְׁמָנָא</a>.]</div>","alt":[]},"18971":{"h":"נַמְנוּמָא","r":"N00883","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נוּם\">נַמְנֵם</a>) <i>sleeping couch</i>. Y. Keth. II, 26ᵃ bot., v. <a href=\"#\" data-headword=\"הֵינוּמָא\">הֵינוּמָא</a>.—[<span dir=\"rtl\">נַמְנוּמֵי</span>, inf. of <a href=\"#\" data-headword=\"נוּם\">נַמְנֵם</a>.]</div>","alt":[]},"18972":{"h":"נִמְנֵם","r":"N00884","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נוּם II\"><span dir=\"rtl\">נוּם</span> II</a> h. a. ch.</div>","alt":["נַמְנֵם"]},"18973":{"h":"נָמֵס","r":"N00885","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>decayed</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">מי שהיח של עץ היה נ׳</span> that (idol) of wood appeared rotten; a. e.—V. <a href=\"#\" data-headword=\"מָסַס\">מָסַס</a>.</div>","alt":[]},"18974":{"h":"נמסיאות","r":"N00886","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Toh. VII, 11</span>, read: <a href=\"#\" data-headword=\"דִּימוֹסִיּוֹת\">דִּימוֹסְיָאוֹת</a> or <a href=\"#\" data-headword=\"אִסְטְוָונָא\">אִסְטְוָונִיוֹת</a> (v. <span class=\"citation\">Toh. VI, 10</span>).</div>","alt":[]},"18975":{"h":"נמסינן","r":"N00887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִימְפִּיּוֹן\">נִימְפְּיוֹן</a></div>","alt":[]},"18976":{"h":"נְמָקִים","r":"N00888","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"מָקַק\">מָקַק</a>) <i>decaying sores</i>. <span class=\"citation\">Sabb. 62ᵇ</span></div>","alt":[]},"18977":{"h":"נָמֵר","r":"N00889","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>tiger</i> or <i>leopard</i>. Y. Yeb. VIII, 9ᶜ top, v. <a href=\"#\" data-headword=\"חוּשׁ II\"><span dir=\"rtl\">חוּשׁ</span> II</a>. <span class=\"citation\">Snh. I, 4</span>; <span class=\"citation\">B. Kam. I, 4</span>, v. <a href=\"#\" data-headword=\"בַּרְדְּלִיס\">בַּרְדְּלִיס</a>; a. e.—Pl. <span dir=\"rtl\">נְמֵרִים</span>. <span class=\"citation\">Gen. R. s. 34</span>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span>; a. e.—[From <span class=\"citation\">Sabb. 107ᵇ</span>, ref. to <span class=\"citation\">Jer. XIII, 23</span>, it would appear that <span dir=\"rtl\">נמר</span>, in Talmudic days, meant <i>leopard</i>.]</div>","alt":[]},"18978":{"h":"נָמַר","r":"N00890","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">נִמֵּר</span> (denom. of <a href=\"#\" data-headword=\"נָמֵר\">preced.</a>) <i>to give a checkered</i> or <i>striped appearance</i>, esp. <span dir=\"rtl\">נ׳ שדה</span> <i>to take out</i> or <i>cut the ripe plants</i> of a field, leaving the unripe stand for later crops. <span class=\"citation\">Peah III, 2</span>. <span class=\"citation\">Men. 71ᵇ</span> <span dir=\"rtl\">במְנַמֵּר לקליות</span> when he cuts portions of the grain field with the intention of using the ears for roasting; <span dir=\"rtl\">במנמר לאוצר</span> when he cuts for storage.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מְנוּמָּר\">מְנוּמָּר</a> <i>striped, speckled</i>. <span class=\"citation\">B. Kam. 119ᵇ</span> <span dir=\"rtl\">לוקחין מהן בגד מנ׳</span> you may buy from them (weavers) (even) a checkered web (for which they may have used remnants of other people’s wool). <span class=\"citation\">Gitt. 54ᵇ</span> <span dir=\"rtl\">משום דמיחזי כמנ׳</span> because (if he were to pass his pen over all the Divine Names in the scroll) the writing would look speckled; <span class=\"citation\">Men. 29ᵇ</span> bot. <span dir=\"rtl\">משום דמיחזי כמ׳</span> it would look speckled (if he were to insert omitted vowel letters). <span class=\"citation\">Y. Succ. III, 53ᵈ</span> bot.; Y. Maasr. I, 49ᵃ <a href=\"#\" data-headword=\"הִימְנוֹן\">המ׳</a> a speckled Ethrog.</div>","alt":[]},"18979":{"h":"נְמַר","r":"N00891","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. V, 6</span>; a. e.—<span class=\"citation\">Y. Peah III, 17ᶜ</span> top (expl. <span dir=\"rtl\">המנמר</span> ib. III, 2) <span dir=\"rtl\">כהדין נימרה</span> making the field look checkered like a tiger (or leopard), v. <a href=\"#\" data-headword=\"נִמְרִירָה\">נִמְרִירָה</a>.—Pl. <a href=\"#\" data-headword=\"נִמְרֵי\">נִמְרִין</a>, <span dir=\"rtl\">נִמְרַיָּא</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Targ. Cant. IV, 8</span> (ed. Vien. <a href=\"#\" data-headword=\"נִמְרֵי\">נְמֵרִין</a>). Targ. <span class=\"citation\">Hab. I, 8</span>.—[<span dir=\"rtl\">בית נמרי</span>, <span dir=\"rtl\">בית נמרא</span>, <a href=\"#\" data-headword=\"נִמְרֵי\">נמרין</a>, v. next w.]</div>","alt":["נִמְרָא","(נִמְרָה","נִי׳"]},"18980":{"h":"נִמְרָה","r":"N00892","html":"<div class=\"sense\"> (b. h.) pr. n. pl. (<i>Beth</i>) <i>Nimrah</i>, modern <i>Nimrîn</i>, in Peraea. <span class=\"citation\">Tosef. Shebi. VII, 11</span>; Y. ib. IX, 38ᵈ bot.; ib. (expl. <span dir=\"rtl\">בית נמרה</span>, <span class=\"citation\">Josh. XIII, 27</span>) <span dir=\"rtl\">בֵּית נִמְרִין</span>.—<span class=\"citation\">Targ. O. Num. XXXII, 3</span> ed. Berl. (ed. Vien. <span dir=\"rtl\">כומרין דבית נִמְרִין</span>, read with Y. <span dir=\"rtl\">מכוור ובית נ׳</span>); Targ. O. ib. 36; Y. <span dir=\"rtl\">בית נִמְרִין</span>, <a href=\"#\" data-headword=\"נִמְרֵי\">נִמְרֵי</a>.—<span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">נמרין מלי</span> (Var. <span dir=\"rtl\">נמרים</span>); <span class=\"citation\">Yalk. Deut. 874</span> <span dir=\"rtl\">נימרין מיליה</span>; Sifré <span class=\"citation\">ib. 51</span> <span dir=\"rtl\">נימרון עליה</span> (corr. acc.); Y. Shebi. VI, 36ᶜ only <a href=\"#\" data-headword=\"נִמְרֵי\">נמרין</a>.—[Sifré l. c. <span dir=\"rtl\">טרכונא דנימרא</span>; Yalk. l. c. <span dir=\"rtl\">טרנינ׳ דזימרה</span>; Y. Shebi. l. c. <span dir=\"rtl\">טרכונא דמתחם לבוצרא</span>; Tosef. l. c. <span dir=\"rtl\">טרכונא דבתחום בצרה</span>.] V. Hildesh. Geogr. p. 60.</div>","alt":["בֵּית נ׳"]},"18981":{"h":"נמרידה","r":"N00893","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִמְרִירָה\">נִמְרִירָה</a></div>","alt":[]},"18982":{"h":"נִמְרֵי","r":"N00894","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Nimrin</i>, </div><div class=\"sense\"><b>1)</b>  = <span dir=\"rtl\">בית נמרה</span>, v. <a href=\"#\" data-headword=\"נמרידה\">preced. art.</a></div><div class=\"sense\"><b>—2)</b> <i>Nimrin</i> in Syria, the last station of messengers proclaiming the new moon. <span class=\"citation\">Y. Keth. II, 26ᵈ</span> top <span dir=\"rtl\">עד מקום ששלוחי … עד נ׳</span> as far as the messengers to announce the new moon go, as far as N. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> bot. <span dir=\"rtl\">אילין דאזלין לנְמוֹרִין</span> those messengers who go to N.—Tosef. Yoma V (IV), 3 <span dir=\"rtl\">ככותבת הנימרין</span>, v. <a href=\"#\" data-headword=\"נִמרִית\">נִמְרִית</a>.</div>","alt":["נִמְרִין","נִי׳"]},"18983":{"h":"נִמְרִירָה","r":"N00895","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (sub. <span dir=\"rtl\">שדה</span>; v. <a href=\"#\" data-headword=\"נָמַר\">נָמַר</a>) <i>a checkered field</i>. <span class=\"citation\">Y. Peah III, 17ᶜ</span> top (in a corrupt and defective passage) <span dir=\"rtl\">מקום … נ׳ קריי לה</span> (not <a href=\"#\" data-headword=\"נמרידה\">נמרידה</a>) the manured spots mature their plants earlier (and such a field) is called <i>nimrirah</i></div>","alt":[]},"18984":{"h":"נִמרִית","r":"N00896","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>of Nimrah</i> or <i>Beth Nimrah</i>. <span class=\"citation\">Y. Yoma VIII, 44ᵈ</span> bot. <span dir=\"rtl\">כותבת הנ׳</span>; Tosef. ib. V (IV), 3 <span dir=\"rtl\">הנימרין</span>; v. <a href=\"#\" data-headword=\"כּוֹתֶבֶת\">כּוֹתֶבֶת</a>.</div>","alt":[]},"18985":{"h":"נַן","r":"N00897","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"נָא I\"><span dir=\"rtl\">נָא</span> I</a>.</div>","alt":[]},"18986":{"h":"נָנָאי","r":"N00898","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָאנָאי\">נָאנָאי</a></div>","alt":[]},"18987":{"h":"נַנַּאי","r":"N00899","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (prob. abbrev. of <a href=\"#\" data-headword=\"חֲנַנְיָא\">חנניה</a>) <i>Nannai</i>, a name frequent in Maḥoza. <span class=\"citation\">Yeb. 115ᵇ</span> bot., v. <a href=\"#\" data-headword=\"חֲבַי\">חֲבַי</a>.</div>","alt":["נַנַּי"]},"18988":{"h":"נגני","r":"N00900","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בְּנִיגְנֵי\">בְּנִיגְנֵי</a></div>","alt":[]},"18989":{"h":"ננהא","r":"N00901","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 140ᵃ</span> Ar. ed. pr., v. <span dir=\"rtl\">נִינְיָא II</span></div>","alt":[]},"18990":{"h":"נִנְהוּ","r":"N00902","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"נִיהוּ\">נִיהוּ</a>.</div>","alt":[]},"18991":{"h":"נַנּוֹס","r":"N00903","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַנָּס\">נַנָּס</a>, <a href=\"#\" data-headword=\"נַנָּסָא\"><a href=\"#\" data-headword=\"נַנָּסָא\">נַנָּסָא</a>.</a></div>","alt":["נַנּוֹסָא"]},"18992":{"h":"נַנַּי","r":"N00904","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַנַּאי\">ננַּאי</a></div>","alt":[]},"18993":{"h":"נִנְיָא","r":"N00905","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נִינְיָא\">נִינְיָא</a></div>","alt":["נִנְיָיא"]},"18994":{"h":"נַנִּיס","r":"N00906","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נַנָּסָא\">נַנָּסָא</a></div>","alt":[]},"18995":{"h":"נַנָּס","r":"N00907","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (νᾶνος, nanus, of Semitic origin, fr. <a href=\"#\" data-headword=\"נְסַס\">נסס</a>, cmp. <span dir=\"rtl\">ממל</span> fr. <span dir=\"rtl\">מלל</span>) <i>dwarf</i>; (adj.) <i>puny, stumped</i>. <span class=\"citation\">Nidd. 24ᵇ</span>, opp. <a href=\"#\" data-headword=\"אָרוּךְ\">אָרוּךְ</a>; <span class=\"citation\">Num. R. s. 9</span>. <span class=\"citation\">Ber. 58ᵇ</span> <a href=\"#\" data-headword=\"נ׳\">נ׳</a> one whose limbs are too small for his body, opp. <a href=\"#\" data-headword=\"כִּיפֵּחַ\">כִּיפֵּחַ</a>; Tosef. ib. VII (VI), 3 <a href=\"#\" data-headword=\"נַנּוֹס\">ננוס</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"נַנָּס\">ננס</a>); Y. ib. IX, 13ᵇ bot.; Tanḥ. ed. Bub., Pinḥas 1. Sifra Emor, Par. 3, ch. III; <span class=\"citation\">Bekh. VII, 6</span> (<span class=\"citation\">45ᵇ</span>, of animals and of men). <span class=\"citation\">Cant. R. to II, 15</span>; <span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">נ׳ שבננסים</span> a puny dwarf. <span class=\"citation\">Midr. Till. to Ps. CXXXVII</span>; <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">הנ׳ הזה</span> that dwarf (Nebuchadnezzar); a. fr.—<span class=\"citation\">Ḥull. 63ᵃ</span> <span dir=\"rtl\">וסימנך ננוס פסול</span> and thy sign (to remember that the small species of <a href=\"#\" data-headword=\"שְׁקִיטְנָא\">שקיטנא</a> is unclean) be, ‘the dwarf is unfit’ (for priesthood).—Pl. <span dir=\"rtl\">נַנָּסִים</span>, <span dir=\"rtl\">נַנָּסִין</span>. Cant. R. l. c.; Gen. R. l. c., v. supra. <span class=\"citation\">Pesik. R. s. 37</span>; <span class=\"citation\">Yalk. ib. 62</span> כפתורים נ׳ Caphtorites (<span class=\"citation\">Gen. X, 14</span>) are dwarfs; a. fr.—<span class=\"citation\">Tam. III, 5</span>; <span class=\"citation\">Midd. III, 5</span> <span dir=\"rtl\">עמודים</span> .<a href=\"#\" data-headword=\"נ׳\">נ׳</a> small columns. <span class=\"citation\">Ib. V, 2</span> <span dir=\"rtl\">הנ׳</span> (sub. <span dir=\"rtl\">עמודים</span>).—<i>Fem</i>. <span dir=\"rtl\">נַנֶּסֶת</span>. <span class=\"citation\">Bekh. 45ᵇ</span>. <span class=\"citation\">Par. II, 2</span>; a. e.</div>","alt":[]},"18996":{"h":"נַנָּסָא","r":"N00908","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Lev. XXI, 20</span> <span dir=\"rtl\">נניס</span> (h. text <a href=\"#\" data-headword=\"דַּק I\">דק</a>).—Pesik. Dibré, p. 112ᵃ sq. <span dir=\"rtl\">נ׳ דבבל</span> (Ms. Parma <a href=\"#\" data-headword=\"נַנּוֹס\">ננוסא</a>) the Babylonian dwarf (Nebuchadnezzar); Yalk. Dan. 1062 (ref. to <span class=\"citation\">Dan. IV, 14</span> <span dir=\"rtl\">שפל אנשים</span>) <span dir=\"rtl\">זה נבוכדנצר נ׳ וכ׳</span> that means N. the dwarf &amp;c. (v. ‘Rashi’ to <span class=\"citation\">Gen. R. s. 16</span>, end).</div>","alt":["נַנִּיס"]},"18997":{"h":"נַנְעָא","r":"N00909","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>mint</i>. <span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> <span dir=\"rtl\">והא נ׳ וכ׳</span> (not <span dir=\"rtl\">והיא</span>) but there is mint (which has a quadrangular stem, whereas you say, there is nothing quadrangular in nature)? (Answ.) It is full of knots; <span class=\"citation\">Y. Ned. III, 37ᵈ</span> bot. <span dir=\"rtl\">והוא כנעה</span> (corr. acc.); <span class=\"citation\">Y. Shebu. III, 34ᵈ</span> bot. <span dir=\"rtl\">והנגעה</span> (corr. acc.).</div>","alt":["נַנְעָה"]},"18998":{"h":"ננקפ\"י","r":"N00910","html":"<div class=\"sense\">, a fictitious word made up of every second letter in <span dir=\"rtl\">מנ̇א מנ̇א תק̇ל ופ̇רסי̇ן</span>, v. <a href=\"#\" data-headword=\"אאלר\">אאלר&quot;ן</a></div>","alt":[]},"18999":{"h":"נֵס I","r":"N00911","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> נסס <i>to lift up</i>, </div><div class=\"sense\"><b>1)</b> <i>flag</i>. <span class=\"citation\">B. Bath. V, 1</span>, v. <a href=\"#\" data-headword=\"אֲדָרָא II\"><span dir=\"rtl\">אֲדָרָא</span> II</a>. <span class=\"citation\">Gen. R. s. 55</span>, beg. (ref. to <span class=\"citation\">Ps. LX, 6</span>) <span dir=\"rtl\">כנס הזה וכ׳</span> like the flag of a ship; ib. (ref. to <span dir=\"rtl\">נסה</span>, <span class=\"citation\">Gen. XXII, 1</span>) <span dir=\"rtl\">גדלו כנס וכ׳</span> he lifted Abraham up like &amp;c.; <span class=\"citation\">Yalk. Ps. 777</span> <span dir=\"rtl\">כנסו של וכ׳</span> (read: <span dir=\"rtl\">כנס זה</span>); a. e.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"אוֹת I\">אוֹת</a>, <a href=\"#\" data-headword=\"מוֹפֵת\">מוֹפֵת</a>) <i>sign, wonder, providential event</i>. <span class=\"citation\">Nidd. 31ᵃ</span> <span dir=\"rtl\">אפי׳ בעל הנס אינו מכיר בנִסּוֹ</span> even he to whom the providential sign happens, does not recognize it. <span class=\"citation\">Yoma 21ᵃ</span> <span dir=\"rtl\">כרובים בנס וכ׳</span> the cherubs (above the ark in the Solomonic Temple) stood by a miracle. Ib., a. e. <span dir=\"rtl\">נס גדול היה וכ׳</span> a great miracle was connected with the show-bread which was as fresh at its removal &amp;c. <span class=\"citation\">Sot. 47ᵃ</span>, a. fr. <span dir=\"rtl\">נס בתוך נס</span> a double wonder. <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">גדול נס שנעשה וכ׳</span> the wonder of recovery which the sick man experiences, is greater than that which happened to Hananiah, Mishael &amp;c. <span class=\"citation\">Sabb. 23ᵃ</span>, a. e. <span dir=\"rtl\">אף הן היו באותו הנס</span> the women, too, were concerned in that wonderful delivery. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ונימעוט נס</span> why not omit the benediction mentioning the wonder (<span dir=\"rtl\">שעשה נסים וכ׳</span>)?; a. v. fr.—Pl. <span dir=\"rtl\">נִסִּים</span>, <span dir=\"rtl\">נִסִּין</span>, <a href=\"#\" data-headword=\"מני\">נִי׳</a>. <span class=\"citation\">Ber. IX, 1</span> <span dir=\"rtl\">הרואה מקום שנעשו בו נ׳ … ברוך שעשה נ׳ וכ׳</span> he who sees a place where miracles happened to Israel, must say, Blessed be he who performed wonders &amp;c. <span class=\"citation\">Ib. 60ᵃ</span>, a. fr. <span dir=\"rtl\">מעשה נ׳</span> (abbrev. <span dir=\"rtl\">מ&quot;נ</span>) a miraculous event, v. <a href=\"#\" data-headword=\"זָכַר\">זָכַר</a>. <span class=\"citation\">Yoma 29ᵃ</span> <span dir=\"rtl\">אסתר סוף כל הנ׳</span> the Book of Esther is the last record of miracles. <span class=\"citation\">Taan. 25ᵃ</span>; <span class=\"citation\">Snh. 109ᵃ</span> top, v. <a href=\"#\" data-headword=\"לָמֵד I\">לָמַד</a>; a. v. fr.</div>","alt":[]},"19000":{"h":"סטרמוסין","r":"O00512","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִטְרוֹמָטִין\">סִטְרוֹמָטִין</a></div>","alt":[]},"19001":{"h":"סטרנורא","r":"O00513","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְטַרְנַלְיָיא\">next w.</a></div>","alt":[]},"19002":{"h":"סְטַרְנַלְיָיא","r":"O00514","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Saturnalia) <i>the Saturnalia</i>, a Roman festival beginning on the 17<sup>ᵗʰ</sup> of December and lasting several days. <span class=\"citation\">Ab. Zar. I, 3</span> Y. ed. (Mish. a. Bab. ed. 8ᵃ variously corrupted or perverted). Y. ib. 39ᶜ (cacophemistic etymology) <span dir=\"rtl\">שׁנאה טֹמונה שׁונא נוקם ונ̇וט̇ר̇</span> hatred hidden (under the merriment of social equality and good will), he (the Roman) hates &amp;c. Ib. <span dir=\"rtl\">ס׳ דביישן</span> the Saturnalian fair of Scythopolis (v. <a href=\"#\" data-headword=\"בֵּישָׁן\">בֵּישָׁן</a>). Ib. top <span dir=\"rtl\">ס׳ אינה אסורה וכ׳</span> during the Saturnalia trading is forbidden only with those who worship thereon (celebrate it). Bab. ib. 8ᵃ <span dir=\"rtl\">ס׳ שמונה ימים לפני וכ׳</span> the Saturnalia begin eight days before the solstice; Y. l. c. <span dir=\"rtl\">ס׳ לאחר וכ׳</span> (corr. acc.). <span class=\"citation\">Deut. R. s. 7</span> <a href=\"#\" data-headword=\"סטרגלים\">סטרגלים</a>, <span dir=\"rtl\">סטרנלים</span> (corr. acc.).</div>","alt":["סְטַרְנַלְיָיה"]},"19003":{"h":"סִי","r":"O00515","html":"<div class=\"sense\"> (σέ) <i>thee</i>. <span class=\"citation\">Pesik. R. s. 40</span> <span dir=\"rtl\">סי לעוֹלה</span> (not <a href=\"#\" data-headword=\"חַי\">חי</a>), v. <a href=\"#\" data-headword=\"שֶׂה\">שֶׂה</a>.</div>","alt":[]},"19004":{"h":"סִיאָה","r":"O00516","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Siah</i>, a plant classified with hyssop, <i>Satureia Thymbra</i> (<i>savory</i>). <span class=\"citation\">Maasr. III, 9</span>. <span class=\"citation\">Shebi. VIII, 1</span>. <span class=\"citation\">Tosef. Kil. III, 12</span>. <span class=\"citation\">Sabb. 128ᵃ</span>, expl. <a href=\"#\" data-headword=\"צִתְרֵי\">צתרי</a>; a. fr.—V. Löw Pfl., p. 135.</div>","alt":[]},"19005":{"h":"סִיאָה ²","r":"O00517","html":"<div class=\"sense\">, <span class=\"citation\">Arakh. 18ᵃ</span>, v. <a href=\"#\" data-headword=\"סִיעָה\">סִיעָה</a></div>","alt":[]},"19006":{"h":"סִיאוּר","r":"O00518","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">סאר</span> = <a href=\"#\" data-headword=\"שְׁאַר I\">שאר</a>) <i>fermentation, leaven.</i> <span class=\"citation\">Ḥall. II, 6</span> וסִיאוּרָן Ar. (ed. <span dir=\"rtl\">ושאורן</span>) the leaven required for them.—Trnsf. <i>original immoral condition; evil nature</i>. <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> top <span dir=\"rtl\">חזר לסִיאוּרוֹ</span> he returned to his old condition (heathenism). <span class=\"citation\">Koh. R. to VII, 8</span> <span dir=\"rtl\">אילולי כן חזר הפרסי לסיאורו</span> because but for it (Samuel’s forbearance) that Persian would have gone back to heathenism; a. e.—V. <a href=\"#\" data-headword=\"סוֹר\">סוֹר</a>.</div>","alt":[]},"19007":{"h":"סִיאוּרָא","r":"O00519","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ps. LXXXV, 9</span> (ed. Lag. <a href=\"#\" data-headword=\"סִאוּר\">סִאוּרָא</a>; oth. ed. <span dir=\"rtl\">סכלא</span>; h. text <span dir=\"rtl\">כסלה</span>).</div>","alt":[]},"19008":{"h":"סַיָּאנָא","r":"O00520","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּינָא\">סיָּינָא</a></div>","alt":[]},"19009":{"h":"סִיאַנְקֵי","r":"O00521","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>of Siân</i>, a Persian town. <span class=\"citation\">Keth. 67ᵇ</span> <span dir=\"rtl\">דינרי ס׳</span> (Ar. <span dir=\"rtl\">סְיָינְקֵי</span>, <a href=\"#\" data-headword=\"זְיָינְקֵי\">זְיָינְקֵי</a> Sian (gold) Denars (v. Zuckerm. Talm. Münz., p. 33 note).</div>","alt":[]},"19010":{"h":"סֵיאָר","r":"O00522","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ukts. I, 8</span>, v. <a href=\"#\" data-headword=\"שֵׂעָר\">שֵׂעָר</a></div>","alt":[]},"19011":{"h":"סִיב I","r":"O00523","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְאֵב II\"><span dir=\"rtl\">סְאֵב</span> II</a>) <i>gray, old; elder, scholar</i>. <span class=\"citation\">Targ. Gen. XXV, 8</span>; a. fr.—<span class=\"citation\">Y. Sabb. VI, 8ᵃ</span> bot. <span dir=\"rtl\">פוק חמי חד ס׳ וכ׳</span> go and look out for a scholar (observe his practice) and rely on him; <span class=\"citation\">Y. Yeb. XII, 12ᵈ</span> top <span dir=\"rtl\">סב</span>; a. fr.—Pl. <span dir=\"rtl\">סִיבֵי</span>. <span class=\"citation\">Targ. Prov. XX, 29</span> (some ed. <a href=\"#\" data-headword=\"סְבָא\">סָבֵי</a>).</div>","alt":[]},"19012":{"h":"סִיב II","r":"O00524","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"סִיב I\">preced.</a>) <i>to be old</i>. <span class=\"citation\">Targ. I Sam. II, 22</span>. <span class=\"citation\">Ib. XII, 2</span> <span dir=\"rtl\">סָבִית</span>; ed. Lag. <span dir=\"rtl\">סֵיבִית</span>; a. fr.—<span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top; <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">זכה למֵיסַב וכ׳</span> he was permitted to reach so high an age that &amp;c.; a. fr.</div><div class=\"sense\"><b>Ithpe. אִיתְּסִיב</b> <div class=\"sense\"><i>to become old</i>. <span class=\"citation\">Targ. Job XIV, 8</span> מִיתְּסִיב Ms. (ed. <span dir=\"rtl\">מִתְּסַב</span>).</div></div>","alt":["סִיב"]},"19013":{"h":"סִיב III","r":"O00525","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְאֵב I\">סְאֵב</a>) <i>fibrous substance</i>, esp. <i>bast</i> of the palm-tree. <span class=\"citation\">Ukts. I, 2</span> <span dir=\"rtl\">הס׳ שלו</span> the fibrous root of the radish. <span class=\"citation\">Pes. 115ᵇ</span> <span dir=\"rtl\">כרכן בס׳</span> if he wrapped them up in bast. <span class=\"citation\">Y. Succ. I, 52ᵇ</span> bot. <span dir=\"rtl\">חבלים של ס׳</span> ropes of bast; a. fr.—Pl. <span dir=\"rtl\">סִיבִים</span>, <span dir=\"rtl\">סִיבִין</span>. <span class=\"citation\">Gen. R. s. 41</span>, beg.; <span class=\"citation\">Num. R. s. 3</span>, beg. <span dir=\"rtl\">ס׳ לחבלים</span> the bast of the palm-tree is used for making ropes; a. e.—[<span class=\"citation\">Yalk. Ps. 841</span> <span dir=\"rtl\">סיב קמלפי</span>, v. <a href=\"#\" data-headword=\"סִיבַק\">סִיבַק</a>.]</div>","alt":[]},"19014":{"h":"סֵיבָא I","r":"O00526","html":"<div class=\"sense\"> <span class=\"citation\">Lev. R. s. 22</span>, beg. <span dir=\"rtl\">ס׳ למעבד חבלא</span> (not <span dir=\"rtl\">סיכא</span>), v. <a href=\"#\" data-headword=\"סִיב III\">preced.</a>; <span class=\"citation\">Koh. R. to V, 8</span> (ed. Wil. <a href=\"#\" data-headword=\"שֵׂיבָא\">שֵׂיבָא</a>); <span class=\"citation\">Yalk. ib. 971</span> <span dir=\"rtl\">סיכא</span> (corr. acc.).</div>","alt":[]},"19015":{"h":"סֵיבָא II","r":"O00527","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סִיב I) <i>old age</i>. <span class=\"citation\">Targ. I Kings XIV, 4</span>.</div>","alt":[]},"19016":{"h":"סִיבְבָא","r":"O00528","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִבְבָא\">סִבְבָא</a></div>","alt":[]},"19017":{"h":"סִיבָּה","r":"O00529","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָבַב\">סָבַב</a>) <i>transfer of property from tribe to tribe</i> (interch. with <a href=\"#\" data-headword=\"הֶסֵּבָּה\">הֶסֵּבָּה</a>). <span class=\"citation\">B. Bath. 111ᵇ</span>, a. fr. <span dir=\"rtl\">סִיבַּת הבעל</span>, v. <a href=\"#\" data-headword=\"הֶסֵּבָּה II\"><span dir=\"rtl\">הֶסֵבָּה</span> II</a>. <span class=\"citation\">Ib. 159ᵇ</span> <span dir=\"rtl\">נאמרה ס׳ בבן נאמרה ס׳ בבעל</span> (Ms. M. <span dir=\"rtl\">הסיבה</span>) the transfer is spoken of (as forbidden) concerning the son succeeding his mother and the husband succeeding his wife; a. fr.—[Bibl. Hebr. <a href=\"#\" data-headword=\"סִבָּה\">סִבָּה</a>: <i>arrangement, divine dispensation</i>; in later Hebr.: <i>turn, misfortune</i>; in philos. literature: <i>cause</i>.]</div>","alt":["סִבָּה"]},"19018":{"h":"סֵיבוּ","r":"O00530","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (סִיב I) <i>gray head, old age</i>. Targ. II Esth. VII, 9. <span class=\"citation\">Targ. Gen. XV, 15</span> (some ed. <a href=\"#\" data-headword=\"שֵׂיבוּ\">שֵׂיבוּ</a>); a. fr.—<span class=\"citation\">Targ. Y. II, Deut. XXXIII, 25</span> <span dir=\"rtl\">סָבוּ׳</span>.—<span class=\"citation\">Cant. R. to VIII, 7</span> <span dir=\"rtl\">דלא שבקת לסֵיבוּתָיךְ כלום</span> that thou didst leave nothing for thyself in thy old age; <span class=\"citation\">Lev. R. s. 30</span>; a. e.—<span class=\"citation\">Yeb. 65ᵇ</span> <span dir=\"rtl\">מַסֵּיבוּ דילה</span> (not … <span dir=\"rtl\">בי</span>) = <span dir=\"rtl\">מה ס׳</span> what about her (my) old age?—Trnsf. <i>old men, elders</i>. <span class=\"citation\">Tosef. Ḥull. II, 24</span> (in Hebr. dict.) <span dir=\"rtl\">אפשר שהס׳ הללו טועים וכ׳</span> is it possible that these elders &amp;c., v. <a href=\"#\" data-headword=\"יְשִׁיבָה\">יְשִׁיבָה</a>.</div>","alt":["סֵיבוּתָא","סֵב׳"]},"19019":{"h":"סיבוא","r":"O00531","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 22</span>, beg., v. <a href=\"#\" data-headword=\"סִיגָא\">סִיגָא</a>.</div>","alt":[]},"19020":{"h":"סיבויי","r":"O00532","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to IV, 12</span>, v. <a href=\"#\" data-headword=\"סִיכּוּי\">סִיכּוּי</a></div>","alt":[]},"19021":{"h":"סיבוך","r":"O00533","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיכּוּךְ\">סִיכּוּךְ</a></div>","alt":[]},"19022":{"h":"סִיבּוּל","r":"O00534","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיבּוֹלֶת\">next w.</a></div>","alt":["סִיבּוֹלִית"]},"19023":{"h":"סִיבּוֹלֶת","r":"O00535","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָבַל\">סָבַל</a>; cmp. <span dir=\"rtl\">סִבְלוֹנוֹת</span>) <i>sending provisions for a common meal, picnic</i>. <span class=\"citation\">Pes. 89ᵇ</span> <span dir=\"rtl\">אפי׳ חמשה ועשו ס׳</span> (Ms. O. repeatedly <span dir=\"rtl\">סבלונות</span>, v. Rabb. D. S. a. l. note 7) even (in ordinary cases) when five persons sent articles of food for a picnic; <span class=\"citation\">Tosef. ib. VII, 10</span> (Var. <a href=\"#\" data-headword=\"סִבּוּל\">סבול</a>, <span dir=\"rtl\">סיבלות</span>); Y. ib. VIII, 36ᵃ <a href=\"#\" data-headword=\"סִינְבּוּל\">סִינְבּוּל</a> (with anorg. <a href=\"#\" data-headword=\"נ\">נ</a>). <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> אני אומר סיבולית וכ׳ I say (the inscriptions ‘in behalf of—’ intimate) that they have arranged a picnic among themselves (and each marked his contribution).</div>","alt":["סִבּ׳"]},"19024":{"h":"סִיבּוּר","r":"O00536","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְבַר I) <i>hope</i>. <span class=\"citation\">Targ. I Chr. XXIX, 15</span>. <span class=\"citation\">Targ. Prov. XI, 23</span>. <span class=\"citation\">Ib. 7</span>; a. fr.</div>","alt":["סִיבּוּרָא","סִבּ׳ I"]},"19025":{"h":"סִיבּוּרָא","r":"O00537","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְבר III) <i>blood-letting</i>. <span class=\"citation\">Ab. Zar. 29ᵃ</span> (interch. with <a href=\"#\" data-headword=\"סִיכּוּרֵי\">סִיבּוּרֵי</a>, <a href=\"#\" data-headword=\"סִיבּוֹלֶת\">סִבּ׳</a> <i>pl.</i>).—<span class=\"citation\">Keth. 39ᵇ</span> תרפתא דסיבורי Ar. ed. Koh. (oth. ed. <span dir=\"rtl\">דסיכורי</span>, a Var. to <span dir=\"rtl\">רבדא דכוסילתא</span>, v. Rashi a. l.) the scar from blood-letting.</div>","alt":["סִבּ׳ II"]},"19026":{"h":"סֵיבוּת","r":"O00538","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, <i>grey color, grey hair</i>. <span class=\"citation\">Tosef. Neg. I, 4</span> <span dir=\"rtl\">מראה ס׳</span> grey color.—<span class=\"citation\">Y. Ber. IV, 7ᵈ</span> top <span dir=\"rtl\">נתמלא … שֵׂיבוּת</span> his entire head became grey.</div>","alt":[]},"19027":{"h":"סֵיבוּתָא","r":"O00539","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סֵיבוּ\">סֵיבוּ</a></div>","alt":[]},"19028":{"h":"סיבטא","r":"O00540","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 112ᵃ</span>, v. <a href=\"#\" data-headword=\"סִכְּתָא\">סִכְּתָא</a></div>","alt":[]},"19029":{"h":"סִיבְכָא","r":"O00541","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִבְכָא\">סִבְכָא</a></div>","alt":[]},"19030":{"h":"סִיבְכַי","r":"O00542","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> <span dir=\"rtl\">ימא דס׳</span>, <span dir=\"rtl\">ימה של ס׳</span> <i>the Lake of Sibkhay</i> (<i>Merom, Samachonitis</i>). <span class=\"citation\">B. Bath. 74ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"סִבְכַיי\">סִיבְכַיי</a>); <span class=\"citation\">Midr. Till. to Ps. XXIV</span>; <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> bot. <span dir=\"rtl\">דסַמְכוּ</span>; <span class=\"citation\">Y. Keth. XII, 35ᵇ</span> bot. <span dir=\"rtl\">דכובבו</span> (corr. acc.). <span class=\"citation\">Y. B. Bath. V, 15ᵃ</span> (ref. to <span class=\"citation\">Deut. XXXIII, 23</span>) <span dir=\"rtl\">זה ימה של סמכו</span> this means the Lake of S.—Targ. Y. I Deut. l. c. <span dir=\"rtl\">ימא דסוֹפְנֵי</span>; <span class=\"citation\">Tosef. B. Kam. VIII, 18</span> <span dir=\"rtl\">ימה של סופני</span>.</div>","alt":[]},"19031":{"h":"סִיבְנִּי","r":"O00543","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִבְנִי\">סִבְנִי</a></div>","alt":[]},"19032":{"h":"סִיבְעָא","r":"O00544","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִבְעָא\">סִבְעָא</a></div>","alt":[]},"19033":{"h":"סִיבַק","r":"O00545","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (sebaceus) <i>tallow-candle</i>. <span class=\"citation\">Midr. Till. to Ps. XC</span> [read:] <span dir=\"rtl\">מה בוצין טב קומוי מה ס׳ טב קומוי וכ׳</span> (ed. <a href=\"#\" data-headword=\"סומבק\">סומבק</a>, <span dir=\"rtl\">סימבק</span>) of what good is a lamp before Him, of what good is a tallow-candle before Him?—Moses, a being of flesh and blood, dares to come before the Lord, who is all fire &amp;c.; <span class=\"citation\">Yalk. Ps. 841</span> <span dir=\"rtl\">סיב קמלפי</span> (corr. acc.).—Pl. <a href=\"#\" data-headword=\"סִבְקִין\">סִיבְקִין</a>, <a href=\"#\" data-headword=\"סִיבּוּר\">סִבְ׳</a>. <span class=\"citation\">Ex. R. s. 36</span> <span dir=\"rtl\">קריונין וס׳</span> wax and tallow-candles.</div>","alt":[]},"19034":{"h":"סִיבְרָא","r":"O00546","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְבַר IV\">סִבְרָא</a></div>","alt":["סִיבְרָה"]},"19035":{"h":"סִיבַּרְתָּא","r":"O00547","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַבָּרוּתָא\">סַבָּרוּתָא</a></div>","alt":[]},"19036":{"h":"סֵיבְתָא","r":"O00548","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  = <a href=\"#\" data-headword=\"סֵיבוּתָא\">סֵיבוּתָא</a>. <span class=\"citation\">Targ. Gen. XLII, 38</span> (O. some ed. <a href=\"#\" data-headword=\"שָׂטָן ²\">שִׂי׳</a>). <span class=\"citation\">Targ. Job XV, 32</span> (ed. Wil. <span dir=\"rtl\">סִבְתּ׳</span>); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>eldership, receiving the title of</i> <a href=\"#\" data-headword=\"סָב\">סָבָא</a>. <span class=\"citation\">Y. Bicc. III, 65ᵈ</span> <span dir=\"rtl\">וכתב ליה מן סֵיבְתֵיה בגוה</span> (not <span dir=\"rtl\">ויהב</span>) and he informed him therein of his (expected) appointment as elder.—Pl. <a href=\"#\" data-headword=\"סֵיבְתָא\">סֵיבָתָא</a>, <a href=\"#\" data-headword=\"סִיבּוּר\">סֵבָ׳</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בגין אילין ס׳ קום וכ׳</span></div>","alt":["סֵבְתָא"]},"19037":{"h":"סִיג I","r":"O00549","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>that which is to be removed;</i> cmp. <a href=\"#\" data-headword=\"בְּדִיל\">בְּדִיל</a>,] <i>dross, base metal; refuse</i>. <span class=\"citation\">Bekh. 51ᵃ</span> שלא יביא ס׳ לעזרה Ar. (ed. <span dir=\"rtl\">סִיגָה</span>) in order that one may not bring base metal to the Temple (therefore stamped silver coins had to be brought along; Rashi: <span dir=\"rtl\">סיגה וכסף סיגים</span> base metal or non-purified silver).—Pl. <a href=\"#\" data-headword=\"סיגים\">סִיגִים</a>, <span dir=\"rtl\">סִגִּים</span>. <span class=\"citation\">Num. R. s. 14</span> (ref. to <span dir=\"rtl\">סוג לב</span>, <span class=\"citation\">Prov. XIV, 14</span>) <span dir=\"rtl\">אותו הלב שהוא מלא ס׳ וכ׳</span> the heart full of base things, will get sick of its own ways. Ib. s. 13 יחזקאל קורא אותם ס׳ Ezekiel calls them base metal (ref. to <span class=\"citation\">Ez. XXII, 18</span>). <span class=\"citation\">Midr. Till. to Ps. CXIX, 119</span>) <span dir=\"rtl\">אכל הענבים נעשה ס׳</span> ed. Bub. (ed. <span dir=\"rtl\">עושה סוגים</span>, corr. acc.) after he has eaten the grapes, it (the cluster) becomes refuse.</div>","alt":[]},"19038":{"h":"סִיג II","r":"O00550","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְגֵי ²\"><span dir=\"rtl\">סְגֵי</span> I</a>; cmp. <a href=\"#\" data-headword=\"סוּגְיָינָא\">סוּגְיָינָא</a>; for the apocopate form cmp. <a href=\"#\" data-headword=\"רֵעַ\">רֵעַ</a> a. <a href=\"#\" data-headword=\"רעי\">רֵעֶה</a>) <i>growth, sproutings</i>, esp. <i>luxuriant growth</i> (in good or bad sense). <span class=\"citation\">Tosef. Ukts. I, 2</span> (<span class=\"citation\">T’bul Yom III</span>) <span dir=\"rtl\">הס׳ של אשכלות</span> the foliage covering the clusters of grapes, <span dir=\"rtl\">של רצפות</span> the cobweb-like covering of fruits; <span class=\"citation\">Ukts. I, 2</span>.—Pl. <a href=\"#\" data-headword=\"סיגים\">סִיגִּים</a>, <span dir=\"rtl\">סִגִּים</span>. <span class=\"citation\">Deut. R. s. 3</span> (ref. to <span class=\"citation\">Deut. VII, 13</span>) <span dir=\"rtl\">מה פרי אדמתך ס׳ וכ׳</span> as the fruit of thy ground will be of luxuriant growth, so will be the fruit of thy womb (strong people). <span class=\"citation\">Num. R. s. 16</span>; Tanḥ. Sh’laḥ 12 (ref. to Is.XVII, 11) <span dir=\"rtl\"><span dir=\"rtl\">ביום שאמר …</span> (<a href=\"#\" data-headword=\"נ\">נ</a>) <span dir=\"rtl\">עשיתם ס׳</span></span> on the day that he intended to plant you in the land, you became a luxuriant growth (degenerated); <span class=\"citation\">Num. R. s. 7</span>.—[Sifra Sh’mini, ch. VII, Par. 6, v. <a href=\"#\" data-headword=\"סוּג II\"><span dir=\"rtl\">סוּג</span> II</a> .].</div>","alt":[]},"19039":{"h":"סְיָג","r":"O00551","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְיָיג\">סְיָיג</a>, <a href=\"#\" data-headword=\"סְיָיג ²\"><a href=\"#\" data-headword=\"סְיָיג ²\">סְיָיגָא</a>.</a></div>","alt":["סְיָגָא"]},"19040":{"h":"סִיגָא","r":"O00552","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סִיג II\"><span dir=\"rtl\">סִיג</span> II</a>, cmp. <a href=\"#\" data-headword=\"סוּגְיָינָא\">סוּגְיָינָא</a>) <i>twig</i>.—Pl. <span dir=\"rtl\">סִיגַיָּא</span>. <span class=\"citation\">Koh. R. to V, 8</span> [read:] <span dir=\"rtl\">ס׳ למיסך גיניא</span> the twigs (of the palm tree) are useful for garden hedges; <span class=\"citation\">Lev. R. s. 22</span>, beg. <span dir=\"rtl\">סיבוא וכ׳</span> (corr. acc.; Ar. <span dir=\"rtl\">סיגא למיסג גינין</span>); <span class=\"citation\">Yalk. Koh. 971</span> <span dir=\"rtl\">סיכא למסמך ביה גופנין</span> (corr. acc.).—[<span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> <span dir=\"rtl\">סיגייה</span>, v. <a href=\"#\" data-headword=\"סוּגֵי\">סוּגֵי</a>.]</div>","alt":[]},"19041":{"h":"סִיגְדָּא","r":"O00553","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִגְדָּא\">סִגְדָּא</a></div>","alt":["סִיגְדְּתָא"]},"19042":{"h":"סֵיגוּ","r":"O00554","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (constr. of <span dir=\"rtl\">סֵיגְוָא</span>; <a href=\"#\" data-headword=\"סְגֵי ²\"><span dir=\"rtl\">סְגֵי</span> I</a>) <i>plenty of, much; very</i>. <span class=\"citation\">Targ. Prov. XIII, 3</span>. <span class=\"citation\">Ib. XV, 23</span> (ed. Wil. <a href=\"#\" data-headword=\"סֵגוּ\">סְגוּ</a>).—Pl. <span dir=\"rtl\">סֵיגוּיֵי</span>. <span class=\"citation\">Targ. Is. V, 13</span> <span dir=\"rtl\">סֵיגוּיֵהוֹן</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">סִגְוְהוֹן</span>, sing.) their multitudes (h. text <span dir=\"rtl\">הֲמֹנוֹ</span>).</div>","alt":["סֵגוּ"]},"19043":{"h":"סֵיגוּיָא","r":"O00555","html":"<div class=\"sense\">, pl. constr. <span dir=\"rtl\">סֵיגוּיי</span>, v. <a href=\"#\" data-headword=\"סֵיגוּ\">preced.</a></div>","alt":[]},"19044":{"h":"סיגום","r":"O00556","html":"<div class=\"sense\">, Sifra M’tsora, Zab., Par. 1, ch. II, read: <a href=\"#\" data-headword=\"סָגוּם\">סָגוּם</a>.</div>","alt":["סיגוס"]},"19045":{"h":"סִיגוּף","r":"O00557","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָגַף\">סָגַף</a>) <i>affliction, privation, ascetic practices</i>. <span class=\"citation\">Koh. R. to III, 18</span> <span dir=\"rtl\">על מדברות שהצדיקים מִדַּבְּרִים בעוה&quot;ו בס׳ וכ׳</span> concerning the conduct with which the righteous conduct themselves in this world in privation, fasts and sufferings.</div>","alt":["סִגּ׳"]},"19046":{"h":"סִיגּוּף","r":"O00558","html":"<div class=\"sense\">, <i>affliction, misery</i>. <span class=\"citation\">Targ. Is. VIII, 21</span>. <span class=\"citation\">Ib. XLI, 17</span>; a. fr.—Pl. <span dir=\"rtl\">סִיגּוּפִין</span>, <a href=\"#\" data-headword=\"סִיגוּף\">סִגּ׳</a>. <span class=\"citation\">Targ. Y. Gen. XLI, 52</span>.</div>","alt":["סִיגּוּפָא","סִגּ׳"]},"19047":{"h":"סיגורין","r":"O00559","html":"<div class=\"sense\">, <span class=\"citation\">Y. Meg. II, 73ᵃ</span> bot., read: <span dir=\"rtl\">סֵירוּגִין</span>.</div>","alt":[]},"19048":{"h":"סיגים","r":"O00560","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 52</span> some ed., v. <a href=\"#\" data-headword=\"סִינִים\">סִינִים</a></div>","alt":[]},"19049":{"h":"סִיגְלָא","r":"O00561","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְגַל\">סְגַל</a>, cmp. <a href=\"#\" data-headword=\"סְגוֹל\">סְגוֹל</a>) [<i>bunch of</i>] <i>violets</i> [Ar. s. v. <span dir=\"rtl\">עפר</span>: <i>root of the Cyperus rotundus</i>, v. Löw Pfl.; p. 269]. <span class=\"citation\">Targ. Y. Num. XXI, 12</span>.—<span class=\"citation\">Snh. 99ᵇ</span> (expl. <span dir=\"rtl\">דודאים</span>, <span class=\"citation\">Gen. XXX, 14</span>). <span class=\"citation\">Sabb. 50ᵇ</span>, v. <a href=\"#\" data-headword=\"בַּרְדָּא II\"><span dir=\"rtl\">בַּרְדָּא</span> II</a>. <span class=\"citation\">Ber. 43ᵇ</span> (Ar. some ed. <span dir=\"rtl\">סגילי</span>).</div>","alt":[]},"19050":{"h":"סִיגְמָטִין","r":"O00562","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (sigma, <i>pl.</i> sigmata) <i>semicircular couches for reclining at meals</i>. <span class=\"citation\">Num. R. s. 1</span>, beg. (homiletic play on <span dir=\"rtl\">ויסב</span>, <span class=\"citation\">Ex. XIII, 18</span>, v. <a href=\"#\" data-headword=\"סָבַב\">סָבַב</a>) <span dir=\"rtl\">הרבצתי אתכם בס׳</span> I caused you to recline on <i>sigmata</i> (like noblemen); Tanḥ. B’midb. 2 Var. <a href=\"#\" data-headword=\"סִגְעָא\">סיג׳</a> (some ed. <span dir=\"rtl\">סוג׳</span>), v. <a href=\"#\" data-headword=\"*סְבַסְטִין\">סְבַסְטִין</a>.—Y’lamd. to Num. I, quot. in Ar. <span dir=\"rtl\">כותב ע&quot;ג סגמוס כמה מיסא</span> (read: … <span dir=\"rtl\">סִיגְמָא … מיסון</span>) writes on the <i>sigma</i> the number of courses.</div>","alt":[]},"19051":{"h":"סִיגְנָא I","r":"O00563","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"סְגַן\">סְגַן</a></div>","alt":[]},"19052":{"h":"סִיגְנָא","r":"O00564","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Signa</i> (cmp. <a href=\"#\" data-headword=\"סִכְנִין\">סִכְנִין</a>). <span class=\"citation\">Tosef. Ter. III, 18</span> <span dir=\"rtl\">בפרסגנא</span> ed. Zuck. (Var. <span dir=\"rtl\">בכ׳ ס׳</span>). <span class=\"citation\">Kel. V, 4</span> <a href=\"#\" data-headword=\"סִיגְנַאי\">סִיגְנָה</a>, <a href=\"#\" data-headword=\"סִיגְנוּם\">(סִגְ׳</a>). <span class=\"citation\">Men. VIII, 6</span> (<span class=\"citation\">86ᵇ</span>).—<span class=\"citation\">Eduy. VII, 8</span> בן סִיגְנַיי Ms. M. (ed. <a href=\"#\" data-headword=\"סִיגְנַאי\">סִגְנַאי</a>).</div>","alt":["סִגְ׳ II","כְּפַר ס׳"]},"19053":{"h":"סִיגְנָא III","r":"O00565","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"סוּגְיָינָא\">סוּגְייָנָא</a></div>","alt":[]},"19054":{"h":"סִיגְנַאי","r":"O00566","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיגְנָא III\">preced. art.</a></div>","alt":["סִיגְנָה"]},"19055":{"h":"סִיגְנוּם","r":"O00567","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (signum, σίγνον S.) </div><div class=\"sense\"><b>1)</b> <i>sign, ensign, banner</i>. <span class=\"citation\">Gen. R. s. 6</span>, end <span dir=\"rtl\">ספר משנה תורה היה ס׳ ליהושע וכ׳</span> (Ar. ed. Koh. <span dir=\"rtl\">סגנם</span>, read <a href=\"#\" data-headword=\"סִגְנוּם\">סגנום</a>) the Book of Deuteronomy was to Joshua a (commander’s) banner; … he took it up and showed it to the sun &amp;c.; <span class=\"citation\">Yalk. Josh. 22</span> <span dir=\"rtl\">שגנז יהושע</span> (corr. acc.). <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">נטל סגנוס של וכ׳</span> (some ed. <span dir=\"rtl\">סגנם</span>; corr. acc.) the commander (of the mutinous legion) took the royal ensign and fled.; <span class=\"citation\">Yalk. Ex. 394</span> <a href=\"#\" data-headword=\"סִיגְנִים\">סִיגְנִין</a> (pl.); Tanḥ., ed. Bub., Ki Thissa 15; Y’lamd. to Num. X, 2, quot. inAr. <span dir=\"rtl\">נטלו סִגְנִים וכ׳</span> they (the <i>singulares</i>, v. <a href=\"#\" data-headword=\"סִנְגְּלָרִין\">סִנְגְּלָרִין</a>) took the ensigns &amp;c.—Pl. <a href=\"#\" data-headword=\"סִיגְנִים\">סִיגְנִים</a>, <a href=\"#\" data-headword=\"סִיגְנִים\">סִיגְנִין</a>, <a href=\"#\" data-headword=\"סִיגְנוּם\">סִגְ׳</a> (v. supra); <a href=\"#\" data-headword=\"סִגְנִיּוֹת\">סִיגְנִיּוֹת</a>, <a href=\"#\" data-headword=\"סִיגְנוּם\">סִגְ׳</a>. <span class=\"citation\">Cant. R. to I, 9</span> <span dir=\"rtl\">נטל ס׳ שלהם וכ׳</span> the Lord took away their (the Egyptians’) ensigns &amp;c.; <span class=\"citation\">Yalk. Ex. 232</span>; Tanḥ. <span class=\"citation\">B’shall. 23</span> <span dir=\"rtl\">סגיונות</span> (some ed. <span dir=\"rtl\">סגניניות</span>, corr. acc.); Mekh. B’shall., s. 2 <span dir=\"rtl\">מגפות</span> (Var. <a href=\"#\" data-headword=\"מַגָּנִיּוֹת\">מגניות</a>, corr. acc.; v. <a href=\"#\" data-headword=\"מְנָפָה\">מְנָפָה</a>); <span class=\"citation\">Y. Sot. VIII, 22ᵇ</span> bot. <span dir=\"rtl\">והפיל סיגנם שלהן</span> (corr. acc., or <a href=\"#\" data-headword=\"סִיגְנוּם\">סיגנום</a>).—<span class=\"citation\">Midr. Till. to Ps. XX</span>, end <span dir=\"rtl\">מכיר דגלו מתוך סגנין שלו</span> ed. Bub., not <a href=\"#\" data-headword=\"סִגְנוּם\">סגנון</a>; oth. ed. <span dir=\"rtl\">דגליו מכל סְגָנָיו</span>, read: <span dir=\"rtl\">דגלו מתוך ס׳</span>) recognises his regiment by its colors; <span class=\"citation\">Yalk. Ps. 681</span> <span dir=\"rtl\">סימנין</span>.—[<span class=\"citation\">Tosef. Ab. Zar. V</span> (<span class=\"citation\">VI), 1</span> <span dir=\"rtl\">הסיגנין</span> some ed., read with ed. Zuck. <span dir=\"rtl\">הטִיגָּנִין</span>.]</div><div class=\"sense\"><b>—2)</b> <i>watchword, signal</i>. <span class=\"citation\">Snh. 89ᵃ</span> <span dir=\"rtl\">ס׳ אחד עולה … בס׳ אחד</span> the same watchword (divine oracle) is passed to many prophets, but no two prophets prophesy under the same watchword (use the very same expressions).</div><div class=\"sense\"><b>—3)</b> <i>sign in the heavens, constellation; v.</i> <a href=\"#\" data-headword=\"אִסְטַגְנֵין\">אִסְטגְנֵין</a>.</div>","alt":["סִיגְנוֹן","סִגְ׳"]},"19056":{"h":"סִיגְנֵי","r":"O00568","html":"<div class=\"sense\">, pl. constr. of <a href=\"#\" data-headword=\"סָגָן\">סָגָן</a>.</div>","alt":[]},"19057":{"h":"סִיגְנַיי","r":"O00569","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיגְנָא I\"><span dir=\"rtl\">סִיגְנָא</span> II</a></div>","alt":[]},"19058":{"h":"סִיגְנִים","r":"O00570","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"סִיגְנוּם\">סִיגְנוּם</a>.</div>","alt":["סִיגְנִין I"]},"19059":{"h":"סִיגְנִין II","r":"O00571","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"סְגַן\">סְגַן</a>.</div>","alt":[]},"19060":{"h":"סיגנם","r":"O00572","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sot. VIII, 22ᵇ</span> bot., v. <a href=\"#\" data-headword=\"סִיגְנוּם\">סִיגְנוּם</a></div>","alt":[]},"19061":{"h":"סִיגָּרוֹן I","r":"O00573","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָגַר\">סָגַר</a>, <i>Pi. to surrender</i>, cmp. <span class=\"citation\">I Sam. XXVI, 8</span>) <i>surrender</i>. <span class=\"citation\">Num. R. s. 8</span> <span dir=\"rtl\">כל מי שכותב את עצמו ס׳ למלך וכ׳</span> he who signs himself (is enlisted) for surrender to the king, must renounce his father &amp;c.; <span class=\"citation\">Pesik. R. s. 23—24</span> <span dir=\"rtl\">מכתיב עצמו שרגיון וכ׳ …</span> (corr. acc.).</div>","alt":[]},"19062":{"h":"סִיגָּרוֹן II","r":"O00574","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סִיגָּרוֹן I\">preced.</a>) <i>Siggaron</i> (Guard), surname of the angel Gabriel. <span class=\"citation\">Snh. 44ᵇ</span></div>","alt":[]},"19063":{"h":"סִיד I","r":"O00575","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּד\">סוּד</a></div>","alt":[]},"19064":{"h":"סִיד II","r":"O00576","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>lime, plaster</i>. Sifra Thazr., <span class=\"citation\">Neg., ch. II, Par. 2</span>; <span class=\"citation\">Neg. I, 1</span> <span dir=\"rtl\">כס׳ ההיכל</span> (white color) like the plaster of the Temple walls (less intense than snow). <span class=\"citation\">Ib. 2</span>; Sifra l. c. <span dir=\"rtl\">הפתוך שבס׳ וכ׳</span> the mixture of red and white colors (in plagues) resembles blood mixed with milk; a. fr.—Esp. <i>lime</i> or <i>orpiment</i> used as <i>a depilatory</i> and <i>a cosmetic</i>. <span class=\"citation\">Sabb. VIII, 4</span>; a. fr.; v. <a href=\"#\" data-headword=\"סוּד\">סוּד</a> and <a href=\"#\" data-headword=\"טָפַל\">טָפַל</a>.</div>","alt":[]},"19065":{"h":"סִידָא","r":"O00577","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XXVII, 2</span>; a. e.</div>","alt":[]},"19066":{"h":"סִידּוּק","r":"O00578","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָרַק I\">סָרַק</a>) <i>being cracked</i>; (sub. <span dir=\"rtl\">עיסת</span>) <i>dough, the surface of which is cracked</i> in consequence of fermentation. <span class=\"citation\">Pes. III, 5</span> <span dir=\"rtl\">ס׳ ישרף</span> dough in the stage of <i>sidduḳ</i> (during Passover) must be burnt; expl. <span dir=\"rtl\">נתערבו סדקיו</span>, v. <a href=\"#\" data-headword=\"סֶדֶק\">סֶדֶק</a>; <span class=\"citation\">ib. 48ᵇ</span>; Mekh. Bo s. 9; a. e.</div>","alt":["סִדּ׳"]},"19067":{"h":"סִידּוּר","r":"O00579","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"סָרַר\">(סָרַר</a>), corresp. to b. h. <a href=\"#\" data-headword=\"עֵרֶךְ\">עֵרֶךְ</a>, </div><div class=\"sense\"><b>1)</b> <i>arrangement, order</i>. <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">סִידּוּרוֹ של עולם</span> the natural order, v. <a href=\"#\" data-headword=\"סִילּוֹן I\"><span dir=\"rtl\">סִילּוֹן</span> II</a>. <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> bot. <span dir=\"rtl\">שהיא סִדּוּרוֹ של יום</span> (not <span dir=\"rtl\">סדורה</span>) for this (the section of Amalek) is the order of the day.—[In later Hebr. <a href=\"#\" data-headword=\"ס׳\">ס׳</a> = <span dir=\"rtl\">ס׳ תפלה</span>, the order of prayers, <i>Prayerbook</i>.]</div><div class=\"sense\"><b>—2)</b> <i>piling up, putting in order</i>, esp. on the altar, the golden table &amp;c., opp. <a href=\"#\" data-headword=\"סִילּוּק\">סילוק</a>, removal. <span class=\"citation\">Yoma 24ᵇ</span> <span dir=\"rtl\">ס׳ בזיכין</span> the putting (on the show-bread) of the frankincense from the vessels; <span dir=\"rtl\">ס׳ איברים</span> the offering of the sacrificial parts. <span class=\"citation\">Men. XI, 6</span> <span dir=\"rtl\">ס׳ קנים</span> the arrangement of the tubes for the show-bread. <span class=\"citation\">Ib. 29ᵃ</span>, a. e. <span dir=\"rtl\">סילוקו כסִידּוּרוֹ</span> when it (the show-bread) was removed, it was as fresh as when it was put on; a. fr.</div><div class=\"sense\"><b>—3)</b>  [<i>that which is arranged before a person</i>,] <i>offering, present</i>. <span class=\"citation\">Lev. R. s. 9</span> <span dir=\"rtl\">טלו סִדּוּרוֹ</span> take what he has brought as his tribute.</div><div class=\"sense\"><b>—4)</b> <i>the daily ration</i>.—Pl. <span dir=\"rtl\">סִידּוּרִים</span>. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">ס׳ של דוב</span> the portions (of honey) designated for the bear (in the vivarium).</div><div class=\"sense\"><b>—5)</b>  (= <a href=\"#\" data-headword=\"עֵרֶךְ\">עֵרֶךְ</a>) <i>determination of a man’s obligation</i> (<i>to the sanctuary &amp;c</i>.) <i>based upon his financial ability</i> (v. <a href=\"#\" data-headword=\"סָדַר\">סָדַר</a> <i>Pi.</i> 2); <i>exemption from seizure</i>. <span class=\"citation\">B. Mets. 113ᵇ</span> <span dir=\"rtl\">עיקר ס׳ בערכין כתיב</span> the original exemption law is stated with reference to vows (<span class=\"citation\">Lev. XXVII, 8</span>). <span class=\"citation\">Y. Naz. II, 51ᵈ</span> bot. <span dir=\"rtl\">סִידּוּרוֹ עלי וכ׳</span> if one said (pointing to a person), ‘I vow his <i>siddur</i>’ (instead of <span dir=\"rtl\">ערכו</span>), he must pay his value according to his age.—</div><div class=\"sense\"><b>*6)</b> <i>net in the flour mill</i>. <span class=\"citation\">Tosef. Kel. B. Mets. II, 15</span> <span dir=\"rtl\">הס׳ והסדן וכ׳</span> the net and the block of the mill, if made of metal &amp;c.—Sifra Metsorʿa, Zabim, Par. 1, ch. II, v. <a href=\"#\" data-headword=\"סָרוּד\">סָרוּד</a>.</div>","alt":["סִדּ׳ I"]},"19068":{"h":"סִידּוּר II","r":"O00580","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Siddur</i>, an Amora. <span class=\"citation\">Y. Ḥall. II, 58ᶜ</span> top. <span class=\"citation\">Y. Sabb. VII, 9ᶜ</span> top (ed. Krot. <span dir=\"rtl\">סירור</span>).</div>","alt":[]},"19069":{"h":"סִידּוּרָא","r":"O00581","html":"<div class=\"sense\"> , <i>arrangement, order, row</i>. <span class=\"citation\">Targ. Y. Num. XIX, 4</span>, sq. (not <span dir=\"rtl\">סְדוּ׳</span>). <span class=\"citation\">Targ. I Chr. XXI, 23</span>. <span class=\"citation\">Targ. Esth. II, 15</span> (h. text <a href=\"#\" data-headword=\"תּוֹר\">תּוֹר</a>).—Pl. <span dir=\"rtl\">סִידּוּרִין</span>, <span dir=\"rtl\">סִידּוּרַיָּא</span>, <a href=\"#\" data-headword=\"סִידּוּק\">סִדּ׳</a>. <span class=\"citation\">Targ. Y. Lev. XXIV, 6</span>, sq. <span class=\"citation\">Targ. Y. Num. XIX, 3</span> (not <span dir=\"rtl\">סְדוּ׳</span>); a. fr.</div>","alt":["סִדּ׳"]},"19070":{"h":"סִידְק־","r":"O00582","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סֶדֶק\">סֶדֶק</a></div>","alt":[]},"19071":{"h":"סִידְקָא","r":"O00583","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִדְקָא\">סִדְקָא</a></div>","alt":[]},"19072":{"h":"סִידְקִי","r":"O00584","html":"<div class=\"sense\"> (interch. with <a href=\"#\" data-headword=\"סִירְקִי\">סִירְקִי</a>) m. (v. <a href=\"#\" data-headword=\"סָדַק\">סָדַק</a>) </div><div class=\"sense\"><b>1)</b> <i>small dealer, retailer</i> in the market, <i>huckster</i>, contrad. to <a href=\"#\" data-headword=\"פַּלְטֵר I\">פלטר</a> shop-keeper. <span class=\"citation\">Y. Shek. VIII, beg. 51ᵃ</span> (ref. to <span class=\"citation\">Deut. XXVIII, 66</span>) <span dir=\"rtl\">ופחדת … זה שהוא לוקח מן הס׳ וכ׳</span> ‘and thou shalt be in fear day and night’, that is, he who buys from the huckster (who cannot lay in stock for a year), ‘and thou shalt have no assurance of thy life’—that is, he who buys from the shop-keeper; ib. III, 47ᶜ <a href=\"#\" data-headword=\"ציוקי\">ציוקי</a> (corr. acc.); <span class=\"citation\">Y. Sabb. VIII, 11ᵃ</span> bot.; Esth. R. introd., beg.; a. fr.</div><div class=\"sense\"><b>—2)</b> (also fem., sub. <a href=\"#\" data-headword=\"שוק\">שוק</a>) <i>market-stand, provision market</i>. <span class=\"citation\">Y. Ned. XI, 42ᶜ</span> bot. <span dir=\"rtl\">והיו שם צבורים בס׳</span> and there were provisions piled up in the market. <span class=\"citation\">Ruth R. to I, 1</span> <span dir=\"rtl\">יצתה ועומדת בס׳ …</span> (not <span dir=\"rtl\">מעילת</span>) his maid servant went out and stood in the market (waiting for her turn to buy provision); <span class=\"citation\">Yalk. Ruth 598</span>. <span class=\"citation\">Y. Dem. III, 23ᶜ</span> <span dir=\"rtl\">ס׳ שהיתה מסתפקת וכ׳</span> a provision stand which was supplied with forbidden fruits one day; ib. II, 22ᶜ top <a href=\"#\" data-headword=\"כּוּרְכְּיָא\">כורכיא</a> (corr. acc.); Y. Keth. I, 25ᵈ bot. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"סִרְיָינָא\">סִירְ׳</a>) <a href=\"#\" data-headword=\"סִידְקִית\">סִידְקִית</a></span>; a. fr.—<span class=\"citation\">Y. Kil. II, beg. 27ᶜ</span> (in Chald. dict.) <span dir=\"rtl\">בסירקי</span> in the market-stand.</div>","alt":[]},"19073":{"h":"סִידְקִית","r":"O00585","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סִידְקִי\">same</a>, v. preced.—2) (adj.) <i>very fine</i>. <span class=\"citation\">Erub. 53ᵃ</span> <span dir=\"rtl\">נקב מחט ס׳</span> the eye of a very fine needle.— 3) <i>small ware, tinsel</i>. <span class=\"citation\">Sot. 40ᵃ</span> <span dir=\"rtl\">מוכר מיני ס׳</span> one who sells tinsel, opp. <span dir=\"rtl\">אבנים טובות ומרגליות</span>.</div>","alt":["סִדְ׳"]},"19074":{"h":"סידתא","r":"O00586","html":"<div class=\"sense\">, Pesik. Shek., p. 11ᵃ, read: <a href=\"#\" data-headword=\"סִירְתָּא\">סִירְתָּא</a>.</div>","alt":[]},"19075":{"h":"*סִיוָאָה","r":"O00587","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>of Siva</i>. <span class=\"citation\">Nidd. 20ᵃ</span> <span dir=\"rtl\">כלבושא ס׳</span> (Ar. <a href=\"#\" data-headword=\"סייבא\">סייבא</a>, Var. <span dir=\"rtl\">סיוהא</span>, v. Ar. ed. Koh. s. v. <a href=\"#\" data-headword=\"סייבא\">סייבא</a> a. <a href=\"#\" data-headword=\"סַיָּינָא\">סיינא</a>) of the dark color of a Siva cloak; [oth. opin.: <i>dirty-dark</i>, v. Ar. l. c.].</div>","alt":[]},"19076":{"h":"סְיוּגָא","r":"O00588","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, constr. <a href=\"#\" data-headword=\"סְיוּגָא\">סְיוּגַת</a> (סוּג I) <i>fencing in, protection</i>. <span class=\"citation\">Targ. Mic. VII, 4</span>.</div>","alt":[]},"19077":{"h":"סִיּוּד","r":"O00589","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּד\">סוּד</a>) <i>a coat of whitewash</i>. <span class=\"citation\">B. Bath. 53ᵇ</span></div>","alt":[]},"19078":{"h":"סְיוּטָא","r":"O00590","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סוּט\">סוּט</a>, <i>Ithpe.</i>) <i>fright</i>. <span class=\"citation\">B. Kam. 37ᵇ</span> <span dir=\"rtl\">הך שופר קמא ס׳ בעלמא וכ׳</span> that first goring when the animal heard the sound of a trumpet, was merely due to the fright which seized it. <span class=\"citation\">Yoma 22ᵇ</span> <span dir=\"rtl\">חזא ס׳ בחלמיה</span> saw a panic in his dream (frightening demons, Rashi); <span class=\"citation\">Yalk. Sam. 117</span>.</div>","alt":[]},"19079":{"h":"סִיּוּם","r":"O00591","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּם I, <i>Pi.</i>) <i>conclusion, finishing</i>. Tanḥ. Haăz. 5 <span dir=\"rtl\">ס׳ חתימתו וכ׳</span> the final letter of Moses’ signature. Ib. <span dir=\"rtl\">כאדם … וחותם … בס׳ ספרו</span> like a man that finishes his book and signs his name (in an acrostic) at the end of his book.</div>","alt":[]},"19080":{"h":"סִיּוּמָא","r":"O00592","html":"<div class=\"sense\"> <span class=\"citation\">B. Bath. 22ᵃ</span> <span dir=\"rtl\">משום דלא הוו בס׳</span> because they had not been present at the final lecture of Raba’s course; [oth. opin.: at the final meeting when the election of the chief of the academy was held].</div>","alt":[]},"19081":{"h":"סִיוָן","r":"O00593","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Sivan</i>, the third month of the Hebrew calendar, of thirty days, varying between the tenth of May and the eighth of July. <span class=\"citation\">Targ. Esth. VIII, 9</span>. Targ. II Esth. III, 7; a. e.—<span class=\"citation\">Sabb. 87ᵇ</span>. <span class=\"citation\">R. Hash. 7ᵇ</span> <span dir=\"rtl\">ששה בס׳ וכ׳</span> the sixth of S. is the New Year for the two loaves (the wheat crop); a. e.</div>","alt":[]},"19082":{"h":"סִיּוּעַ","r":"O00594","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סִיעַ\">סִיעַ</a>) <i>help, assistance</i>. Y. Sabb. XVIII, end, 16ᶜ (ref. to <span dir=\"rtl\">מסעדין</span>, Mish. <span class=\"citation\">Sabb. XVIII, 3</span>) <span dir=\"rtl\">אי זהו הס׳</span> wherein does the assistance (rendered to travailing animals) consist? <span class=\"citation\">Lev. R. s. 24</span> <span dir=\"rtl\">ומה אם הרוחות … לשום ס׳ צריכין ס׳ אנו שנבראנו לס׳ וכ׳</span> when the spirits that are not made dependent on assistance, require assistance, how much more do we (human beings) who are made dependent on assistance &amp;c. <span class=\"citation\">Ib.</span> (ref. to <span dir=\"rtl\">עזרך … יסעדך</span>, <span class=\"citation\">Ps. XX, 3</span>) <span dir=\"rtl\">עזרה וס׳ וכ׳</span> help and assistance come from Zion. <span class=\"citation\">Esth. R. to I, 1</span> <span dir=\"rtl\">וכי לסִיּוּעָן של וכ׳</span> does the Lord need the assistance of the nations?—<span class=\"citation\">Ex. R. s. 43</span> <span dir=\"rtl\">עשו לך ס׳</span> they have given thee (the Lord) an assistant (in the golden calf); a. e.</div>","alt":[]},"19083":{"h":"סִיּוּעַ ²","r":"O00595","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Job VI, 13</span>. <span class=\"citation\">Targ. Y. Gen. XLIX, 25</span>; a. e.</div>","alt":["סִיּוּעָא","סְיוּ׳"]},"19084":{"h":"סִיּוּפָא","r":"O00596","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּף II) </div><div class=\"sense\"><b>1)</b> <i>ending, failing</i>. <span class=\"citation\">Targ. Y. II, Deut. XXVIII, 65</span> <span dir=\"rtl\">סִיּוּף עיינין</span> (not <a href=\"#\" data-headword=\"*יִסּוֹף\">יסוף</a>) failing of eye-sight.</div><div class=\"sense\"><b>—2)</b> pl. constr. <span dir=\"rtl\">סִיּוּפֵי</span> the <i>fruit left to the end, late fruit</i>. <span class=\"citation\">Targ. Am. VIII, 1</span>, sq. (ed. Lag. <a href=\"#\" data-headword=\"סַיָּיפִי\">סְיָיפֵי</a>, <span dir=\"rtl\">סְיָפֵי</span>). <span class=\"citation\">Targ. Mic. VII, 1</span> (h. text <span dir=\"rtl\">אספי</span>); v. <a href=\"#\" data-headword=\"סוֹף\">סוֹף</a>.</div>","alt":[]},"19085":{"h":"סְיוּרָא","r":"O00597","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*סְוִירָא\">סְוֵירָא</a></div>","alt":[]},"19086":{"h":"סִיחַ","r":"O00598","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּחַ\">סוּחַ</a></div>","alt":[]},"19087":{"h":"סַיָּח","r":"O00599","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּיח\">סַיָּיח</a></div>","alt":["סַיָּחָה"]},"19088":{"h":"סִיחָה","r":"O00600","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>talk, conversation</i>. <span class=\"citation\">B. Bath. 78ᵇ</span> <span dir=\"rtl\">ואמאי קרי ליה סיח שמהלך אחר ס׳ נאה</span> and why do they call a young ass <i>sayyaḥ</i>? Because it follows a persuasive talk (of its driver, whereas the old ass must be struck). <span class=\"citation\">Ib.</span> (play on <span dir=\"rtl\">עיר סיחון</span>, <span class=\"citation\">Num. XXI, 27</span>) <span dir=\"rtl\">אם משים … כְּעַיִר שמהלך אחר ס׳ נאה</span> if a man makes himself like (is as obedient as) the young ass that follows &amp;c. Ib. (play on <a href=\"#\" data-headword=\"עֵר I\">ער</a> ib. 28) <span dir=\"rtl\">זה המהלך אחר יצרו … ס׳ נאה</span> that is he who follows his evil inclination as the young ass follows &amp;c. <span class=\"citation\">Snh. 94ᵃ</span> (play on <span dir=\"rtl\">ס̇נח̇ר̇י̇ב̇</span>) <span dir=\"rtl\">שסִיֹחָתוֹ ר̇י̇ב̇</span> whose talk is strife. <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">כל שסיחתו בבבל</span> he whose conversation shows that he is a Babylonian. <span class=\"citation\">Ḥag. 5ᵇ</span> (ref. to <span class=\"citation\">Am. IV, 13</span>) <span dir=\"rtl\">אפי׳ ש׳ יתירה וכ׳</span> even superfluous talk between husband and wife is brought up against man in his hour of death; <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">אפי׳ ש׳ קלה שאדם משיח וכ׳</span> even frivolous talk &amp;c. <span class=\"citation\">Succ. 28ᵃ</span> <span dir=\"rtl\">שִׂיחַת חולין</span> profane (secular) talk. <span class=\"citation\">Yalk. Num. 764</span> <span dir=\"rtl\">שיחת כנענים</span> the language of the Canaanites; a. fr.—Pl. <span dir=\"rtl\">סִיחוֹת</span>, <a href=\"#\" data-headword=\"סִיפְתָא\">שִׂ׳</a>. Y. Gitt. IX, end, 50ᵈ <span dir=\"rtl\">(<a href=\"#\" data-headword=\"ש׳\">ש׳</a>) <span dir=\"rtl\">ס׳ בני אדם משיחין</span></span> when people talk what people say (i.e. when you can trace the rumor; v. Bab. <span class=\"citation\">Gitt. 89ᵃ</span>); a. e.</div>","alt":["שִׂיחָה"]},"19089":{"h":"סַיחוּי","r":"O00601","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְחָא\">סחה</a>, v. <a href=\"#\" data-headword=\"סְחֵי\">סְחֵי</a>) <i>swimming</i>. <span class=\"citation\">Yoma 77ᵇ</span> <span dir=\"rtl\">יכול יעבירנו בס׳</span> you might think one could cross the river by swimming; Yalk. Ez. 381 <span dir=\"rtl\">בשוחי</span> (read: <span dir=\"rtl\">בשֵׂחוּי</span>).</div>","alt":[]},"19090":{"h":"סִיחוֹן","r":"O00602","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Sihon</i>, King of the Amorites. <span class=\"citation\">Ḥull. 60ᵇ</span>; <span class=\"citation\">Gitt. 38ᵃ</span> <span dir=\"rtl\">עמון זמואב טהרו בס׳</span> the districts of Ammon and Moab became permitted (a legitimate conquest) to the Israelites through Sihon (who had conquered them from Ammon and Moab, and from whom Israel took them by the right of conquest). <span class=\"citation\">B. Bath. 78ᵇ</span>, v. <a href=\"#\" data-headword=\"סִיחָה\">סִיחָה</a>; a. fr.—[<span class=\"citation\">Gen. R. s. 12</span> <span dir=\"rtl\">כפר סיחון</span> (some ed. <span dir=\"rtl\">סיחין</span>; oth. <span dir=\"rtl\">שיחין</span>), v. <a href=\"#\" data-headword=\"שִׁיחִין\">שִׁיחִין</a>.]</div>","alt":[]},"19091":{"h":"סִיט","r":"O00603","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּט\">סוּט</a>; cmp. <a href=\"#\" data-headword=\"סוּט\">הֶסֵּיט</a>), only with art. <a href=\"#\" data-headword=\"סוּט\">הַסִּיט</a> (cmp. <a href=\"#\" data-headword=\"הַנֵּץ\">הַנֵּץ</a>) [<i>swinging the forefinger</i>, cmp. the expression <span dir=\"rtl\">נטה יד</span>,] <i>hassiṭ, the distance between the tip of the thumb and that thumb and that of the index finger when held apart, or between the root of the thumb and the tip of the index finger, when the former is leaning against the latter</i> <span dir=\"rtl\">(כפוף</span>). [Commentators differ in the definition of our w.—Maim. to <span class=\"citation\">Kel. XIII, 4</span> distinguishes between <span dir=\"rtl\">מלא הס׳</span> a. <span dir=\"rtl\">מלא רחב הס׳</span>.] <span class=\"citation\">Sabb. XIII, 4</span> <span dir=\"rtl\">כמלא רחב הס׳ כפול</span> the double size of a <i>hassiṭ</i>; <span class=\"citation\">ib. 106ᵃ</span> רב יוסף מחוי כפול R. J. showed the double measure (Ar. <span dir=\"rtl\">כפוף</span>, v. supra); <span dir=\"rtl\">רב חייא … מחוי פשוט</span> R. H. b. A. showed the single measure (Ar.: with the thumb stretched); Tosef. ib. IX (X), 3 <span dir=\"rtl\">מלא הס׳ כפול</span>. <span class=\"citation\">Orl. III, 2</span>; a. fr.—<span class=\"citation\">Num. R. s. 18</span>; Tanḥ. Ḥuck. 1 <span dir=\"rtl\">מלא הס׳ יש בו וכ׳</span> within a distance of a <i>hassiṭ</i> (in the human head) there are several wells (seats of mucous secretions).</div>","alt":[]},"19092":{"h":"סִיטּוּמְתָּא","r":"O00604","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְטַם\">סְטַם</a>) <i>seal, signet ring</i>. <span class=\"citation\">Targ. Y. Gen. XXXVIII, 18</span>. <span class=\"citation\">Targ. Esth. VIII, 2</span>; a. e.—<span class=\"citation\">B. Mets. 74ᵃ</span> <span dir=\"rtl\">האי ס׳ קניא</span> putting the seal (mark) on the wine bought gives possession.</div>","alt":["סִטּ׳"]},"19093":{"h":"סִיטוֹן","r":"O00605","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σιτώνης) <i>corn-merchant</i>, in gen. <i>wholesale provision dealer</i>, contrad. to <span dir=\"rtl\">חנוני</span> shop-keeper, and <span dir=\"rtl\">בעל הבית</span> the producer. <span class=\"citation\">B. Bath. V, 10</span>. <span class=\"citation\">Tosef. Dem. III, 13</span>; a. fr.—Pl. <span dir=\"rtl\">סִיטוֹנוֹת</span>. <span class=\"citation\">Dem. II, 4</span> <span dir=\"rtl\">הס׳ ומוכרי וכ׳</span> the wholesale provision merchants and the corn dealers. <span class=\"citation\">Kel. XII, 1</span>; a. e.—[<span class=\"citation\">Midr. Till. to Ps. XXIII</span> <span dir=\"rtl\">הסיטון</span>, v. <a href=\"#\" data-headword=\"אַמְיַינְטוֹן\">אַמְיַינְטוֹן</a>.]</div>","alt":[]},"19094":{"h":"סִיטוֹנָא","r":"O00606","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סִיטוֹן\">same</a>. <span class=\"citation\">Y. Maas. Sh. IV, 54ᵈ</span> <span dir=\"rtl\">לחטוניא</span> (read: <span dir=\"rtl\">לסיטונא</span> or <span dir=\"rtl\">לסִיטוֹנֵיס</span>).).</div><div class=\"sense\"><b>—2)</b>  (= frumentarius) <i>commissary of the army</i>.—Pl. <span dir=\"rtl\">סִיטוֹנִין</span>. <span class=\"citation\">Targ. Is. XXI, 8</span> <span dir=\"rtl\">בסִיטוֹנֵיהוֹן</span> (ed. Lag. <span dir=\"rtl\">בסוטנהוּן</span>; v. Sm. Ant. s. v. Frumentarii).</div>","alt":[]},"19095":{"h":"סיטוסימה","r":"O00607","html":"<div class=\"sense\">, read: <span dir=\"rtl\">סִיטִיסְטָא</span> m. pl. (σιτιστά, v. Matth. XXII, 4) <i>fatlings</i>. Y’lamd. to Gen. XXXVII, quot. in Ar. <span dir=\"rtl\">אפי׳ יהו לי פטומות וס׳ וכ׳</span></div>","alt":["סיטסמא"]},"19096":{"h":"סיטיון","r":"O00608","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. II, 8</span>, v. <a href=\"#\" data-headword=\"סְטֵיו\">סְטֵיו</a></div>","alt":[]},"19097":{"h":"*סִיטְמָנַיָּא","r":"O00609","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְטַם\">סְטַם</a>) <i>sealed-up things, hidden treasures</i>. <span class=\"citation\">Targ. Y. II, Deut. XXXIII, 19</span> ed. Vien., v. <a href=\"#\" data-headword=\"סִימָא II\"><span dir=\"rtl\">סִימָא</span> II</a>.</div>","alt":[]},"19098":{"h":"סִיטְנָא","r":"O00610","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְטַן II\"><span dir=\"rtl\">סְטַן</span> II</a></div>","alt":[]},"19099":{"h":"סיטנו","r":"O00611","html":"<div class=\"sense\">, Tanḥ. Shof’ṭim 2; ed. Bub. 3 <a href=\"#\" data-headword=\"שיטנו\">שיטנו</a>, read: <span dir=\"rtl\">שִׁיטְרוֹ</span>, v. <a href=\"#\" data-headword=\"שֶׁטֶר\">שֶׁטֶר</a></div>","alt":[]},"19100":{"h":"סִיטְרָא","r":"O00612","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְטַר II\"><span dir=\"rtl\">סְטַר</span> II</a></div>","alt":[]},"19101":{"h":"סַיֵּיב","r":"O00613","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּב\">סוּב</a></div>","alt":[]},"19102":{"h":"סַיָּיארָא","r":"O00614","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּירָא\">סַיָּירָא</a></div>","alt":[]},"19103":{"h":"סייבא","r":"O00615","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*סִיוָאָה\">סִיוׇאָה</a>.</div>","alt":[]},"19104":{"h":"סְיָיג","r":"O00616","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּג I) <i>fence, hedge.</i> <span class=\"citation\">Orl. I, 1</span> <span dir=\"rtl\">הנוטע לס׳</span> he that plants for the sake of forming a hedge (not for the fruit); a. fr.—Trnsf. (cmp. <a href=\"#\" data-headword=\"גֶּדֶר I\">גֶּדֶר</a>) <i>guard, preventive measure, protection</i>. <span class=\"citation\">Nidd. 3ᵇ</span> … <span dir=\"rtl\">ומיהו עשה ס׳ לדבריך דעבדינן ס׳</span> but at least set a guard to thy words (add a restriction), for wherein does this case differ from other Biblical laws around which we (the Rabbis) place a fence? Y. ib. I, beg. 48ᵈ. <span class=\"citation\">Ab. d’R. N. ch. I</span>, v. <a href=\"#\" data-headword=\"סוּג I\"><span dir=\"rtl\">סוּג</span> I</a>. <span class=\"citation\">Ab. I, 1</span> <span dir=\"rtl\">עשו ס׳ לתורה</span> make a fence around the Law. <span class=\"citation\">Ib. III, 13</span> <span dir=\"rtl\">מסורת ס׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"מַסּוֹרֶת\">מַסּוֹרֶת</a>; <span dir=\"rtl\">מעשרות ס׳ לעושר</span> tithe-giving is a preserver of wealth; <span dir=\"rtl\">נדרים ס׳ וכ׳</span> vows are a help to self-control; <span dir=\"rtl\">ס׳ לחכמה וכ׳</span> a protection of wisdom is silence; a. fr.</div>","alt":["סְיָג"]},"19105":{"h":"סְיָיג ²","r":"O00617","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Mic. VII, 4</span>. <span class=\"citation\">Targ. Y. Num. XXII, 25</span>; a. e.—Y. Dem. III, 23ᵇ bot. <span dir=\"rtl\">הא אזיל ס׳ דגוברא</span> the man’s fence would soon be gone.—<span class=\"citation\">Y. Kidd. I, end, 61ᵈ</span>, a. e. <span dir=\"rtl\">סייגין סְיָיגָה</span>, v. <a href=\"#\" data-headword=\"סוּג\">סוּג</a> I ch.; <span class=\"citation\">Yalk. Prov. 935</span> <span dir=\"rtl\">סגיי סוגייא</span> (corr. acc.).—Pl. <span dir=\"rtl\">סְיָיגִין</span>. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot., v. <a href=\"#\" data-headword=\"כּוּבָּא I\"><span dir=\"rtl\">כּוּבָּא</span> I</a>.</div>","alt":["סְיָיגָא","סְיָ׳"]},"19106":{"h":"סִיֵּיד","r":"O00618","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּד\">סוּד</a></div>","alt":["סַיֵּיד"]},"19107":{"h":"סַיָּיד","r":"O00619","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סִיֵּיד\">preced.</a>) <i>lime-burner, worker in lime, plasterer</i>. <span class=\"citation\">Koh. R. to IX, 8</span> <span dir=\"rtl\">הלך הס׳ לסִידוֹ</span> the lime-burner went to his lime (workshop). [<span class=\"citation\">Tosef. B. Bath. II, 17</span> <span dir=\"rtl\">בסייד</span>, read: <span dir=\"rtl\">בסִיד</span>.]—Pl. <span dir=\"rtl\">סַיָּידִים</span>, <span dir=\"rtl\">סַיָּידִין</span>. <span class=\"citation\">Sabb. 80ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּף\">כַּף</a>. <span class=\"citation\">Eduy. II, 8</span>, a. e. <span dir=\"rtl\">סנדל של ס׳</span> the (wooden) sandal of the lime-burners; a. e.</div>","alt":[]},"19108":{"h":"סַיָּיח","r":"O00620","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>foal, young ass</i>. <span class=\"citation\">B. Bath. V, 3</span>. <span class=\"citation\">Ib. 78ᵇ</span>, v. <a href=\"#\" data-headword=\"סִיחָה\">סִיחָה</a>. <span class=\"citation\">R. Hash. 3ᵃ</span> <span dir=\"rtl\">סיחון שדומה לס׳ וכ׳</span> he was named Sihon, because he was (quick or untamed) as a foal in the desert. Pesik. Ekha, p. 123ᵃ, v. <a href=\"#\" data-headword=\"כפי\">כָּפָה</a>; a. e.—Pl. <span dir=\"rtl\">סַיָּיחִים</span>, <span dir=\"rtl\">סַיָּיחִין</span>. Y. Taan. II, 65ᵇ <span dir=\"rtl\">ס׳ מבפנים ואימותיהן וכ׳</span> foals (sucklings) within and their mothers without; (Bab. <span class=\"citation\">ib. 16ᵃ</span> <span dir=\"rtl\">הבהמות … והוולדות</span>). <span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot. [read:] <span dir=\"rtl\">שלא יאכיל … סייח לס׳</span> he must not feed … foals with a foal (sell one of the animals in his keeping to feed the others). <span class=\"citation\">Tosef. B. Mets. II, 20</span>. <span class=\"citation\">Lev. R. s. 20</span>, a. e. <span dir=\"rtl\">הרבה ס׳ מתו וכ׳</span> many foals died and their skins were spread on their mothers’ backs (many old men survive the young); a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"סַיָּיחָה\">סַיָּיחָה</a>. <span class=\"citation\">Esth. R. to III, 1</span>; <span class=\"citation\">Yalk. ib. 1053</span>.</div>","alt":["סַיָּח"]},"19109":{"h":"סַיְיחָא","r":"O00621","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>swimmer</i>, v. <a href=\"#\" data-headword=\"סַחְיָיא\">סַחְיָיא</a>.</div>","alt":[]},"19110":{"h":"סַיָּיחָה","r":"O00622","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּיח\">סַיָּיח</a></div>","alt":[]},"19111":{"h":"סייטא","r":"O00623","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Gen. XV, 11</span> Levita, read: <a href=\"#\" data-headword=\"טְיָיסָא\">טְיָיסָא</a>.</div>","alt":[]},"19112":{"h":"סַיְיטָן","r":"O00624","html":"<div class=\"sense\">, m. (<a href=\"#\" data-headword=\"סוּט\">סוּט</a>) <i>flighty</i>, v. <a href=\"#\" data-headword=\"*טַיְיסָן\">טַיְיסָן</a>.</div>","alt":[]},"19113":{"h":"סַיָּיאנָא","r":"O00625","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּינָא\">סַיָּינָא</a></div>","alt":[]},"19114":{"h":"סַיַּין","r":"O00626","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. I Deut. XXXIII, 28</span>, v. <a href=\"#\" data-headword=\"סְנַן\">סְנַן</a></div>","alt":[]},"19115":{"h":"סַיָּינָא","r":"O00627","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סְיָן\">סְיָן</a>) <i>trowel</i>, name of a <i>felt cap with a shade in front</i>. <span class=\"citation\">Sabb. 138ᵇ</span> Ms. M. (ed. <a href=\"#\" data-headword=\"סַיָּאנָא\">סַיָּאנָא</a>); <span class=\"citation\">Erub. 102ᵇ</span>. <span class=\"citation\">Sabb. 119ᵃ</span> <span dir=\"rtl\">אותבה בסַיָּינֵיה</span> he stuck the jewel on his cap; (Ms. M. <span dir=\"rtl\">בסדיניה</span>; Ms. O. <span dir=\"rtl\">בסדיניה וא׳&#x27;ל בסַיָּיאנֵיה דרישיה</span>; <span class=\"citation\">Yalk. Gen. 16</span>, a. Is. 356 <span dir=\"rtl\">בסדיניה</span>).—[<span class=\"citation\">Nidd. 20ᵃ</span> סיינא Ar. ed. Koh., v. <a href=\"#\" data-headword=\"*סִיוָאָה\">סִיוָאָה</a>.]</div>","alt":[]},"19116":{"h":"סַיָּיעָא","r":"O00628","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סִיּוּעַ ²\">סִיּוּעָא</a>) <i>help</i>. <span class=\"citation\">Targ. Lam. IV, 17</span>.</div>","alt":[]},"19117":{"h":"סַיַּיעְתָּא","r":"O00629","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סַיָּיעָא\">same</a>. <span class=\"citation\">Targ. Ps. XLVI, 2</span> (ed. Wil. <a href=\"#\" data-headword=\"סִיעֲתָא\">סִיעֲתָא</a>, read <a href=\"#\" data-headword=\"סַיַּעְתָּא\">סַיַּעְתָּא</a>).—<span dir=\"rtl\">ס׳ דשמיא</span>, <span dir=\"rtl\">ס׳ מן שמיא</span> <i>divine assistance, providential grant</i>. <span class=\"citation\">B. Bath. 55ᵃ</span>, v. <a href=\"#\" data-headword=\"*אַנְדִּיסְקֵי\">אַנְדִּיסְקֵי</a>. <span class=\"citation\">Meg. 6ᵇ</span> <span dir=\"rtl\">ס׳ מן ש׳ הוא</span> success depends on divine grace (not on man’s work alone); a. e.</div><div class=\"sense\"><b>—2)</b> <i>support</i> of an argument, <i>confirmation</i>, opp. <span dir=\"rtl\">תיובתא</span> refutation. <span class=\"citation\">B. Mets. 48ᵃ</span> <span dir=\"rtl\">קרא לא תיובתא ולא ס׳</span> (Ms. F. a. R. 2 … <span dir=\"rtl\">תיובתיה … סַיַּיעְתֵּיה</span>) no argument either against or in favor of his opinion could be derived from the text.</div>","alt":["סַיַּעְ׳"]},"19118":{"h":"סַיִּיף","r":"O00630","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּף II) <i>sword.</i> <span class=\"citation\">Kel. XIII, 1</span>. <span class=\"citation\">Ib. XIV, 5</span>. <span class=\"citation\">Lev. R. s. 35</span>; <span class=\"citation\">Sifré Deut. 40</span>, v. <a href=\"#\" data-headword=\"כָּרַךְ\">כָּרַךְ</a>; a. fr.—Esp. <i>execution by the sword</i> (= <a href=\"#\" data-headword=\"הֶרֶג\">הֶרֶג</a>), v. <span class=\"citation\">Snh. VII, 3</span>. <span class=\"citation\">Ib. 50ᵃ</span> <span dir=\"rtl\">סקילה חמורה מס׳</span> stoning is a severer punishment than beheading. <span class=\"citation\">Ib. 52ᵇ</span> <span dir=\"rtl\">בס׳</span> is to be put to death with the sword; a. fr.</div>","alt":["סַיִּף"]},"19119":{"h":"סַיְיפָא","r":"O00631","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XXVII, 3</span> (ed. Berl. <a href=\"#\" data-headword=\"סֵיפָא\">סֵיפָ׳</a>). <span class=\"citation\">Targ. Y. Num. XIX, 16</span>; a. fr.—<span class=\"citation\">B. Bath. 4ᵃ</span> אם סַיְיפָךְ עלך Ar. (ed. <span dir=\"rtl\">זיינך</span>), v. <a href=\"#\" data-headword=\"זֵין II\">זֵינָא</a>.—Pl. <span dir=\"rtl\">סְיָיפִין</span>, <a href=\"#\" data-headword=\"סַיָּיפִי\">סְיָיפֵי</a>, <a href=\"#\" data-headword=\"סְיָף\">סְיָפ׳</a>. <span class=\"citation\">Targ. I Chr. V, 18</span>. <span class=\"citation\">Targ. Is. II, 4</span>; a. fr.—<span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">כי הוה שדי עפרא הוו ס׳</span> (not <span dir=\"rtl\">סייפו</span>) when he threw dust, it changed into swords (ref. to <span class=\"citation\">Is. XLI, 2</span>).—V. <a href=\"#\" data-headword=\"סֵיפָא\">סֵיפָא</a>.</div>","alt":["סַיְפָא","(סֵיפָא)"]},"19120":{"h":"סַיָּיפָא","r":"O00632","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַיְיפָא\">preced.</a>) <i>sword-bearer, warrior</i>. <span class=\"citation\">Ab. Zar. 17ᵇ</span> אי ספרא לא ס׳ ואי ס׳ וכ׳ Ar. (ed. <span dir=\"rtl\">אי סַיָּיפִי לא וכ׳</span></div>","alt":[]},"19121":{"h":"סְיָיפָא","r":"O00633","html":"<div class=\"sense\">, pl. <a href=\"#\" data-headword=\"סַיָּיפִי\">סְיָיפֵי</a>, v. <a href=\"#\" data-headword=\"סִיּוּפָא\">סִיּוּפָא</a>.</div>","alt":[]},"19122":{"h":"סְיָיפוֹת","r":"O00634","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>pl</i>. (v. <a href=\"#\" data-headword=\"סִיּוּפָא\">סִיּוּפָא</a>) <i>late</i> (<i>stunted</i>) <i>fruits</i>. Tosef<i>.</i> <span class=\"citation\">Dem. I, 3</span>, v. <a href=\"#\" data-headword=\"סוּף II\"><span dir=\"rtl\">סוּף</span> II</a>. <span class=\"citation\">Gen. R. s. 22</span> <span dir=\"rtl\">שהיה אוכל … את הס׳</span> who ate the first fruits and presented the late fruits to the king; a. e.—Constr. (m.) <a href=\"#\" data-headword=\"סַיָּיפִי\">סְיָיפֵי</a>, <span dir=\"rtl\">סְיָפֵי</span>. Midr. Sam. ch. I <span dir=\"rtl\">סְיָפֵי סַיְפָנִים</span> (or <span dir=\"rtl\">סֵיפֵי סֵיפָ׳</span>) the very poorest produces.</div>","alt":[]},"19123":{"h":"סַיָּיפִי","r":"O00635","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַיָּיפָא\">סַיָּיפָא</a></div>","alt":[]},"19124":{"h":"סִיֵּיר","r":"O00636","html":"<div class=\"sense\">, incorr. for <a href=\"#\" data-headword=\"סִיֵּיד\">סִיֵּיד</a>, v. <a href=\"#\" data-headword=\"סוּד\">סוּד</a></div>","alt":[]},"19125":{"h":"סַיָּירָא","r":"O00637","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּר I ch.)<i>spy</i>. <span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">יהבי ס׳</span> (the fish) place spies (to look out for bait).</div>","alt":["סַיָּיארָא"]},"19126":{"h":"סייתו","r":"O00638","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. III, 12</span> ed. Zuck., read: <span dir=\"rtl\">סיערתו</span>, v. <a href=\"#\" data-headword=\"סָעַר II\"><span dir=\"rtl\">סָעַר</span> II</a></div>","alt":[]},"19127":{"h":"סִיכָּא","r":"O00639","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִכָּא\">סִכָּא</a></div>","alt":[]},"19128":{"h":"סיכָה","r":"O00640","html":"<div class=\"sense\">, Tosef. Erub. XI (VIII), 11 <span dir=\"rtl\">ס׳ של קוצים</span>, read: <a href=\"#\" data-headword=\"סוֹכָה\">סוֹכָה</a>.</div>","alt":[]},"19129":{"h":"סִיכָה","r":"O00641","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּךְ\">סוּךְ</a>) <i>anointing, rubbing with oil.</i> <span class=\"citation\">Yoma VIII, 1</span>. <span class=\"citation\">Y. Bicc. II, 64ᵈ</span>, v. <a href=\"#\" data-headword=\"מָשְׁחָה\">מָשְׁחָה</a>. <span class=\"citation\">Eduy. IV, 6</span> <span dir=\"rtl\">כדי סִיכַת אבר קטן</span>, v. <a href=\"#\" data-headword=\"סוּךְ\">סוּךְ</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"סִיכּוּת\">סִיכוֹת</a>. <span class=\"citation\">Tosef. Sabb. III</span> (<span class=\"citation\">IV), 6</span> <span dir=\"rtl\">כל מיני ס׳</span> all sorts of applications of oil.</div>","alt":[]},"19130":{"h":"סִיכּוּי","r":"O00642","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָכָה\">סָכָה</a>) <i>what is looked for, prospect, hope</i>. <span class=\"citation\">Erub. 21ᵇ</span> <span dir=\"rtl\">בטל סִיכּוּיָם</span> their prospect is frustrated. Sifra Aḥăré, Par. 9, ch. XIII <span dir=\"rtl\">סִיכּוּיִי</span>, v. <a href=\"#\" data-headword=\"סֵבֶר\">סֵבֶר</a>. Ib. <span dir=\"rtl\">אני סִכּוּיְיךָ</span> I (the Lord) am thy hope. <span class=\"citation\">B. Mets. 33ᵇ</span> <a href=\"#\" data-headword=\"סִיכּוּיָא\">סִיכּוּיָם</a>; <span class=\"citation\">Yalk. Is. 371</span> <span dir=\"rtl\">שִׂיכּוּיָין</span>; a. e.</div>","alt":["סִכּ׳"]},"19131":{"h":"סִיכּוּיָא","r":"O00643","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סִיכּוּי\">same</a>. <span class=\"citation\">Targ. Prov. XIX, 18</span> (ed. Wil. <a href=\"#\" data-headword=\"סִכּוּי\">סִכְוְיָא</a>, corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>looks</i>. <span class=\"citation\">Cant. R. to IV, 12</span> <span dir=\"rtl\">סִכּוּיִי</span> (some ed. <a href=\"#\" data-headword=\"סיבויי\">סיבויי</a>, corr. acc.); <span class=\"citation\">Yalk. Num. 773</span> <a href=\"#\" data-headword=\"סבוי\">סבוי</a> (corr. acc.); (Pesik. B’shall., p. 83ᵃ <span dir=\"rtl\">סִכְיוֹנִי</span>); v. <a href=\"#\" data-headword=\"בְּרוּנָא I\"><span dir=\"rtl\">בְּרוּנָא</span> I</a>.</div>","alt":["סִכּ׳"]},"19132":{"h":"סִיכּוּךְ","r":"O00644","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָכַךְ I\">סָכַךְ</a>) </div><div class=\"sense\"><b>1)</b> <i>interlacing, training a creeper so as to be intertwined with another plant</i>. <span class=\"citation\">Tosef. Kil. I, 6</span> <span dir=\"rtl\">אסורה בס׳ וכ׳</span> (Var. <span dir=\"rtl\">לסַכֵּךְ</span>) must not be trained over vegetables; Y. ib. II, end, 28ᵇ <span dir=\"rtl\">ס׳ שאמרו בנוגע</span> (not <a href=\"#\" data-headword=\"סיבוך\">סיבוך</a>) the training spoken of (as forbidden) means real contact.</div><div class=\"sense\"><b>—2)</b> <i>the branches or reeds used for covering the festive booth</i> <a href=\"#\" data-headword=\"סוּכָּה\">(סוּכָּה</a>); <i>thatch-roof</i>. <span class=\"citation\">Succ. I, 9</span> <span dir=\"rtl\">הרחיק את הס׳ וכ׳</span> if he left a space of three handbreadths between the covering and the walls. <span class=\"citation\">Ib. 11</span> <span dir=\"rtl\">לס׳</span> if the reed-mat was intended for covering the Succah. Ib. 4 <span dir=\"rtl\">ואם היה ס׳ וכ׳</span> but if the covering (fit for the Succah) is larger in quantity than they (the vines trained over the Succah); a. e.</div><div class=\"sense\"><b>—3)</b> <i>hedging in</i>. <span class=\"citation\">Gen. R. s. 41</span>; <span class=\"citation\">Num. R. s. 3</span>, beg. <span dir=\"rtl\">חריות לס׳</span> the dry twigs of the palm-tree are useful for hedges (about garden beds; cmp. <span class=\"citation\">Koh. R. to V, 8</span>, quot. s. v. <a href=\"#\" data-headword=\"סִיגָא\">סִיגָא</a>).</div>","alt":["סִכּ׳"]},"19133":{"h":"סִיכּוּלָא","r":"O00645","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְכַל I) <i>intelligence</i>, <i>deliberation</i>. <span class=\"citation\">Targ. Prov. XXI, 16</span>. <span class=\"citation\">Ib. XXIII, 9</span> (some ed. <span dir=\"rtl\">שִׂיכּ׳</span>).</div>","alt":["סִכּ׳"]},"19134":{"h":"סִיכּוּן","r":"O00646","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סָכַן II, v. <a href=\"#\" data-headword=\"סַכָּנָה\">סַכָּנָה</a>) <i>endangering</i>; <span dir=\"rtl\">נפשות ס׳</span> <i>risk of life</i>. <span class=\"citation\">Y. Peah I, 15ᵈ</span> top; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> bot.</div>","alt":["סִכּ׳"]},"19135":{"h":"סִיכּוּף","r":"O00647","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָכַף\">סָכַף</a>) <i>affliction</i>.—Pl. <span dir=\"rtl\">סִיכּוּפִים</span>, <span dir=\"rtl\">סִיכּוּפִין</span>, <a href=\"#\" data-headword=\"סִיכּוּי\">סִכּ׳</a>. Lam. R. introd. (R. Naḥm.) (expl. <span dir=\"rtl\">תאניה ואניה</span>, <span class=\"citation\">Is. XXIX, 2</span>) <span dir=\"rtl\">סִכּוּפֵי ס׳</span> the worst of afflictions; <span class=\"citation\">Yalk. Is. 302</span> <span dir=\"rtl\">סכיפי סכופים</span> (corr. acc.); <span class=\"citation\">Lam. R. to II, 5</span> (ref. to <span class=\"citation\">Lam. II, 5</span>) <span dir=\"rtl\">סכופים סכופים</span> (corr. acc.).</div>","alt":["סִכּ׳"]},"19136":{"h":"סִיכּוּרֵי","r":"O00648","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְכַר II\"><span dir=\"rtl\">סְכַר</span> II</a></div>","alt":[]},"19137":{"h":"סִיכּוּת","r":"O00649","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִכּוּת\">סִכּוּת</a></div>","alt":[]},"19138":{"h":"סִיכְנָא","r":"O00650","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"סִיכְרָא\">סִכְ׳</a>.</div>","alt":["סִיכְנִין"]},"19139":{"h":"סִיכְסָא","r":"O00651","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">סיכסכא</span>; v. <a href=\"#\" data-headword=\"סִכְסֵךְ I\"><span dir=\"rtl\">סכסך</span> I</a>) <i>confusion, folly</i>. <span class=\"citation\">B. Bath. 74ᵃ</span> <span dir=\"rtl\">כל בר בר ח׳ ס׳</span> the whole Bar Bar Ḥanah is (all his stories are) nonsense (Rashi: = <a href=\"#\" data-headword=\"סַכְסַן\">סַכְסַן</a> q. v.).</div>","alt":[]},"19140":{"h":"סִיכְסַן","r":"O00652","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַכְסַן\">סַכְסַן</a></div>","alt":[]},"19141":{"h":"סִיכְרָא","r":"O00653","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְכַר II) <i>grave, burial place</i>. <span class=\"citation\">Keth. 17ᵃ</span>; <span class=\"citation\">Meg. 29ᵃ</span>, v. <a href=\"#\" data-headword=\"אִבּוּלָא\">אִבּוּלָא</a>.—Pl. <span dir=\"rtl\">סִיכְרֵי</span>, <a href=\"#\" data-headword=\"סִיכְרָא\">סִכְ׳</a>. <span class=\"citation\">Sabb. 67ᵃ</span> ז׳ עפרי מז׳ ס׳ Ms. M. (ed. <span dir=\"rtl\">סנרי</span>, Rashi <span dir=\"rtl\">סינרי</span>; Ms. O. <span dir=\"rtl\">סוכרי דבבא</span>; v. Rabb. D. S. a. l. note) seven specimens of earth from seven graves; [oth. opin. from under seven <i>door sockets</i>, v. <a href=\"#\" data-headword=\"סוֹכָרָא\">סוֹכָרָא</a>].—[<span class=\"citation\">Men. 64ᵇ</span>, v. <a href=\"#\" data-headword=\"סוֹכָרָא\">סוֹכָרָא</a>.]</div>","alt":["סִכְ׳ I"]},"19142":{"h":"סִיכְרָא ²","r":"O00654","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Sikhra</i>, near Maḥuza (v. Berl. Geogr., p. 56). <span class=\"citation\">Ab. Zar. 40ᵃ</span> (R. N. <a href=\"#\" data-headword=\"סוּרָא I\">סורא</a>). <span class=\"citation\">Keth. 100ᵇ</span>. <span class=\"citation\">Ḥull. 18ᵇ</span> <span dir=\"rtl\">רב שמן מסוכרא</span> (corr. acc.); <span class=\"citation\">Nidd. 36ᵃ</span> <span dir=\"rtl\">מסכ׳</span>. <span class=\"citation\">Ḥull. 94ᵇ</span>. <span class=\"citation\">B. Mets. 42ᵃ</span>; <span class=\"citation\">Pes. 31ᵇ</span> <span dir=\"rtl\">רפרם מס׳</span>. <span class=\"citation\">B. Mets. 83ᵃ</span></div>","alt":["סִכְ׳ II"]},"19143":{"h":"סִיכְּתָא","r":"O00655","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִכְּתָא\">סִכְּתָא</a>, <a href=\"#\" data-headword=\"סִיכְרָא\"><a href=\"#\" data-headword=\"סִיכְרָא\">סִכְ׳</a>.</a></div>","alt":["סִיכְתָא"]},"19144":{"h":"סִילְוָא","r":"O00656","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִלְוָא\">סִלְוָא</a></div>","alt":["סִילְוִין","סִילְוִים"]},"19145":{"h":"סִילוֹן","r":"O00657","html":"<div class=\"sense\">) m. (σελλίον, σέλλιν) <i>chair</i>. <span class=\"citation\">Lev. R. s. 25</span> <span dir=\"rtl\">ס׳ דדהבא</span> a golden (or gilt) chair.</div>","alt":["סִילִין"]},"19146":{"h":"סִילּוֹן I","r":"O00658","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>rod</i>, <i>thorn</i>. <span class=\"citation\">Koh. R. to VI, 6</span> <span dir=\"rtl\">כס׳ רטוב הפוך</span> (not <span dir=\"rtl\">כסילין</span>) like a green rod inverted (in the direction opposite to that of its knots, v. <a href=\"#\" data-headword=\"חִיזְרָא ²\"><span dir=\"rtl\">חִיזְרָא</span> I</a>); <span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">כסִילָּן</span>.—[<span class=\"citation\">Midr. Till. to Ps. XCII, 13</span> <a href=\"#\" data-headword=\"סִילּוֹן I\">סילון</a> ed. Bub., v. <a href=\"#\" data-headword=\"סוֹל\">סוֹל</a>.]</div>","alt":[]},"19147":{"h":"סִילּוֹן","r":"O00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סָלַל II; cmp. <a href=\"#\" data-headword=\"סוּלָּם\">סוּלָּם</a>) <i>path, gutter</i>, in gen. <i>duct, pipe, tube.</i> <span class=\"citation\">Kil. VII, 1</span> <span dir=\"rtl\">הבריכה בדלעת או בס׳</span> if in sinking a vine he conducted it through gourd shells or through a pipe (so that it could draw no nourishment from the ground which it passed); Y. Bicc. I, 63ᵈ top. <span class=\"citation\">Y. Kil. VII, beg. 30ᵈ</span> <span dir=\"rtl\">ס׳ של חרס</span> an earthen pipe; <span dir=\"rtl\">ס׳ של אבר</span> a leaden pipe. <span class=\"citation\">Sabb. III, 4</span> (<span class=\"citation\">38ᵇ</span>) <span dir=\"rtl\">הכיאו סל׳ של צונן וכ׳</span> (Y. a. Bab. ed. <a href=\"#\" data-headword=\"סִלְסוּל\">סיל׳</a>) they passed a duct of cold water through an arm of the hot springs. <span class=\"citation\">Tosef. Makhsh. II, 2</span> <span dir=\"rtl\">ס׳ של יוצר</span> an earthen water pipe. <span class=\"citation\">Bekh. 44ᵇ</span>, a. e. <span dir=\"rtl\">ס׳ החוזר</span> the urin in the urinary duct which is forced back. <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">כמין ס׳ של אש</span> like a duct of fire; a. fr.—<span class=\"citation\">B. Bath. 99ᵇ</span> <span dir=\"rtl\">בית הס׳</span> comment., v. <a href=\"#\" data-headword=\"קִילוֹן\">קִילוֹן</a>.—Pl. <span dir=\"rtl\">סִילּוֹנוֹת</span>. <span class=\"citation\">Kel. II, 3</span>; <span class=\"citation\">Tosef. Kel. B. Kam. II, 3</span>. Tosef. Erub. IX (VI), 18 <span dir=\"rtl\">ס׳ שבכרכין</span> the culverts in large cities; Y. ib. VIII, end, 25ᵇ. <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">הם קלקלו ס׳ שלהן וכ׳</span> (not <a href=\"#\" data-headword=\"סילונית\">סילונית</a>) they abused their (seminal) ducts, therefore the Lord changed the order (of irrigation) of the world. <span class=\"citation\">Pirké d’R. El. ch. V</span> <span dir=\"rtl\">ס׳ עולין וכ׳</span> (not … <span dir=\"rtl\">נית</span>) ducts rise from the depth to irrigate &amp;c.; <span class=\"citation\">Yalk. Gen. 20</span> (corr. acc.).</div>","alt":["סִלּ׳ II"]},"19148":{"h":"סִילּוֹנָה","r":"O00660","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <i>tube</i>. <span class=\"citation\">Y. Sabb. VI, 8ᵇ</span> top <span dir=\"rtl\">מהו מיתניתיה בההן ס׳</span> how about putting it (the amulet) into a tube (and wearing it on the Sabbath)?</div>","alt":[]},"19149":{"h":"סילונית","r":"O00661","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִילּוֹן I\"><span dir=\"rtl\">סִילּוֹן</span> II</a>.—<span class=\"citation\">Yalk. Lev. 537</span>, v. <a href=\"#\" data-headword=\"סִירוֹנִי\">סִירוֹנִית</a>.</div>","alt":[]},"19150":{"h":"סִילּוּק","r":"O00662","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָלַק\">סָלַק</a>) <i>removal, taking up; being taken away</i>. <span class=\"citation\">Men. 29ᵃ</span>, a. e. <span dir=\"rtl\">סִילּוּקוֹ</span>, v. <a href=\"#\" data-headword=\"סִידּוּר\">סִידּוּר</a>. <span class=\"citation\">Ib. 95ᵃ</span>; <span class=\"citation\">Zeb. 60ᵇ</span> <span dir=\"rtl\">בשעת ס׳ מסעות</span> at the time of packing up (the Tabernacle) for journeying. <span class=\"citation\">Yoma 24ᵃ</span> <span dir=\"rtl\">עבודת ס׳</span> the function of removing (the ashes &amp;c.). <span class=\"citation\">Nidd. 53ᵃ</span> <span dir=\"rtl\">עם ס׳ ידיה</span> at the moment she removed her hands. <span class=\"citation\">Lam. R. to I, 16</span> <span dir=\"rtl\">ס׳ דעת</span> the loss of the senses; <span dir=\"rtl\">ס׳ שכינה</span> the departure of the Divine Presence. <span class=\"citation\">Cant. R. to III, 6</span>; <span class=\"citation\">VIII, 5</span> <span dir=\"rtl\">עילויה … סִילּוּקָהּ וכ׳</span> her (Israel’s) elevation (to her priestly mission) dates from the desert, her removal (from divine grace) dates from the desert; a. fr.—Esp. (<span dir=\"rtl\">ס׳ מן העולם</span>) <i>death</i>. <span class=\"citation\">Lam. R. to I, 15</span> <span dir=\"rtl\">סִילּוּקָן של בחורים</span> the death of youths. <span class=\"citation\">Gen. R. s. 62</span>, a. e. <span dir=\"rtl\">בשעת סילוקן וכ׳</span> when the righteous die &amp;c. <span class=\"citation\">Pesik. R. s. 1</span> <span dir=\"rtl\">בשעת סילוקו מן העולם</span> at the time of his death; a. fr.—Pl. <span dir=\"rtl\">סִילּוּקִים</span>. <span class=\"citation\">Ex. R. s. 52</span> (ref. to <a href=\"#\" data-headword=\"עֲתַק\">עתק</a>, <span class=\"citation\">Ps. XXXI, 19</span>) <span dir=\"rtl\">דברים של ס׳</span> words of removal (‘go away’), i.e. harsh words.</div>","alt":["סִלּ׳"]},"19151":{"h":"סִילֵי","r":"O00663","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"סִלְוָא\">סִלְוָא</a>, <i>thorns</i>, v. <a href=\"#\" data-headword=\"כִּילּוּיָא\">כִּילּוּיָא</a>.</div>","alt":["סִילְיֵי"]},"19152":{"h":"סיליון","r":"O00664","html":"<div class=\"sense\">, <span class=\"citation\">Y. Maasr. V, end, 52ᵃ</span> <span dir=\"rtl\">זרע הס׳</span>, read with Maim. to <span class=\"citation\">Maasr. V, 8</span> <span dir=\"rtl\">העֶלְיוֹן</span>; [R. S. to Maasr. l. c. quotes: <span dir=\"rtl\">סלולין</span>].</div>","alt":[]},"19153":{"h":"סילין","r":"O00665","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. XCII, 13</span>, v. <a href=\"#\" data-headword=\"סוֹל\">סוֹל</a></div>","alt":[]},"19154":{"h":"סִילִיקְרָאוּת","r":"O00666","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a denom. of <span dir=\"rtl\">סִילִיקָר</span> = <span dir=\"rtl\">סִירִי׳</span>, sericarius, sub. textor) <i>silk-weaver’s trade</i>. <span class=\"citation\">Pesik. R. s. 25</span>; [<span class=\"citation\">Midr. Till. to Ps. VIII</span>, ed. Bub. <span dir=\"rtl\">סריקה שירקירים</span> (note: <span dir=\"rtl\">סריקה סירקיריס</span>) read: <span dir=\"rtl\">סִירִיקָרְיוּס</span>, sub. <a href=\"#\" data-headword=\"אוּמָנוּת\">אומנות</a>; <span class=\"citation\">Yalk. Ps. 639</span> <a href=\"#\" data-headword=\"סִירְקִי\">סירקי</a>, <span dir=\"rtl\">סיריקי</span>, read: <a href=\"#\" data-headword=\"סִירִיקָא\">סִירִיקָר</a>].—V. <span dir=\"rtl\">סרקאריס</span>.</div>","alt":["סִילִקְרָ׳"]},"19155":{"h":"סִילְיְתָא","r":"O00667","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִלְיְתָא\">סִלְיְתָא</a></div>","alt":[]},"19156":{"h":"*סִילכָּא","r":"O00668","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Silka</i>. <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">מן בנוי דס׳</span> (not <span dir=\"rtl\">בנו</span>); <span class=\"citation\">Y. Hor. III, 48ᵃ</span> bot. <span dir=\"rtl\">מן אילין דבר סילני</span> (prob. <span dir=\"rtl\">דבי ס׳</span>).</div>","alt":[]},"19157":{"h":"סִולָּן","r":"O00669","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִילּוֹן\">סִילּוֹן</a></div>","alt":[]},"19158":{"h":"סילני","r":"O00670","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*סִילכָּא\">סִילְכָּא</a></div>","alt":[]},"19159":{"h":"סִילסוּל׳","r":"O00671","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"סִילּוּק\">סִלְ׳</a>.</div>","alt":["סִילְסֵל","סִילְעָא"]},"19160":{"h":"סילק׳","r":"O00672","html":"<div class=\"sense\">, <span class=\"citation\">Yoma 10ᵃ</span>, v. <a href=\"#\" data-headword=\"סְלִיק\">סְלִיק</a></div>","alt":[]},"19161":{"h":"סִילְקָא","r":"O00673","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִלְקָא\">סִלְקָא</a></div>","alt":[]},"19162":{"h":"סילקוס","r":"O00674","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְלֶיוְקוֹס\">סְלֶיוְקוֹס</a></div>","alt":[]},"19163":{"h":"סילקי","r":"O00675","html":"<div class=\"sense\">, <span class=\"citation\">Y. B. Mets. VI, 11ᵃ</span> top <span dir=\"rtl\">בס׳</span>, read: <span dir=\"rtl\">בבָסִילְקִי</span>.</div>","alt":[]},"19164":{"h":"סִילָּת","r":"O00676","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַלָּת\">סַלָּת</a></div>","alt":[]},"19165":{"h":"סִילְתָּא","r":"O00677","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְלַת\">סְלַת</a>) </div><div class=\"sense\"><b>1)</b> <i>kindling chip</i>. <span class=\"citation\">B. Kam. 22ᵇ</span>, v. <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> I</a>.—Pl. <span dir=\"rtl\">סִילְתֵּי</span>. <span class=\"citation\">Sabb. 74ᵇ</span> <span dir=\"rtl\">האי מאן דסלית ס׳</span> he who cuts chips (on the Sabbath). Ib. 150ᵇ (ed. <a href=\"#\" data-headword=\"סולתי\">סולתי</a>), v. <a href=\"#\" data-headword=\"סְלַת\">סְלַת</a>. Ib. 20ᵇ</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"בְּקַעַת\">בְּקַעַת</a>, <a href=\"#\" data-headword=\"גַּוָּוזָא I\"><span dir=\"rtl\">גַּוָּוזָא</span> I</a>) <i>log</i>. <span class=\"citation\">Nidd. 66ᵇ</span>; [Rashi refers to <a href=\"#\" data-headword=\"סִילְּתָא II\"><span dir=\"rtl\">סִילְּתָא</span> II</a>].</div>","alt":[]},"19166":{"h":"סִילְּתָא I","r":"O00678","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"סַל\">סַל</a>) <i>bread-basket</i>. <span class=\"citation\">B. Bath. 74ᵃ</span> [read:] <span dir=\"rtl\">שקליתה לסִילְּתָאִי וכ׳</span> I took off my basket with provision &amp;c. <span class=\"citation\">Ab. Zar. 38ᵃ</span>. <span class=\"citation\">Pes. 111ᵇ</span> (prov.) <span dir=\"rtl\">תלא סִילְּתֵיה תלא מזוניה</span> (ed. <a href=\"#\" data-headword=\"סִילְּתָא I\">סילתא</a>, v. Rabb. D. S. a. l. note 90) he who suspends his bread-basket (in the air), suspends his sustenance (brings poverty into the house).</div>","alt":[]},"19167":{"h":"סִילְּתָא II","r":"O00679","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"סוֹל\">סוֹל</a>, <a href=\"#\" data-headword=\"סִלְוָא\">סִלְוָא</a>) <i>rod, thorny twig</i>.—Pl. <a href=\"#\" data-headword=\"סִילְּתָא I\">סִילָּתָא</a>. <span class=\"citation\">Yeb. 63ᵇ</span>, v. <a href=\"#\" data-headword=\"חֲבֶרֶת\">חֲבֶרְתָּא</a>.</div>","alt":[]},"19168":{"h":"סִילְתָא","r":"O00680","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>after-birth</i>, v. <a href=\"#\" data-headword=\"סִלְיְתָא\">סִלְיְתָא</a>.</div>","alt":[]},"19169":{"h":"סילתית","r":"O00681","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַלָּת\">סַלָּת</a></div>","alt":[]},"19170":{"h":"סִים","r":"O00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוּם\">סוּם</a></div>","alt":[]},"19171":{"h":"סִימָא I","r":"O00683","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. <i>saim</i>; v. however, <a href=\"#\" data-headword=\"סִימָא II\">next w.</a>) <i>silver</i>. <span class=\"citation\">Targ. Ps. XII, 7</span>. <span class=\"citation\">Ib. XV, 5</span> (ed. Lag. <span dir=\"rtl\">סָמֵיה</span>). <span class=\"citation\">Targ. Prov. X, 20</span>. <span class=\"citation\">Ib. VIII, 19</span> ed. Lag. (ed. <a href=\"#\" data-headword=\"סַנְיָא III\">סניא</a> for <a href=\"#\" data-headword=\"סַגִּי\">סגיא</a>). <span class=\"citation\">Ib. XVI, 16</span>; <span class=\"citation\">XVII, 3</span> (some ed. <a href=\"#\" data-headword=\"סאניא\">סאניא</a>, <a href=\"#\" data-headword=\"סאניא\">סאסא</a>; corr. acc.); a. fr.; v. <a href=\"#\" data-headword=\"גַּבְיָא I\"><span dir=\"rtl\">גַּבְיָא</span> I</a>.</div>","alt":["סָאמָא"]},"19172":{"h":"סִימָא II","r":"O00684","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סוּם\">סוּם</a>, v. <a href=\"#\" data-headword=\"סְמֵי\">סְמֵי</a>) [<i>tied up, hidden</i>,] <i>treasure</i>. <span class=\"citation\">Targ. Gen. XLIII, 23</span> (O. ed. Berl. <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>; h. text <a href=\"#\" data-headword=\"מַטְמוֹן\">מַטְמוֹן</a>). <span class=\"citation\">Targ. Prov. XXI, 20</span> (h. text <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a>); a. e.—<span class=\"citation\">Y. B. Mets. II, 8ᶜ</span> bot. <span dir=\"rtl\">וס׳ יהוי וכ׳</span> let the treasure (that has been found) belong to both of them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">וס׳ עלת למלכא</span>; <span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">וס׳ סלקא לבי מלכא</span> and the treasure goes to the king’s treasury; Tanḥ. Emor 6; Yalk.Ps. Ps. 727; Pesik. Zakhor, p. 74ᵇ sq. <span class=\"citation\">Y. Shek. III, 47ᶜ</span> top <span dir=\"rtl\">אשכח … ס׳</span> R. A. must have found a treasure (because he looks so bright); Y. Sabb. VIII, beg. 11ᵃ <a href=\"#\" data-headword=\"סִימָה\">סִימָה</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>, <a href=\"#\" data-headword=\"סִימָא II\">סִימָתָא</a>, <a href=\"#\" data-headword=\"סִימְוָאתָא\">סִימָאתָא</a>. Targ. O. Gen. l. c. ed. Berl. (v. supra). <span class=\"citation\">Targ. O. Deut. XXXIII, 19</span> (ed. Vien. <a href=\"#\" data-headword=\"סימא\">סימא</a> sing.; ed. Berl. <a href=\"#\" data-headword=\"סִימָן\">סִימַּן</a>; Y. II <span dir=\"rtl\">סִימָנַיָּא</span>; ed. Vien. <a href=\"#\" data-headword=\"*סִיטְמָנַיָּא\">סִיטְמָנַיָּא</a>). <span class=\"citation\">Targ. Is. XLV, 3</span> (ed. Wil. <a href=\"#\" data-headword=\"סִימָן\">סִמַן</a>); a. fr.—V. <a href=\"#\" data-headword=\"סִימָה\">סִימָה</a>.</div>","alt":["סִימְתָא","סִימְתָה"]},"19173":{"h":"סִימָא III","r":"O00685","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סוּמָא II\"><span dir=\"rtl\">סוּמָא</span> II</a>) <i>mark, sign</i>. <span class=\"citation\">Targ. Y. Ex. XXXII, 20</span>. <span class=\"citation\">Targ. O. Num. XXXII, 3</span>, v. <a href=\"#\" data-headword=\"סוּמָא II\"><span dir=\"rtl\">סוּמָא</span> II</a>.—Esp. pl. <a href=\"#\" data-headword=\"סִימְוָאתָא\">סִימְוָון</a>, <a href=\"#\" data-headword=\"סִימְוָן\">סִימְוָן</a>, <a href=\"#\" data-headword=\"סִימְוָאתָא\">סִימְוָותָא</a>, <a href=\"#\" data-headword=\"סִימְוָאתָא\">סִימְוָאתָא</a>, <a href=\"#\" data-headword=\"סִימְפּוֹן\">סִמְ׳</a> <i>military ensigns, standards</i>. <span class=\"citation\">Targ. Jer. IV, 21</span> (Bxt. <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>). Targ. <span class=\"citation\">Hab. I, 16</span>; a. fr.—Meg. Taan. IX, beg. <span dir=\"rtl\">איתנטלו ס׳ וכ׳</span> the (foreign) insignia were removed from the Temple; expl. ib. as referring to Greek idolatrous emblems <a href=\"#\" data-headword=\"סִימְוָאוֹת\">(סִימְוָאוֹת</a>). [The peculiar application of our w. is caused by the adaptation of σῆμα a. σημαία.]</div>","alt":[]},"19174":{"h":"סימא","r":"O00686","html":"<div class=\"sense\">, Pesik. Vattom., p. 133ᵇ, <a href=\"#\" data-headword=\"ס׳\">ס׳</a>, <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, v. <a href=\"#\" data-headword=\"סִימוֹן\">סִימוֹן</a></div>","alt":[]},"19175":{"h":"סִימַאי","r":"O00687","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"סִימַיי\">סִימַיי</a></div>","alt":[]},"19176":{"h":"סִימְדִּי","r":"O00688","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְמִידָא\">סְמִידָא</a></div>","alt":[]},"19177":{"h":"סִימָה","r":"O00689","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(also <a href=\"#\" data-headword=\"סִימָא I\">סִימָא</a>) = <a href=\"#\" data-headword=\"סִימָא II\"><span dir=\"rtl\">סִימָא</span> II</a>, <i>treasure</i>. <span class=\"citation\">Cant. R. to IV, 12</span> (ed. Wil. a. oth. <a href=\"#\" data-headword=\"סימא\">סימא</a>); <span class=\"citation\">Yalk. Ex. 225</span>. Y. Ab. Zar. II, 41ᵈ top (play on <span dir=\"rtl\">תשים</span>, <span class=\"citation\">Ex. XXI, 1</span>) <span dir=\"rtl\">מה הס׳ הזאת וכ׳</span> as a treasure is not revealed to every one &amp;c.; <span class=\"citation\">Cant. R. to I, 2</span> <a href=\"#\" data-headword=\"שִׂימָה\">שִׂימָה</a>. <span class=\"citation\">Lev. R. s. 17</span>; a. fr.—<a href=\"#\" data-headword=\"סִימָה\">סִימָה</a> ch., v. <a href=\"#\" data-headword=\"סִימָא II\"><span dir=\"rtl\">סִימָא</span> II</a>.</div>","alt":[]},"19178":{"h":"סִימְוָאוֹת","r":"O00690","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"><i>ensigns</i>, v. <a href=\"#\" data-headword=\"סִימָא III\"><span dir=\"rtl\">סִימָא</span> III</a>.</div>","alt":[]},"19179":{"h":"סִימְוָאתָא","r":"O00691","html":"<div class=\"sense\">, ch. <a href=\"#\" data-headword=\"סִימְוָאוֹת\">same</a>, v. <a href=\"#\" data-headword=\"סִימָא III\"><span dir=\"rtl\">סִימָא</span> III</a></div>","alt":["סִימְוָון","סימְוָותָא","סִימְוָן"]},"19180":{"h":"סִימּוּי","r":"O00692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָמָה\">סָמָה</a>) <i>making blind</i>. <span class=\"citation\">Lev. R. s. 6</span> <span dir=\"rtl\">זה ס׳ עינים וכ׳</span> this refers to the blinding of the eyes which they executed on &amp;c.; <span class=\"citation\">Yalk. ib. 675</span>; <span class=\"citation\">Yalk. Ez. 357</span>.</div>","alt":[]},"19181":{"h":"סִימְוָן","r":"O00693","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימְוָאתָא\">סִימְוָאתָא</a></div>","alt":[]},"19182":{"h":"סִימוֹן","r":"O00694","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (Σίμων) <i>Simon</i>, name of several Amoraim. <span class=\"citation\">Y. Sabb. VIII, 11ᵃ</span> bot.; <span class=\"citation\">Y. Shek. VIII, beg. 51ᵃ</span> (also <a href=\"#\" data-headword=\"שִׁמְעוֹן\">שִׁמְעוֹן</a>). <span class=\"citation\">Y. Succ. IV, beg. 54ᵇ</span>; a. fr.—<span class=\"citation\">Y. Pes. IX, beg. 36ᶜ</span>. <span class=\"citation\">Y. Sabb. VII, 9ᵃ</span> top; a. fr.—V. Fr. M’bo, p. 118ᵃ.—<span class=\"citation\">Lam. R. to IV, 15</span>; (Pesik. Vatt., p. 133ᵇ <a href=\"#\" data-headword=\"סימא\">סימא</a>).</div>","alt":[]},"19183":{"h":"סִימוּנָא","r":"O00695","html":"<div class=\"sense\"><i>Simuna of the marshland</i>, name of <i>a reed</i> (v. Löw Pfl. p. 344). <span class=\"citation\">Ḥull. 16ᵇ</span> (Ar. <a href=\"#\" data-headword=\"סִימוֹנְיָא\">סִימוּנַיָּא</a> a. <span dir=\"rtl\">סִימוּנִיתָא</span>; v. Koh. Ar. Compl. s. v.).</div>","alt":["ס׳ דְאַגְמָא"]},"19184":{"h":"סִימוֹנַאי","r":"O00696","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימוֹנְיָא\">next w.</a></div>","alt":["סִימוֹנִי"]},"19185":{"h":"סִימוֹנְיָא","r":"O00697","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Σιμωνίας, Joseph. Vita 24) <i>Simonia</i> (Semûniye), west of Nazareth. <span class=\"citation\">Gen. R. s. 81</span>, beg.; Tanḥ. Tsav 5; Y. Yeb. XII, end, 13ᵃ (not <span dir=\"rtl\">כימ׳</span>); <span class=\"citation\">Yalk. Prov. 964</span> <a href=\"#\" data-headword=\"סִימוֹנַאי\">סימונאי</a>.—<span class=\"citation\">Nidd. 24ᵇ</span> <a href=\"#\" data-headword=\"סִימוֹנַאי\">סימוני</a>.</div>","alt":["סִימוֹנְיָיא"]},"19186":{"h":"סִימּוּק","r":"O00698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְמֵק\">סְמַק</a>) </div><div class=\"sense\"><b>1)</b> <i>reddish</i>. <span class=\"citation\">Targ. O. Gen. XXV, 25</span> (ed. Vien. <a href=\"#\" data-headword=\"סִמּוּק\">סִמּוֹק</a>). Targ. ib. 30 (O. ed. Vien. <a href=\"#\" data-headword=\"סְמוֹקְרִי\">סִמּוֹ׳</a>); a. e.—<span class=\"citation\">Y. Dem. II, beg. 22ᵇ</span> <span dir=\"rtl\">ס׳ הוא</span> (not <a href=\"#\" data-headword=\"ט׳\">ט׳</a>) it is reddish (blighted), v. <a href=\"#\" data-headword=\"*אַכְתַּר\">אַכְתַּר</a>.</div><div class=\"sense\"><b>—2)</b>  (noun) <i>red meat</i>. <span class=\"citation\">Y. Ter. I, 40ᵇ</span> [read:] <span dir=\"rtl\">אכים גו ס׳</span> (they gave him) dark wine after red meat; <span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span> <span dir=\"rtl\">סָמִיק</span>.—[<span class=\"citation\">Lam. R. to IV, 3</span> <span dir=\"rtl\">סימוקן</span> (ed. Wil. <span dir=\"rtl\">סמקון</span>), read: <span dir=\"rtl\">סַמְּקִין</span>, v. <a href=\"#\" data-headword=\"סַמְקָא\">סַמְּקָא</a>.]—<i>Fem</i>. <a href=\"#\" data-headword=\"סִמּוּקְתָּא\">סִימּוּקְתָּא</a>. <span class=\"citation\">Targ. O. Num. XIX, 2</span> (ed. Vien. <a href=\"#\" data-headword=\"סִמֻּקְתָּא\">סִמֻּקְתָּא</a>); a. e.</div>","alt":["סִימּוּקָא","סִמּ׳"]},"19187":{"h":"סִימְטָא","r":"O00699","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">סמט</span>, Saf. of <span dir=\"rtl\">מוט</span>, cmp. <span dir=\"rtl\">שמט</span>; v. <a href=\"#\" data-headword=\"*אִיסְמְטָא\">אִיסְמְטָא</a>) <i>recess, alley</i> adjoining an open place to which merchants retire to transact business; <i>market-stand</i> under a colonnade. <span class=\"citation\">Keth. 84ᵇ</span>, opp. <span dir=\"rtl\">רשות הרבים</span>. <span class=\"citation\">Pes. 50ᵇ</span>; <span class=\"citation\">Tosef. Bicc. II, 16</span> <span dir=\"rtl\">תגרי ס׳</span> traders in market-stands. Sifra B’har, ch. VII, Par. 6, [read as:] <span class=\"citation\">Yalk. Lev. 667</span> (ref. to <span class=\"citation\">Lev. XXV, 42</span>) <span dir=\"rtl\">לא יעשה ס׳ ויעמידם על וכ׳</span> one must not put up a stand and put them on the auction stone; a. e.—<i>Pl.</i> (h. form) <a href=\"#\" data-headword=\"סִימְטָיוֹת\">סִימְטָיוֹת</a>. <span class=\"citation\">Y. Sabb. I, 2ᵈ</span> bot. <span dir=\"rtl\">ס׳ שבין העמודים</span>; (Bab. <span class=\"citation\">ib. 7ᵃ</span> only <span dir=\"rtl\">בין העמודים</span>) the stands between the columns.</div>","alt":["סִמְ׳ I"]},"19188":{"h":"סִימְטָא ²","r":"O00700","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סִימְטָא\">preced.</a>; cmp. Lat. abscessus) <i>abscess, carbuncle</i>. <span class=\"citation\">Ab. Zar. 28ᵃ</span> bot. <span class=\"citation\">Sabb. 67ᵃ</span></div>","alt":["סִמְ׳ II"]},"19189":{"h":"סִימְיוֹן","r":"O00701","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"סִימְפּוֹן\">סִמְ׳</a>.</div>","alt":["סִימְיוֹנָא"]},"19190":{"h":"סִימְטָיוֹת","r":"O00702","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימְטָא ²\"><span dir=\"rtl\">סִימְטָא</span> I</a></div>","alt":[]},"19191":{"h":"סימיא","r":"O00703","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Lev. XIX, 14</span> ed. Vien., read: <a href=\"#\" data-headword=\"סָמֵי\">סַמְיָא</a>.</div>","alt":[]},"19192":{"h":"סִימַיי","r":"O00704","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Simay</i>, </div><div class=\"sense\"><b>1)</b>  a Tannai. <span class=\"citation\">Kidd. 64ᵃ</span>; <span class=\"citation\">Keth. 29ᵇ</span>. <span class=\"citation\">Tosef. Sabb. XII</span> (<span class=\"citation\">XIII), 14</span>; Y. ib. XII, beg. 13ᶜ; a. e.</div><div class=\"sense\"><b>—2)</b>  an Amora. Ib. VII, 9ᶜ top. <span class=\"citation\">Y. Maas. Sh. II, 53ᵇ</span>; <span class=\"citation\">Yeb. 74ᵃ</span> <a href=\"#\" data-headword=\"סִמְיָא\">סִמְיָא</a>.—Pesik. Vattom. p. 134ᵃ <span dir=\"rtl\">ר׳ ס׳ בר קוסי</span> (v. Bub. a. l. note 81); <span class=\"citation\">Yalk. Is. 333</span> <span dir=\"rtl\">ר׳ סימון</span>.</div>","alt":["סִימַאי"]},"19193":{"h":"סימין","r":"O00705","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Shebi. I, 11</span>, v. <a href=\"#\" data-headword=\"סוּם I\"><span dir=\"rtl\">סוּם</span> I</a></div>","alt":[]},"19194":{"h":"סִימִיסִירִיקִין","r":"O00706","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (semiserica) <i>half-silken garments</i>. <span class=\"citation\">Koh. R. to I, 7</span> (not … <a href=\"#\" data-headword=\"קוּן\">קון</a>)</div>","alt":["סִימִיסרִ׳"]},"19195":{"h":"סִימִירוֹן","r":"O00707","html":"<div class=\"sense\"> (σήμερον = τήμερον) <i>to-day</i>. <span class=\"citation\">Y. Keth. II, 26ᶜ</span> bot. <a href=\"#\" data-headword=\"שמירון\">שמירון</a> (Ar. <a href=\"#\" data-headword=\"סמרון\">סמרון</a>, corr. acc.), interch. with <span dir=\"rtl\">יום דין</span> a. <span dir=\"rtl\">היום</span>.</div>","alt":[]},"19196":{"h":"סִימְלוֹן","r":"O00708","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"סִימְפּוֹן\">סִמְ׳</a>.</div>","alt":["סִימְלָק"]},"19197":{"h":"סִימָנִים","r":"O00709","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְמָן\">סַמְמָן</a></div>","alt":["סִימְמָנִין"]},"19198":{"h":"סִימָן","r":"O00710","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סוּם I, v. <a href=\"#\" data-headword=\"סוּמָא II\"><span dir=\"rtl\">סוּמָא</span> II</a>) <i>mark, sign; omen; symptom; cipher, mnemotechnical note</i>. <span class=\"citation\">B. Mets. 22ᵇ</span> <span dir=\"rtl\">ס׳ העשוי לידרס לא הוי ס׳</span> a mark (on a lost object) which is liable to be effaced by treading upon it, is no mark (by which one can claim it). <span class=\"citation\">Ib. 23ᵃ</span> <span dir=\"rtl\">ס׳ הבא מאליו</span> an accidental mark (not made purposely). <span class=\"citation\">Ib. 24ᵇ</span> <span dir=\"rtl\">נתן בה ס׳</span> he told a sign (by which he identified it). <span class=\"citation\">Ib. 27ᵇ</span> <span dir=\"rtl\">ס׳ מובהק</span> a distinguished (specific) mark of identification.—<span class=\"citation\">Ber. 24ᵇ</span> <span dir=\"rtl\">ס׳ יפה</span> an auspicious omen. <span class=\"citation\">Taan. 30ᵇ</span> <span dir=\"rtl\">אינו רואה סִימַן ברכה וכ׳</span> will never see a sign of blessing (will labor without success).—<span class=\"citation\">Kidd. 16ᵇ</span> <span dir=\"rtl\">דברי הכל ס׳</span> all agree that it is a sign of puberty. <span class=\"citation\">Ḥull. 61ᵃ</span> <span dir=\"rtl\">עוף הבא בס׳ אחד</span> a bird which has one of the four marks of cleanness. <span class=\"citation\">Erub. 54ᵇ</span> (ref. to <a href=\"#\" data-headword=\"שִׂימָה\">שימה</a>, <span class=\"citation\">Deut. XXXI, 19</span>) <span dir=\"rtl\">א&quot;ת שימה אלא סִימָנָהּ</span> read not <i>simah</i> (put it), but <i>simanah</i> (its mark, catchwords). Ib. 54ᵃ, a. fr. (editorial gloss) <span dir=\"rtl\">ס׳ וכ׳</span> the catchwords for the subject following are &amp;c.; a. v. fr.—Trnsf. <i>the organ, the cutting of which is an indication that the animal has been slaughtered according to the ritual, the windpipe</i> and <i>the gullet</i>. <span class=\"citation\">Ḥull. 27ᵇ</span> <span dir=\"rtl\">הכשרו בס׳ אחד</span> is made ritually fit for eating by the cutting of either of the organs; a. fr.—Pl. <a href=\"#\" data-headword=\"סִימָנִים\">סִימָנִים</a>, <a href=\"#\" data-headword=\"סִימָנִים\">סִימָנִין</a>. <span class=\"citation\">B. Mets. 27ᵃ</span>, a. fr. <span dir=\"rtl\">ס׳ דאורייתא וכ׳</span> is identification by marks a Biblical or a rabbinical institution? <span class=\"citation\">Ib. II, 5</span> <span dir=\"rtl\">שיש בה ס׳</span> which can be identified by signs. <span class=\"citation\">Ib. 7</span> <span dir=\"rtl\">אמר אבידה ולא אמר סִימָנֶיהָ</span> if he states the object he has lost, but cannot describe it.—<span class=\"citation\">Kidd. 4ᵃ</span>, a. fr. <span dir=\"rtl\">סִימָנֵי נערות</span> evidences of puberty (v. <a href=\"#\" data-headword=\"נַעֲרוּת\">נַעֲרוּת</a>). <span class=\"citation\">Ib. 16ᵃ</span> <span dir=\"rtl\">קונה את עצמה בס׳</span> acquires herself (becomes free) on showing evidences of puberty. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">אין ס׳ באיש</span> a man-servant does not go out free on reaching puberty. Ḥull.III, 6 <span dir=\"rtl\">סימני בהמה וכ׳</span> the distinguishing marks of cleanness in animals &amp;c. Ib. 27ᵇ <span dir=\"rtl\">לחייבו בשני ס׳</span> to make it obligatory to cut both organs (the windpipe and the gullet). Ib. 44ᵃ <span dir=\"rtl\">עיקור ס׳</span> the case of the organs’ being torn loose before cutting. <span class=\"citation\">Erub. 54ᵇ</span> <span dir=\"rtl\">אין התורה … בס׳</span> knowledge of the Law can be obtained only by means of signs (rubrication by catchwords). <span class=\"citation\">Ib. 21ᵇ</span> <span dir=\"rtl\">סימני טעמים</span> notes of accentuation (v. <a href=\"#\" data-headword=\"טַעַם\">טַעַם</a>); a. fr.</div>","alt":[]},"19199":{"h":"סִימָן ²","r":"O00711","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. XXX, 39</span>. <span class=\"citation\">Targ. Y. II, Num. XVII, 3</span> (h. text <a href=\"#\" data-headword=\"אוֹת I\">אוֹת</a>).—<span class=\"citation\">Targ. Y. Ex. VII, 17</span> (fem.); a. fr.—<span class=\"citation\">Targ. Jer. IV, 21</span>, v. <a href=\"#\" data-headword=\"סִימָא III\"><span dir=\"rtl\">סִימָא</span> III</a>.—<span class=\"citation\">Ḥull. 96ᵃ</span> <span dir=\"rtl\">פלניא דהאי סִימָנֵיה וכ׳</span> that person whom I know by such and such a mark has killed a man; opp. <span dir=\"rtl\">טביעות עינא</span>, v. <a href=\"#\" data-headword=\"טְבִיעוּתָא\">טְבִיעוּתָא</a>. <span class=\"citation\">Ib. 95ᵇ</span>. <span class=\"citation\">Ker. 6ᵃ</span>; <span class=\"citation\">Hor. 12ᵃ</span> <span dir=\"rtl\">ס׳ מילתא היא</span> there is something in an omen. <span class=\"citation\">Y. Snh. I, 18ᶜ</span> bot. <span dir=\"rtl\">מיעקר אף אהן ס׳</span> to abolish even this (last) distinction of Judæa.—<span class=\"citation\">Ḥull. 46ᵃ</span> <span dir=\"rtl\">וסִימָנָיךְ וכ׳</span> and thy sign (the words by which to remember) be &amp;c. <span class=\"citation\">Sabb. 66ᵃ</span> <span dir=\"rtl\">וס׳ סמך סמך</span> and the mnemonical sign is Samekh Samekh (i.e. <span dir=\"rtl\">ר׳ יוסֹי אוסֹר</span> R. José is he that forbids); a. v. fr.—Pl. <a href=\"#\" data-headword=\"סִימָנִים\">סִימָנִין</a>, <span dir=\"rtl\">סִימָנַיָּא</span>. <span class=\"citation\">Targ. Y. I Gen. I, 14</span>. <span class=\"citation\">Targ. Y. Ex. XXI, 7</span> <span dir=\"rtl\">בס׳</span> with signs of puberty. <span class=\"citation\">Targ. Y. Num. XIX, 3</span> <span dir=\"rtl\">תרין ס׳</span> the windpipe and gullet (v. <a href=\"#\" data-headword=\"סִימָן\">preced.</a>); a. e.—<span class=\"citation\">B. Mets. 27ᵇ</span>; a. fr.</div>","alt":["סִימָנָא I"]}};
